/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20061016-4","meetingId":"h18-c-settlement","date":"2006年10月16日","dateIso":"2006-10-16","committee":"決算特別委員会","time":"午前１０時０３分～午後５時４７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"最初に１０３ページの生活安全推進事業、その後で１０６ページの防災対策費について質問していきます。最初に生活安全の方なんですけれども、平成１７年度の新規事業としては近隣セキュリティシステムですとか、防犯設備整備、防犯カメラ、それとわんぱくパトロール等、年々創意工夫がなされて、実りを増しているところだと思います。","respondent":"金子生活安全担当課長","answer":"これから安心・安全マニュアル等を作成するような機会があれば、作成元であるＰＴＡ、教育委員会、まちづくり事業部と連携をさらに図りまして大いに活用していきたいと、こう考えております。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、今年度から開校されました日野学園なんですけれども、開校時には校門の入口付近では前面道路に信号がついていなかったんですけれども、開校をして、やはりそういう通学時間等、かなりスピードを上げた車が往来していて、危険ではないかというような声もあったり、そういうところはスピーディーな対応が求められて、現在では信号機がついたり、そういった通学路等、その辺のところも重点を置いて。","respondent":"金子生活安全担当課長","answer":"お話のありました用途変更４カ所につきましては、警視庁の管理のもと、仮称ではありますけれども、地区安全連絡所として活用すると聞いております。ここにつきましては、警視庁の動きを見ながら具体的な対策を考えていきたいと思います。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"生活安全サポート隊の強化等、よろしくお願いしたいと思うんですけれども、例えば環状６号線等、東京都が道路を拡幅するにあたりまして用地買収をしている、進んでいるところ、進んでいないところありますけれども、そういった進んでいて、単管パイプによる柵等で土地が遊んでいるような状態、そういったスペース等が活用できないか、これはたまたま品川区内の大崎警察署が今、建て替えをしておりまして。","respondent":"金子生活安全担当課長","answer":"したがいまして、新たに空き地に防犯拠点等を整備して、それを運用するということは困難かと思われますけれども、警視庁の動きを見ながら、そういった敷地等をうまく活用できないかという方法をこれから検討して、警視庁にも働きかけをしていきたいと考えております。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"警察との連携というところでちょっとお聞かせいただきたいと思うんですけれども、今年の６月より施行されました国の放置駐車違反なんですけれども、法律の整備のことでは言いようがありませんが、都内１２区４３署での取り締まりということで実施をされておりますが、区内での状況を、就労者、消費者、景気の動向等、メリット、デメリットを検証し、それを警察へ伝えていくなどの考え。","respondent":"松嶋交通安全担当課長","answer":"そういったことで、今後の物流の関係はいろいろ支障が出る可能性も当然あるわけですので、これは区としては警察と連携をとっていきまして、いろいろな対応をとっていきたいと、このように考えております。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"危機管理の対応、連携というところで、危機管理室も設置をされて、例えばこの間、西五反田３丁目でもがけ崩れがありましたし、そういったものにいち早く品川区が対応されたという、本当に地域からもそういう声が挙がっておりますが、そうしたいろいろな品川区の危機管理室はじめ防災課等、その連携について、平成１７年度からということで、その辺のところを教えていただきたいのと、あと。","respondent":"桑村危機管理室長、久保田防災課長","answer":"危機管理関係について、私からお答え申し上げたいと思います。平成１７年１月に危機管理室を設置いたしまして、いわゆる不測の事態というんでしょうか、通常では予測できない事態ということに対処するということでやってまいりました。全部の地区というわけではないんですけれども、それぞれの協議会の中でまた検討していきたいと考えています。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"１０４ページの広報費、情報公開に関連して質問させていただきたいと思います。前年度１年間で陳情数は大体どれぐらいになったのかということと、また、その陳情に基づいて、あるいはそうでなくても、区の部課長との対話というか、話し合いが年間どれぐらいあったのか、それをまず教えていただきたいと思います。","respondent":"中川原広報広聴課長","answer":"そのうち、他の部課長とどういう形で話し合われているかということですが、私どもは区民の声をいただきますと、所管に回答依頼をしたり、処理依頼をいたしますので、その間、所管で必要に応じて区民の声に対して部課長が説明されたりしていることと思います。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"２４０件とＥメールで７００件、約１,０００件というんですけれども、この寄せられた１,０００件の回答というのは、大体すべてにわたって回答されているんでしょうか。","respondent":"中川原広報広聴課長","answer":"２４０件の中でも、答えが欲しいという内容と、それから提案、参考送付という内容もありますので、そういった形で言いますと、その中で回答をさせていただいているのは２４０件です。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"そうすると区の基本姿勢というのは、区民の声が出されて、回答可能なもの、回答が求められているものについては回答していくという姿勢なんでしょうか。","respondent":"中川原広報広聴課長","answer":"住所氏名がありまして回答可能なものについては、すべて回答をします。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"それは区民個人であっても、区内にあるさまざまな住民運動団体だとか、町会なんかも入るかもしれませんけれども、それは団体であっても問わずということでしょうか。","respondent":"中川原広報広聴課長","answer":"お答えができるような状況になったときにお答えするという形で回答します。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"私がきょう前段でこれを聞いたのは、今年度ですね、４月に入ってから、東京春闘共闘会議が公契約条例など勤労施策充実のための懇談会をやる、そのために懇談にあたっての事前アンケート調査というのを東京３６の三多摩を含めたすべての自治体にアンケートと懇談の申し入れを行ったんですけれども、これに対してはどのような態度をとったんでしょうか。","respondent":"中川原広報広聴課長","answer":"それについては区民の声という形では受け付けておりません。広報広聴課にはそうしたご要望が来ていません。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"どこかの所管にこのアンケートと、それから懇談の申し入れが回ったと思うんですが、それはいかがでしょうか。受け取った所管で回答願いたいと思います。","respondent":"桑村総務課長","answer":"どういう形のものについて、あるいはアンケートを答える、あるいはそういう懇談に応じるかというのは、中身を見せていただいて、そのことについてお話ができるような状況であれば懇談ということを設定いたしますし、また。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"区としてこれを受けるかどうか、どこかで判断をして回答をした。これは１つひとつみんな回答できますよね。それなのに回答しないで、しかもアンケート用紙を突き返したというのはどういうわけなんでしょうか。どこか知っている方が絶対にいるはずですから、答えていただきたいと思います。","respondent":"桑村総務課長","answer":"１つの何か考え方のある団体からの一定のものについての答えの仕方というのは、お答えしない場合もありますし、特に懇談が伴っているものについては、いわゆるそのことをお答えすることが懇談に結びつくというようなことと判断すれば。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"これは必ずこれを受け取って、トップまで上がったかどうかは知らないけれども、答えるべきか、答えるべきでないかという検討がされているはずですよ。それは覚えがないんですか。これだけの全都調査を１つの団体がやっているのに。私は考えられない。部長クラスだとどうですか。自分の我が身に照らしてこうした問題が、総務部長、どうですか、覚えがあったらちょっとお答え願いたいんですが。","respondent":"本間総務部長","answer":"総務課長が答弁したとおり、アンケート、それからまた懇談を前提としたようなアンケートの場合は、区のそれぞれの考えで対処するケースは一般論としてあろうかと思いますが、今の具体的なお話につきましては、私も記憶が定かではございません。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"全都的に品川区の対応はおかしいと春闘共闘の中では話題になっているそうです。そうなっているのに、担当課長、部長が記憶が定かでないというのが私はちょっと解せないと思います。それで、改めてまた来年やるかもしれませんけれども、春闘共闘が労働条件の改善、とりわけ不安定雇用を少しでも前に進めようとしたこの種のアンケートが出てきた場合に、今後は回答するんでしょうか、しないんでしょうか。","respondent":"本間総務部長","answer":"出されました時点につきまして、中身をよく読みまして、区としての態度を決めさせていただきたいと、さよう考えているところです。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょうど私どもは団の会議を行っていまして、館内一斉に放送が流れたので、会議ちょっと中断といってみんなやめて一斉に耳を傾けて、私はノートをとりながら聞かせていただいたんですが、特にその中で高橋前区長の継承という面と、濱野区長のもう一歩進んだ政治姿勢として、区民の声を聞いて進めたい、それから政策決定の段階から区民の声を聞いて、それを区政に反映することを貫きたい。","respondent":"濱野区長","answer":"これを特段変えるということではございません。ただ、区民の声をしっかり聞くというのは、私も含め、所管も含め、さまざまなところから情報をきちっと収集をして、あるいはまた実行する段につきましても、地域の実情というのをよく知った上で行うという基本方針を述べたと。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問・要望","question":"もちろん住民運動、区民の運動であっても、業務上設定した時間に会うことができなかったり、そういうのはいろいろあると思うので、そこは調整の範囲ですけれども、基本的に区民のそういう申し入れ、区民の声、話し合いについては極力受ける姿勢に立ってほしいと思いますが、改めてもう一度聞かせていただきたいと思います。","respondent":"濱野区長","answer":"過去、品川区においては、自分たちの要求が通らなければとことんまで要求を続けるという団体もおられたわけで、それはやはり団体の方が良識ある行動をとられること、あるいは区政に対して一定の。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは過去の問題ですからこれ以上言いませんけれども、そうしたものまで今までの区政の中では、きっと意に沿わない団体だったんでしょう。これから進めるにあたって、その上で品川区の情報公開の手数料はやっぱり他区と同じように無料にすべきだと、区民の声を聞きたいという区長の姿勢では、そこを私はぜひやってほしいと思いますが、いかがでしょうか。","respondent":"濱野区長","answer":"情報公開の手数料については従来どおりと考えております。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は前、これを明らかにしたことがあるんですけれども、もし変わっていたら担当から指摘していただきたいんですが、東京２３区で情報公開手数料を、区民が要求をした資料で有料化にしているのは、当時、中央区と品川区だけだと、そのときの答弁では、今、５区ぐらいが有料化を検討して、もっと広がる方向ですという答弁を最後に、私はその後はやっていないんですけれども。","respondent":"中川原広報広聴課長","answer":"品川区の考え方としましては、一定の職員の労力等々がかかりますので、受益者負担という考えに立ちましてやらせていただいています。なお、品川区の場合、何人も情報公開請求ができますので、参考までに申し上げますと、区外の事業者と区外の方の請求が７割という現状です。","id":"exchange-018"},{"speaker":"沢田委員","kind":"意見","question":"受益者負担というのを今まで言いましたけれども、情報を区民に公開をするというのは、区民の権利ですよね。権利の保障、それからもう１つ、だれが受益者かというのは、情報を区民に渡すことによって受益は区民自身が受けると思います。新しい区長のもとでぜひ再検討をすることを要請して、時間ですので終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"私は１０２ページの庁舎等維持管理費、１０４ページの「しながわガイド」、１０６ページの防災対策費、時間がありましたら１０３ページの生活安全推進事業についてお伺いしたいと思います。初めに庁舎等維持管理費なんですが、庁舎内の掃除、カーペット、じゅうたん、また窓ガラス、その辺の掃除はこの庁舎維持管理費の中でよろしいんでしょうか。","respondent":"中島経理課長","answer":"庁舎内の清掃等につきましては、こちらの庁舎管理維持費に含まれておるものです。","id":"exchange-020"},{"speaker":"武内委員","kind":"確認","question":"一応確認させていただいて。そういう経緯がありました。万が一、もしそういうところから落下して事故が起きた場合の区の責任というのは何か問われちゃうんでしょうか、どうなんでしょうか。","respondent":"中島経理課長","answer":"基本的にはもちろん清掃業者と契約に基づいて執行しているわけですけれども、契約の中では当然清掃作業員の方が事故等、けがをした場合につきましては、その事業者の責任で対応するということになってあります。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"１０４ページの「しながわガイド」に移りますけれども、これはこの間、新聞にも出ていましたけれども、「しながわガイド」について、今期におきましては、これは２万５,０００部で７００万余のお金で経費を使って作成されていますけれども、目黒区ではある新聞社と提携しまして、その新聞社が区内のいろいろなお店とか、企業とか、そういうところの広告をとっていただいて、区は行政の情報の提供と。","respondent":"中川原広報広聴課長","answer":"「しながわガイド」につきましては、今回、その方法をいろいろな点を考えさせていただいて、とらなかったわけなんですけれども、やはり広告料というのは、きのうもご指摘がありましたように、今後考えていかなきゃいけないことだと思いますので、今回は読みやすさとか。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして、１０６ページの防災対策費ということで、ちょっとどこに入るかわからないので、一応防災対策費の中でお願いしたいんですが、町会の防災倉庫、これについてお聞きしたいんですけれども、今、これについての防災倉庫自体の建築費ですとか、また防災倉庫を設置する場所についての区のバックアップというか、そういうのはどうなっていますでしょうか。","respondent":"久保田防災課長","answer":"町会のいわゆる防災倉庫ですけれども、現在、町会が独自に土地も、それから建物も確保している町会は８０町会ぐらいあるんですけれども、町会全体では２０３町会というのが私どもに登録しているところなんですけれども、そのほか。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問・要望","question":"１３５町会で持っているということで、いろいろな条件はあると思うんですけれども、さらに各町会で持てるようなまたバックアップをしていただきたいと思うんですが、実は、ちょっと町会名はあれなんですけれども、私の地域のお世話になっている町会で、今、防災倉庫がある場所が民間の駐車場の中で、その民間の会社に無償で一応場所をお借りして、そこの防災倉庫を置いているわけですが、そこの企業の方も。","respondent":"久保田防災課長","answer":"私どもとしては近くに手ごろな公園等があって、そこに設置することが可能であれば、私どもも町会と一緒になって、そういったところについていろいろご相談を受けて、そして調査をして、なおかつやっていきたいなというふうには考えているところです。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"ぜひ、またその際にはよろしくお願いしたいと思うんですが、その場合、倉庫はもう建物というか、プレハブみたいなのがあるんですけれども、その場合の移動する費用なんかはやっぱりこれは町会が負担するんでしょうか。","respondent":"久保田防災課長","answer":"一緒になってものを外したり、大体業者にお願いすればやっていただくケースが大半なんですが、私どももお手伝いをして移設するということもありますので、その辺は町会と十分に相談していきたいと考えています。","id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"最後に１０３ページの生活安全推進事業の中でお伺いしたいと思うんですけれども、いろいろ取り組まれているということで、例えばひったくりですとか、痴漢ですとか、こういったものについてもこの生活安全の中でやられると思うんですけれども、特にひったくり等ですけれども、そういったものというのは、区内の中である程度そのポイントといいますか、ひったくりされやすいところとか。","respondent":"金子生活安全担当課長","answer":"性犯罪は公にしておりませんけれども、ひったくりに関しましては、いわゆる駅から離れて、暗がりで、比較的狭い通り、それで女性を対象とした事件がほとんどです。","id":"exchange-026"},{"speaker":"武内委員","kind":"質問","question":"それで、ひったくりの多発地域だよと、ここで多発していますよというものをその自治体は歩道にはってあるんです。そういったものを例えば区で今後工夫していくというのはどうなんでしょうか。","respondent":"金子生活安全担当課長","answer":"道路標示となりますと、いいところ、悪いところ、それぞれあると思うんですけれども、うつむきながら歩くということになると、なかなか目立たないような点もありますので、その点はちょっと検討して、最も効果ある方法を見つけていきたいと考えています。","id":"exchange-027"},{"speaker":"川西委員","kind":"意見","question":"１つは戸籍住民関連が１点、次にコミュニティ組織づくり、地域センター関係の活動に関して、ページは１０３ページ、次に１０４ページの歩きたばこの関係、それから１０６ページの区民保養所、時間があったらまだ用意してあります。そういう気持ちが私なんかに寄せられながらも、やはり子どもの権利最優先という立場から、今回とった措置についてお考えをひとつ聞きたいと思います。","respondent":"濱野区長","answer":"もう１つ、お子様のことということで言えば、それはさまざまな行政サービスについては、現行の状態の中で提供することができるということでありますので、その点については最高裁の判断云々の時期に至るまでも。","id":"exchange-028"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひこれも１つのきっかけといたしまして、新しい姿勢を考えていただきたいと思います。１０３ページの地域振興事業の中で、コミュニティ組織づくりということがあります。平成１７年度は約３年目になるんでしょうか、こういうことで、平成１７年度中にはどういうコミュニティ組織づくりの骨格を積み上げられたのか、内容について伺います。これが２番目です。この２つ、よろしくお願いいたします。","respondent":"田村地域活動課長","answer":"地域振興事業委託の関係です。１地区３０万円ということで、実際には受託者である町会、自治会では青少年対策地区委員、あるいは防災地区協議会、あるいは高齢者クラブ、あるいは日赤、赤十字の活動等、地域との連携を深めるための活動として実施しているものです。","id":"exchange-029"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、やはり区として地域のコミュニティをどういうふうにつくっていくかというのをもう少し積極的に出されていかれる必要があるんじゃないかというふうに要望をしておきますので、一度地域の中で今の活動会議みたいなもの、拡大活動会議といいますか、そういうのを開いていただければ、参加していって私どももいろいろ申し上げたいと思っています。","respondent":"田村地域活動課長","answer":"他区を見ましても、やはり全域を指定地域という、あるいは拡大をというような形ですと、どうしても、指定地域を広げることはできますが、今も朝と晩に指導員を立てて実際にチェックをしていると、一部今年から昼間もチェックしておりますが、指定地域を広げるだけじゃなく。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問・要望","question":"それを向こうは青物横丁駅から鮫洲駅、立会川駅、それから新馬場駅から北品川駅、あるいは東急で言えば、品川区内の駅をくるくる回るくらいの指定地域を広げる努力も考えていただきたいと要望いたしまして、これは終わります。次に、毎度言っている区民保養所のことですが、平成１７年度の調査の中で、今後の方策はどのように今、なっておりますでしょうか。伺います。","respondent":"鷹倉区民課長","answer":"暖景苑は数的には４７名程度の施設なんですが、それにかわる代替的なものを何とか確保したいなということで、今、詰めを行っているところです。１１月に入った早々に委員会がありますけれども、そのときには具体的な報告ができるのではないかと、このように考えているところです。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問・要望","question":"そのご答弁で結構ですが、私は行財政改革特別委員会というところに所属しています。できれば、今後、新しい方策をとったものがあまり区の手間ひまのかからないような段取りで、できるだけ合理性を持ったものにしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"１０１ページの職員給与、それに退職手当についてと、それと１０２ページの職員研修費と職員互助会補助金についてお伺いしますが、まず退職手当についてお伺いしますが、いわゆる２００７年問題ということで団塊の世代が退職をしていくという形でありますが、品川区においてもこれから退職されていく方の数が大量に出てくると思うんですけれども。","respondent":"榎本人事課長","answer":"ただ、品川区の財政規模は１,３００億円という一般会計規模を持っていますので、その中の３０億円ということになりますので、計画的に今後、きちんと行政改革をやっておりますので、人数等の関係でいけば、特に支障なく支払えることができるのかなと考えております。","id":"exchange-033"},{"speaker":"藤原委員","kind":"確認","question":"退職手当は問題ないということで確認をさせていただきましたが、次に、お金のことは問題はありませんということで、人的なことなんですけれども、いわゆるずっと行政にかかわられた方がやめていくということで、公務という意味の技術の継承がどのようになっているのかというのが知りたいんですけれども、なかなか次の方に継承していくというのは難しい面もいろいろあると思いますが、本区の場合。","respondent":"榎本人事課長","answer":"そういった意味でいきますと、技能系につきましては民間委託等で対応しておりますし、その他本来業務の部分につきましても、中途採用ですとか、再任用制度を組み込みながら、新規採用も一定程度は採っていきますので。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"品川区は今、新規採用はされておりますが、何年か前は極端にといいますか、ゼロに近いか、ゼロだった時期というのがあると思うんですが、その辺の問題というのはまだすぐにはあらわれていないと思うんですけれども、将来的において、採用がなかったときに関してというのは問題というのはないんでしょうか。","respondent":"榎本人事課長","answer":"そういった意味で、新規採用ゼロの年の影響というのは、必ずしも入区する年齢が全員同じ年齢で入ってくるわけではありませんので、実際上入ってきた年代がばらけますので、確かに２０代が今、区の職員の構成としては少ないということはありますけれども。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"わかりました。そのこともありましたが、いわゆる福利厚生、互助会に関しては十分見直しもあったと思いますし、内容もいろいろ変わってきたと思うんですけれども、まず見直しの経過と、それと内容がどのように変わってきたかを教えていただきたい。","respondent":"榎本人事課長","answer":"職員互助会の部分ですけれども、大きな見直しは平成１７年度に見直しをしておりまして、特に互助会に対する補助金を約半分にしたという形です。","id":"exchange-036"},{"speaker":"藤原委員","kind":"意見","question":"この互助会に関しては、職員の方の福利厚生ということで、前高橋区長もこれに関してはバランスよく職員に対して必要だというお考えであったと思いますが、この互助会の制度に関して、新区長はこれからどういう方針を持たれているのかをお尋ねいたします。","respondent":"濱野区長","answer":"そういう意味では職員に対する、あるいは従業員に対する雇用者責任という、この２つの観点からバランスを考えて物事を進めていくという、この基本に変わることはございません。","id":"exchange-037"},{"speaker":"三村委員","kind":"質問","question":"最初に、平成１７年度にボランティアのホームページのシステムが立ち上がって、今、稼働しているかと思うんですけれども、こちらの経費がどこに計上されていて、どのぐらいコストがかかっているか、またどういう契約になっているのかを最初にお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"そのほかにサーバーの賃貸借料ということで、賃貸借料が年間で２１７万４,０００円余です。開発委託が５５０万円という形です。事業部支援プロジェクトの中に含まれてあります。","id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"品川区としていろいろ立ち上げてはいるんですけれども、なかなか活動登録団体が増えていないような様子がうかがえるんですけれども、それに対してどういった問題点があるのか、現状把握されていることをお伺いできればと思います。","respondent":"堀越行財政改革担当課長","answer":"活動分野別をＮＰＯ別でというお話ですけれども、これは平成１７年度からこのボランティア・ナビしながわのシステムが始まりまして、これまでいろいろな所管でボランティアの情報がさまざま分かれていたものを。","id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"受け付けもサイトを通じてもやっていますということだったんですけれども、このサイトを立ち上げたことによって、どの程度このサイトを通じて利用者が実際にボランティアの活動に参加されたとか、そういった実績や何かは把握していらっしゃいますでしょうか。もし把握されているようでしたら、教えていただければと思うんですけれども。","respondent":"堀越行財政改革担当課長","answer":"実際にボランティアの活動状況がどうなっているかですけれども、これについては、定期的にやられている方ですとか、それから短期でやられている方ですとか、さまざまな状況がありますので、今のところは細かい活動状況を把握しているという状況にはございません。","id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"育児休業取得者は対象者が何人で、実績が何人になったのか、その辺についても、この行動計画をつくる前は実績ゼロということだったんですけれども、変化があったのかどうか、その点についてお伺いしたいと思います。","respondent":"榎本人事課長","answer":"特定事業主行動計画の件ですけれども、まず出産支援休暇の取得状況は、平成１５年度２日、平成１６年度１.８日、平成１７年度１.８日という形です。それで、出産支援休暇の取得率７５％ということに対して、平成１７年度の実績でいきますと７７％という形になってあります。","id":"exchange-041"},{"speaker":"三村委員","kind":"質問・要望","question":"パーセンテージだけじゃなくて、ぜひ実数でも教えていただければと思うんですけれども、なかなか７７％ということで、ぜひこの数字も今後上げていっていただきたいと思うんですけれども、実際に企業に対しても、区の職員の方の男性の育児休業取得、また出産時の休暇の取得ということはかなり数字として実績として上がってきたという現状があるかと思うんですけれども、当然、品川区全体を見たときには。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"失礼しました。実数ですけれども、男性の育児休業が対象者２２名中３名取得です。東京都では東京商工会議所等６団体等が指定されておりまして、品川区といたしましては東京商工会議所等と意見交換をしながら、啓発、そういった状況の把握に努めてまいりたいと考えているところです。","id":"exchange-042"},{"speaker":"三村委員","kind":"質問","question":"今、国の動き、都の動きをおっしゃっていらっしゃったんですけれども、品川区としての動きは商工会議所との会合ということで、その点だけということだったんですけれども、産業振興課では「産業ニュース」や何かを発行されていると思うんです。会議だけではなくて、ほかにもいろいろ働きかける方法等はあるかと思うんですけれども、それについて、もしされていることがあればお伺いしたいと思います。","respondent":"堀越行財政改革担当課長、金子産業振興課長","answer":"商工会議所といたしましても、中小企業向けのワーク・ライフ・バランスに関する啓発講座、講演会、推進マニュアル等も展開していくというお話を聞いておりますので、そういった状況を見ながら。あるいはホームページ等々を事業者向けに出しているものがありますけれども、こういった媒体をさまざまな啓発、それから私どもが支援する啓発セミナー等々を載せて、十分広く周知していきたいと考えているところです。","id":"exchange-043"},{"speaker":"三村委員","kind":"質問","question":"ぜひ積極的な働きかけのほう、よろしくお願いいたします。多分、今のお話だと把握はされていないかと思うんですけれども、努力義務の中小企業、品川区内の中小企業の行動計画の策定状況等をもし把握をされていれば、お伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"それから公募委員の件ですけれども、継続という形ですが、継続というのは、例えば公募委員以外の学識委員とか、団体の代表部の方ですとか、そういった方については継続するかもしれないというようなお話をさせていただいたとは思うんですけれども、公募委員の方については。","id":"exchange-044"},{"speaker":"三村委員","kind":"質問","question":"委員のほうは了解をさせていただきました。こちらの協議会でいろいろ議論が出ていたかと思うんですけれども、そういった次世代の審議会の中で、どういった意見が交わされていて、それが品川区にどのように反映されたのか、もし事例等があれば教えていただければと思います。","respondent":"堀越行財政改革担当課長","answer":"そのほか、あとは委員からあった意見といたしましては、今後とも協議会としてしっかりと意見を言って、行政と一体となって、一緒にこの次世代育成の計画を推進していきたいというような意見が出ております。","id":"exchange-045"},{"speaker":"三村委員","kind":"質問","question":"高学年になってくればいいんですけれども、やっぱり低学年の際のなかなか預け先がないということで、いろいろこの委員会の中でも必要性が指摘されていたかと思うんですけれども、この点については区としてはどのように判断をされているのか、その点についてお伺いしたいと思います。","respondent":"新美企画部長","answer":"私どもは今までは拡大をしていくということで取り組んでまいりましたが、全校展開の段階になって、十分関係者の方、保護者も含めて、趣旨を含めて、何時までやるかということについてもさまざまな考え方がありますので、そういったことについて十分ご説明をし。","id":"exchange-046"},{"speaker":"三村委員","kind":"質問・要望","question":"最後に改正ＤＶ法で、公共団体の責務に、被害者の自立支援を含む被害者の保護が明記されておりますけれども、品川区としては改正されたことによってどういった行政施策、対応が変わったのか、変わっていないのか、その辺についてお伺いできればと思います。","respondent":"武内人権啓発課長","answer":"今、均等法の改正が４月１日からスタートということできておりまして、今後、厚生労働省とこのポイントを各企業等に説明会を２月に開催する予定になっておりまして、そのような形で今後進めていきたいなと考えています。","id":"exchange-047"},{"speaker":"三村委員","kind":"質問","question":"すいません、男女雇用機会均等法ではなくて、改正ＤＶ防止法をお伺いしたんですけれども。","respondent":"諸岡児童課長","answer":"児童課におきまして、女性に関する福祉といたしまして相談を行っています。これはいわゆるＤＶ法に基づく法律で定められた相談員でございまして、ＤＶ等の相談に応じ、また必要に応じて一時保護等に、被害者の保護につなげているというような状況です。","id":"exchange-048"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"私のほうから２点確認と質問をさせていただきたいと思います。もう１点は１０８ページ、選挙費のところです。山北町のほうは八潮太鼓とか、あるいは大井権現太鼓の方が行かれているということで、費用的にも早川町の５分の１、早川町が大体５００万円前後、山北町のほうが１００万円前後でずっと推移しているんですけれども、内容に相当違いがあるのかどうかを確認させていただきたいと思います。","respondent":"鷹倉区民課長","answer":"今、委員ご指摘にもございましたが、平成１０年が１つの境になってありますが、早川町のヘルシー美里、ヴィラ雨畑につきましては、平成１４年がピーク、そして、１５年がぐっと落ちて、１６年、１７年で少し回復してきているという内容かと思います。","id":"exchange-049"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"それからもう１点は、平成１６年から契約延長をしてあるわけなんですが、これは山北町が地元の方々と契約をしているわけなんですが、これは例えば何かあった場合には品川区のほうから契約を途中で解除できるとか、そういう条項は入っているんでしょうか。山北町との話し合いの中でどういうふうにされているのかなということなんですが、わかりましたら教えていただきたいと思います。","respondent":"鷹倉区民課長","answer":"ひだまりの里の契約延長の関係のお話かと思います。１０年延長したということで現在進めてあります。","id":"exchange-050"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"今のお話の中で自律をというお話をしていらっしゃいましたけれども、多分民間での交流事業を積極的に推し進めようとしているのではないかと思うんですが、今後の状況の中で、特に山北町の場合は、今まで交流をされてきた、例えば丹沢湖マラソンにしても何にしても、縮小のような状況が出てきていますし、民間だと相互交流をしなきゃならない場合ですけれども。","respondent":"鷹倉区民課長","answer":"そこのところである種の見直しという形で、より活性化させるような形で効率的に活性させていただきたいと考えているところです。","id":"exchange-051"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"スペースの都合もあるでしょうけれども、そこに期日前投票の案内も載せたらどうかという話が来ているんですが、その辺の考え方はどうでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"そういった意味で、実際に紙面がどうなるかというのは、立候補届けが終了しないと確定しないという状況がありますので、そういった意味では、載せ方については、１晩かけて校正するという関係もありますので、ちょっと工夫させてもらわないと。","id":"exchange-052"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"工夫を凝らしていただきたいとは思いますけれども、区民の方々は、区長もそうですし区議もそうですが、なるべく早く情報が欲しいわけですよね。どういう方が出るのかどうなのかという部分も。それは確かに出る方の数が増えれば、なかなかスペース的に確保できないところもわかりますけれども、そのぐらいの努力はされてもいいのではないかなと思うんですが、ご意見を聞かせてください。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ先ほど申し上げましたように、選挙公報となりますと、載せ方の工夫はしますけれども、校正等とかを短期間で誤りなく発行するということでは、なかなか難しいところもあります。そういうことも踏まえて、可能性については検討させていただきたいと思います。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"１０６ページの防災問題について伺います。学校避難所の関係ですけれども、避難所の中核として位置づけると防災計画にはなっています。１０年ほど前の平成５年当時の資料を見る機会がありまして、それに書いてある数字から大幅に減っているので、その辺もあわせてどういう検討の経過があったのかを教えていただきたいと思います。","respondent":"久保田防災課長","answer":"これは相当前からこういう考えでやられていたんですが、阪神・淡路大震災が起きたときに、学校にいっぱい避難者が避難したという経過から、学校も避難所として位置づけていこうという形で、新しく考え方が出てきたのが平成８年です。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"しかし人口は今年の８月１日現在で１万３,４２６人なので、収容数は大体５人に１人ぐらいになっちゃうのかなと思うんですね。この計画によると、３.３m2に対して２人という基準で計算しているということも書いてあるので、それでの数なのかなと思うんですけれども、あふれちゃう方々をどうするかというところをちょっと伺いたいと思います。","respondent":"久保田防災課長","answer":"これを主に小中学校、もちろん小中学校で、震災が起きたときに一律に状況が各地区によって同じだということは絶対あり得ませんので、おそらく被害が集中しているところもあれば、全然被害が少ないところもあるだろうということから。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"そうなった場合の状況についてちょっと伺いたいんですけれども、その場合に、１つは学校のトイレの数なんですけれども、避難所になっている学校は６個ずつ設置をするということになっているようですが、これについては簡易トイレ等々もいろいろありますけれども、タイプとしては和式型のトイレなのかなと今までの経験で思うんですけれども、高齢化時代の中で。","respondent":"久保田防災課長","answer":"そういう中で入浴とか何かという機械もそろえていますので、当面はそういう形でやってもらうというのが１つだろうし、それからもう１つは、何よりも重要なのは、そういう入浴関係とか、あるいはお店関係が一刻も早く復旧体制をとっていくという仕組みも必要だということで、現在。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"ですから、これはきちんと明記していただいて対策をとっていただくように、この辺はお願いしたいと思いますけれども、その辺の見解と、それからマニュアルの件なんですが、役員には配布しているというお話なんですが、もらっていないという方もいるのでこの問題を取り上げて聞いてみたんですけれども、すべての防災区民組織の役員には伝わっているということで認識していいんでしょうか。","respondent":"久保田防災課長","answer":"３分は自分の身を守れ、３時間はお互いに助け合って何とかやっていこうと、３日間は何とかしのいでいこう。３日間以後になれば公共的には支援が来るんだと、こういうお話になってあります。ということであれば、３日後から我々防災機関も含めて何とか動ける体制になるわけですね。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"私のほうからは１０３ページの青少年対策、そのうちの特に地区委員会運営のほう、２点目に同じく生活安全推進事業、生活安全サポート隊を中心に質問します。青少年対策地区委員会のほうです。平成１８年度、この青い冊子、品川区における青少年対策の概要というのを読ませていただきました。この対策、概略の中身ですが、一瞥いたしますと、各地区の平成１７年度の実施事業一覧があります。","respondent":"田村地域活動課長","answer":"それ以外も、宿泊の研修も、地区委員会の連合行事としては、私どものほうで事務局を務めて、一括１３地区からお連れしていますが、それ以外の各地域の研修につきましても、宿泊でするもの、あるいは宿泊でしない場合もありますし。","id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"いろいろ研修、また事業内容、人数を含めて、限られた予算の中で適切に児童健全育成のために地域の構成員の方々が一生懸命頑張られている。今後とも有意義な地区委員会の運営をお願いしたいと思います。そこで、こういう事業をされて、今、課長もおっしゃられました健全育成が目的だというところで、どのような成果を得てこられたのか、何点かお答えいただければと思います。","respondent":"田村地域活動課長","answer":"それも町会、自治会あるいは地区委員会の方に実際に協力者として参加してもらったということもありますし、例年、各地区ごとに実態調査といいまして、不健全な、例えば自販機によるビデオだとか、あるいはコンビニによるいわゆるビニールがかぶさった本だとか。","id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"この地区委員会の構成についてですが、ある程度固まった構成員、メンバーになっていると思います。そこで、新規の参加も含めまして、地区委員会への参加というのはどのような過程を経て、どういう決定がされるのか、お知らせいただきたいと思います。","respondent":"田村地域活動課長","answer":"現在、内訳で申しますと、実際に８６３名地区委員がいまして、８６３名中１１４名、全体の１３.２％が町会長、それと９９名、全体の１１.５％がそれぞれのＰＴＡの方が委嘱されて、地区委員会として活躍している。","id":"exchange-060"},{"speaker":"若林委員","kind":"質問・要望","question":"ちょっと私の質問の仕方がまずかったかもしれません。児童センターとか家庭あんしんセンター、これは児童の家庭指導実績が大変に多くて、昨年１年間でも１,０００名超のそういう児童相談を受けているということで、地域の実情を非常に細かく存じていると、私は各館長のお話も聞きながら理解をしておりますので、その担当部署との連携等を図りながら、今後どのように検討させていくかをお知らせ願います。","respondent":"田村地域活動課長","answer":"ただそれでよしとしないで、１３地区連携しながら児童センターと、目指すところは青少年の健全育成一本ですから、連携を密にして事業を進めていこうということで、所長会の中で児童課長とお話ししたと、このような実態です。","id":"exchange-061"},{"speaker":"若林委員","kind":"質問・要望","question":"各地域センターが事務局となっておりますので、ぜひとも児童センター等のこういう環境をご利用していただきたいなと思います。生活安全サポート隊のほうでパトロールの車を回しておられますけれども、こういった稼働率等が現在どのようになっておりますでしょうか。その効果、具体的に犯罪を未然に防いだとか、また具体的な犯罪に対応したことなど、そこら辺をまずお知らせいただきたいと思います。","respondent":"金子生活安全担当課長","answer":"このほか生活安全サポート隊による具体的な成果と申しますと、近隣セキュリティシステム、これはお子さんが危険を感じて緊急発信したケースがこれまで７件ありますけれども、いずれも初期的対応については警察に頼らず。","id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、池田山交番の存続を要望する請願が第３回定例会に出されまして、委員会のほうでは趣旨採択という結果になりました。同時に都民の世論調査では、パトロールの機能が強く求められているという都民の世論になっているようですけれども、今、なぜこのパトロールへの要望が多くの区民、都民から寄せられているのか、どのようにお感じになられるのか、お伺いいたします。","respondent":"金子生活安全担当課長","answer":"したがいまして、はっきりしていない部分も幾つかあると思いますので、具体的な交番の運用につきましては警視庁の考え方があると思いますので、区としては警察でできない部分、例えばパトロールカーで細かい裏路地までパトロールできないようなところ。","id":"exchange-063"},{"speaker":"若林委員","kind":"意見","question":"最後になります。急激な変化というのを地域の皆さんは大変に嫌いますので、そういう意味では警察としっかりと連携をとりながら、今後例えばパトロール車の増車でありますとか、また適正なルート、特に池田山地域につきましては、パトロールの強化についても特段のご配慮をお願いしたいと思いますけれども、ご答弁をお願いいたします。","respondent":"金子生活安全担当課長","answer":"これまで以上に警察と連携をとって、穴のないように対応していきたいと考えております。","id":"exchange-064"},{"speaker":"伊藤委員","kind":"確認","question":"私からは品川区の人件費に関連して、それから、１０２ページの庁舎等維持管理費、１０３ページの生活安全推進事業に関連して質問いたします。ですから、先ほど確認したところによれば、私たちが見るこの品川区の人件費の中には、いわゆる外に出した仕事の人件費はカウントされていないわけであります。","respondent":"日下部企画財政課長","answer":"これが業務委託という形で執行方法が変わる。そうすると、例えば平成１７年度の実績で見ますと、３億５,０００万円ほどということで、おおむね全体として６割程度の執行の実績という形で切り替わっているという現状です。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"質問","question":"それは大体わかっているんですが、要はトータルコストが見えないんですよ。ですから、そういうことからトータルコストを含めた上で、数字は確かに減っていると思います。それはそのとおりです。ですけれども、これからどんどん外部委託とか、指定管理者が増えていくわけですから、しっかりとそれを把握していってほしいなと、そういう思いを込めて質問しておりますので、答弁をまた改めてお願いいたします。","respondent":"日下部企画財政課長","answer":"ただ、それがどれだけの効果が上がったのかということも含めての点検作業、例えば今までの行政評価でありますとか、そういう手法も含めて、経年的な変化も含めてきちんと検証し、次の見直しに生かしていくということで取り組んできているという状況です。","id":"exchange-066"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そこで質問としては、これをやっていくにあたっては、例えば○○部、○○課を横断した全庁的な形で庁舎等の、例えば検討委員会なりをきちっと立ち上げて、そこで上位計画とか、さまざまなことも絡めながら最終工事を進めていくべきと考えますが、いかがでしょうか、答弁をお願いしたいと思います。","respondent":"宍戸施設担当課長","answer":"今、まだ基本設計の段階なので、これからそうした具体的なことは詰めていかなければいけないと思いますが、当然全庁にかかわることなので、連絡会議になるのか、そういった検討委員会になるのかというのはこれから決めるべきものと思いますけれども。","id":"exchange-067"},{"speaker":"伊藤委員","kind":"確認","question":"これはこれからいろいろな議論があると思われますのでこれぐらいにしておきますが、もう１つ確認しておかなくてはいけないのが、東京法務局の品川出張所が、こういうことに関連して、私たち自民党が言い続けてきた内容と違った方向でいってしまうと困るわけでありますので、ぜひそのことについては十分な区の対応をここではお願いをしておきますので、よろしくお願いいたします。","respondent":"金子生活安全担当課長","answer":"したがいまして、できるだけ私どものほうでも具体的に犯罪の種別を明らかにして、ある意味では区民の方に危機意識を持っていただいて、それを、先ほど委員のほうからご提案のありましたボランティア活動、パトロール活動、そういった点に結びつけていきたいと考えております。","id":"exchange-068"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、もう少し踏み込んで、これだけ貴重なデータが今あるわけですから、例えばまちづくりの観点からも考えられるわけじゃないですか。ですから今、課長がおっしゃったように、それは当然であり、やっていただきたいんですけれども、せっかくそういう犯罪マップがあるわけですから、それをもとにして、ハードの部分の対応はどうですかということをお伺いしておりますので、改めて答弁をお願いいたします。","respondent":"山田区民生活事業部長","answer":"一方、防災計画の見直し等もやっておりますけれども、かなり多岐にわたる所管に入ってまいりますし、対外的な措置という部分も出てくるかと思いますので、しばらくお時間をいただいて、研究させていただきたいと思います。","id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問","question":"犯罪マップという言葉はおかしいかもしれませんけれども、犯罪が多発している地域とそうでない地域が明確にわかっているわけですから、その多発している地域に、集中的に品川区の持っている資源を投入して犯罪を防止したらどうでしょうかという観点で質問しておりますので、おそらくそのことはご理解していただいていると考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"山村委員","kind":"質問","question":"私は１０１ページの総務管理費の関係で２点お伺いさせていただきまして、１０４ページ、歩きたばこ防止キャンペーンで１件、時間がありましたら、同じく１０４ページの広報経費関係で１件、それと時間がありましたら、防災対策費で１件質問します。","respondent":"榎本人事課長","answer":"従来からずっと人員削減を進めてきた中では、技能系の仕事がかなり減ってきたという形です。これからは一般事務系や一般技術系の職務の中で、どれぐらいそういうスリム化が図れるのかというのは、いろいろと検討をしていかなければいけないと考えています。","id":"exchange-071"},{"speaker":"山村委員","kind":"質問","question":"その４割分を全部補充しないというのを聞きまして安心いたしました。どうかちょうど人数が減るのを利用しまして、できるだけスリム化を今後とも図っていただければと思います。飲酒運転をした職員に対して、品川区ではどのような対応をとるおつもりなのか、今まではどうだったのかと、今後変えるのか等を教えていただければと。","respondent":"吉岡総務部副参事","answer":"品川区といたしましても、従来から飲酒運転に対しては、その件につきましていろいろ国の基準ですとか、都の基準ですとか、あるいは社会通念と申しますか、その事実に対する社会一般の見方ですとか、あるいは社会やその他の職員に与える影響、過去の処分例等を勘案いたしまして。","id":"exchange-072"},{"speaker":"山村委員","kind":"質問・要望","question":"私は飲酒運転をすることはありませんので、どんどん聞かせていただいてもいいと思うんですけれども、とにかく私はお酒が全く飲めない人間ですから。とりあえず現状はどういう処罰になっているのかと、今後その処罰を重くする等を考えられているかを教えていただきたいと思います。","respondent":"吉岡総務部副参事","answer":"今後の方向ですけれども、今申しましたように、処分基準は統一的なものはございませんので、それを策定するような方向で検討しています。","id":"exchange-073"},{"speaker":"山村委員","kind":"質問","question":"品川区としても、飲酒運転に対しては厳しい対応を取り決めて、厳しい対応をしていただければと考えています。これは私も吸いますので、なかなか心が痛いところですが、ちょっと前まではよく道路上に舞っていました、品川区が設置しました歩きたばこ防止のプリントされた、よくはげる代物ですが、現状はどういうふうに変えられたのかということをまず教えていただければと思います。","respondent":"田村地域活動課長","answer":"やらないというわけじゃなく、予定では大井町、五反田、武蔵小山と、路面表示については順次、大井町のほうは新しくしたばかりですが、４１個ほど焼き付けのタイルをはろうということで、五反田についても路面表示を１１月以降、武蔵小山もそれぞれ協議しておりますので。","id":"exchange-074"},{"speaker":"山村委員","kind":"質問・要望","question":"我々品川区の人間は、品川区でそういうのがだめだというのは理解しているんですが、県外ですとか区外の人間がどこまでそれに気づけるかというのはあるでしょうから、そこら辺はもう少し目立つようにしていただければと思います。それともう１つ、関連して質問するのが、前も質問したんですが、目黒駅はいまだにやられていないのか。もしやられていないんでしたら、その理由を教えていただきたいと思います。","respondent":"田村地域活動課長","answer":"ただし、品川区のように駅の近辺を指定区域という指定はしていないんですが、やはり両区にまたがるということなので、合同でマナーアップのキャンペーンを１１月に予定しようということで、今、暫時調整しています。","id":"exchange-075"},{"speaker":"山村委員","kind":"質問","question":"ですから、このケーブルテレビ等でテレビで流すだけじゃなく、新しい分野というか、新しい方法を現時点ぐらいから模索しておいていただかないと、すぐ時代おくれになってしまうというのがあるのと、ケーブルテレビで品川区民チャンネルを見れる年代とそれを見れない年代があると思いますので、特に働いている年代ですとか。","respondent":"中川原広報広聴課長","answer":"もちろん携帯電話のところからメール配信ということも、昼間は区にいらっしゃらない方が多いわけですから、どういった情報を携帯電話を通じて必要とされるかということも含めまして、対象者と情報内容と、それからメディアについてのバランスを考えながら。","id":"exchange-076"},{"speaker":"山村委員","kind":"質問","question":"まだ時間がありますので、最後に１０６ページ、防災対策費のことでちょっと聞かせていただければと思うんですけど、この防災対策費を見ていると、これはいわゆる自然災害というのを想定されてやっているんだとは思うんですが、北朝鮮が核ミサイルを現在持つようになったということで、この核に対する災害というものに関しては、今後想定されて対策というか。","respondent":"桑村危機管理室長","answer":"私ども区とすれば、そういったものを教えていただき、あるいは研究させていただいて、それが実際上区民の避難、あるいは救援のためにどういう形で使えるかという意味での考え方について、検討させていただければと考えています。","id":"exchange-077"},{"speaker":"山村委員","kind":"意見","question":"こればかりはあおったほうがいいのか、あおったほうがいけないのか、実はあまり危ない危ないと言わないほうがいいんじゃないかと私とかは思うんですが、とにかくさまざまな事態を想定してシミュレーションしていくということ自体をやめないでいただいて、防災というのは自然災害だけじゃないということは肝に銘じて、これから頑張っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"品川区の職員の定数をどういうふうにしていき、そして、いわゆる新規採用の方をどうして、それから、１００人ぐらいの退職で再任用を求める人はどのくらいの方々がいらっしゃるか、その数字だけでも教えていただきたい。それから、これは非常に簡単なことで、広報広聴の古い話、新しくない話ですから。私たちは品川区議会の議員ですから、品川区議会へのリンクが一番下なんですよ。","respondent":"山田区民生活事業部長、榎本人事課長、桑村危機管理室長、上川内戸籍住民課長、中川原広報広聴課長","answer":"ただご本人がアメリカのネバダ州でこのようなことを認知されて戻ってきて。職員数の関係ですけれども、退職の数でいきますと、平成１８年度は定年退職が７３人、その後１２３人、１１４人、１１６人、１２７人と。その意味では、これまで平成１７年１月からやっておりました、いわゆる宿直の体制ですとか。除籍簿についてのお尋ねですが、８０年保存しております。これは戸籍の規則によって全国一律８０年です。今年度中にやらせていただきます。","id":"exchange-079"},{"speaker":"林（宏）委員","kind":"意見","question":"不満だというのだけ聞かせていただければ、この後、対策を練って、来年はトップに躍り出たいという、その気持ちをくんでこれ以上続けませんけど、日経だけじゃないんですよ、さっき言ったようにね。八王子市がトップという新聞もあるわけ。だから、どこまで機材を備えて、学校側に、あるいは避難してきた人と一緒にあれを生かしていくのかというのが、意味がよくわからないので、その辺答えてください。","respondent":"久保田防災課長","answer":"学校の備蓄倉庫に入れている機材ということで、拡大して考えますと、スコップとか、ガスバーナーとか、こういうものをおっしゃっているんでしたら、これは全校に配備してあります。全部同じ形になっています。","id":"exchange-080"},{"speaker":"林（宏）委員","kind":"意見","question":"最後の話なんだけど、学校にとっては、副校長とか校長とか横の連絡がある。そうすると、あれを使って何をしたらいいのかという話もしていると、あら、うちにはそれはないというような疑問が起きてくるから、もう１回点検をしておいてください。お願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"山路委員","kind":"質問","question":"時間があったら１０４ページの防犯設備整備助成事業についてもお伺いしたいと思います。男女共同参画に関してですが、本とかを読ませていただきますと、非常に充実、拡大、または今後の展開も非常に区の事業として大事になってくるんじゃないかと考えていますが、どういう内容を今まで平成１７年度やってこられて、今後どういう計画を持って進めていかれるのか、お伺いいたします。","respondent":"武内人権啓発課長","answer":"これが行動計画推進会議を立ち上げておりまして、区民の委員の方がこの行動計画についていろいろご意見をいただく。それで昨年、平成１７年から第１１期の行動計画推進会議を立ち上げておりまして、来年の３月に報告書を区長に提言していただく予定になっております。","id":"exchange-082"},{"speaker":"山路委員","kind":"質問","question":"今、少子化対策における女性の社会進出ということが盛んに言われておりますが、今の内容でいろいろ来年の３月に区長に提言をされるという、非常に今後の区政運営にとっても大事なことではないかと思いますが、その中にあって、今言われています、ちょっと関連できるかどうかわかりませんけど、女性の働き方の見直しとか、あるいは地域における環境整備とか。","respondent":"武内人権啓発課長","answer":"このような啓発につきましては、男女平等推進フォーラムというのを毎年１１月に行っているわけですけれども、この１１月２５日に行う部分についてはワーク・ライフ・バランスということをテーマに、シンポジウムを予定しています。","id":"exchange-083"},{"speaker":"山路委員","kind":"質問・要望","question":"この中で、昨日の歳入のときにもちょっと出たんですが、非常に努力をされてバナー広告と発音するんですか、今、５つぐらい出されていますが、ホームページが見やすいように、邪魔にならないようにということで大変苦労されている気持ちはわかるんですが、昨年もお願いしましたけれども、企業の広告まで手を広げられていいんじゃないかと思って今、あたっていらっしゃると思うんですが。","respondent":"中川原広報広聴課長","answer":"前回ご提案がありました、今までとは違った、大学とかそういった業種ではない企業への広告ですけれども、先ほどもお話しありましたが、今、品川ガイドの広告を鋭意やっておりますので、その広告の営業とともにバナー広告の営業もやってこようと思いまして、今。","id":"exchange-084"},{"speaker":"山路委員","kind":"質問","question":"工事中じゃなくて載っていなかったので、もっと品川区にはたくさんの工芸家とか、すまいるスクールとかで活躍している方もいらっしゃいますし、銀座とかで個展を開いている方もいらっしゃいますし、載せられるんじゃないかと思ったんですけど、作品が少ないわけじゃないと思うんですが、その辺の理由はどういうところにあるんでしょうか。","respondent":"鷹倉区民課長","answer":"今、委員ご指摘のとおり、もっといろいろ自分たちの作品を見てもらえるような機会をという話が確かにあります。その辺をどのような形でその要望をかなえていけるかというところは研究してまいりたいと考えています。","id":"exchange-085"},{"speaker":"山路委員","kind":"提案","question":"平成１３年の決算特別委員会の総括質問の中でも、インターネット美術館の中身についてのいろいろご提案を申し上げているところに、民俗資料だとか書籍だとか、美術史も含めまして、品川歴史館には２万８,０００余の資料があるということですので、載せるものと載せられないものの選別はあると思うんですが、作品についてはまだまだいいものが発掘されるんじゃないかと思うんです。","respondent":"鷹倉区民課長","answer":"現在のやり方が公募という形で平成１６年度からやってきているわけです。アクセス数ということは今やっているやり方の評価ということになってまいると思います。この辺のアクセス数を踏まえながら、今後いろいろなアクセスが増えるような形の研究をしてまいりたいと考えています。","id":"exchange-086"},{"speaker":"山路委員","kind":"質問・要望","question":"ちょっとまだ抽象的なんですが、具体的に、例えばせっかくフラッシュプレーヤーみたいなので、動画で、１辺２辺見るんじゃなく、ずっとこの方の作品を１０品ぐらい見て、芸術の秋にふさわしい感動をホームページ上で味わうような、そこまで研究をしていただきたいということなんですけど、その辺のことはいかがでしょうか。","respondent":"鷹倉区民課長","answer":"確かに動画的なことができないかということも我々研究している部分もあります。ただ一定の経費がかかってまいりますので、その費用対効果等も踏まえて研究してまいりたいと考えています。","id":"exchange-087"},{"speaker":"山路委員","kind":"質問","question":"この美術館も区のホームページとリンクしていますけど、ここもバナー広告を入れてもいいんじゃないかと。芸術、美術を支援する企業というのはよくありますよね。そういう考えをしているんですけど、芸術作品を見せるための企業広告も考えられると思いますけれども、この辺をどのようにお考えでしょうか。","respondent":"鷹倉区民課長","answer":"財団法人品川文化振興事業団に対する委託事業という形でやってありますので、その辺との兼ね合いも含めて、これも研究課題とさせていただきたいと思います。","id":"exchange-088"},{"speaker":"山路委員","kind":"質問・要望","question":"続きまして国勢調査、昨年行われまして１年で、内容が発表されるのは１２月ごろだということを新聞で読んだんですけど、国勢調査の調査のあり方について、回収ができなかったとか、来年は見直すとか言っておられますけれども、費用に関しては国が出すということで品川区はないと思うんですけれども、調査状況でどういうことが品川区であったのか、困ったこととか、不都合なこととか。","respondent":"鷹倉区民課長","answer":"実施しているときも委員会の中でいろいろご質問があってお答えしているとおり、調査員が行った中で、ちょうど個人情報の保護という形で、すごく敏感になっている時代背景の中で行ったということで、調査に対してもうちょっと十分説明してほしいとか。","id":"exchange-089"},{"speaker":"山路委員","kind":"質問","question":"調査員の方が調査票をお家に持ってきて、回収に来なかったという方をお伺いしたんですね。ニュースでも調査員が回収しないで、そのままどこかに捨てたとか、そういうのもあったようなこともありますけれども、せっかくの国勢調査で、来年の住民のニーズが反映されるかと思うんですけど、それに関しては品川区ではありませんでしたか。","respondent":"鷹倉区民課長","answer":"捨てたとか、そういう不謹慎な話は特に聞いてございません。","id":"exchange-090"},{"speaker":"山路委員","kind":"質問","question":"この調査状況は、来年は調査員を選定するのにもいろいろ工夫するということを新聞で読ませていただきましたが、また１２月には内容が発表されますので、来年の区の予算または区政にも影響があると思いますので、また改めて質問いたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０４ページの生活安全サポート隊についてお聞きしたいと思います。この事業は平成１５年１０月に発足しまして、１６年、１７年と拡充されて、現在、各警察署ごとに２名の警察官ＯＢと、実際のパトロールカーでパトロールとか防犯広報活動をしていると思いますけれども、この取り組みを拡充させてきた背景と事業の目的、また取り組んできた効果についてお聞かせいただきたいと思います。","respondent":"金子生活安全担当課長","answer":"平成１４年にさかのぼりますけれども、都内の犯罪発生件数、いわゆる刑法犯の認知件数が初めて３０万件を超えたという状況下で、非常に犯罪が、いわゆる街頭犯罪をはじめ増えているという状況下にございまして、警察の持つ力だけでは。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうことを受けて、今回、街づくり特別委員会の中でもテーマの１つになっていますし、区長の発言でも、高齢者の福祉の充実とともにこの安心・安全のまちづくり、犯罪に強いまちづくりという発言がありましたけれども、こういう中で、私は今回、警視庁から出された交番廃止という問題が本当に大きな問題だと思うんですけれども、品川区として交番の役割について。","respondent":"金子生活安全担当課長","answer":"区としては、警察だけではできない部分、先ほどちょっとお話をさせていただきましたけれども、人と、手間と、お金のかかる、まちの裏側隅々までのパトロール、こういったものをやっていければそういった犯罪自体も減っていくのかなと考えております。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は品川区が、警視庁が出した交番廃止の計画に対してどう思うかということではなくて、品川区が交番の役割をどのように考えているか、交番の役割についてお聞きしましたので、そのことについてお願いします。","respondent":"金子生活安全担当課長、早津区民生活事業部次長","answer":"区としても、警視庁の考え方、一定の考え方があると思いますので、それをある程度理解した上で、できることを考えていかなきゃいけないのかなと考えております。しかしながら、地域における、品川区で言えば区民生活の安寧をつかさどっているためのいろいろな活動をされている、そんなふうに認識しております。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、荏原町駅前交番は東京都のこの規定からすると対象にならないんじゃないかと思うんですけど、そこの考え方と、それから、荏原町駅前というのはもちろん駅前ですし、商店街がすぐそばにありますし、学校がすごくたくさん、保育園、幼稚園、小学校、中学校、高校と合わせると十数カ所の子どもの施設があるところなので。","respondent":"早津区民生活事業部次長","answer":"請願の件なんですが、先般、荏原第四地区の町会長会議において、区の考え方、つまり荏原町駅前交番の撤去は撤回できない状態であるということを踏まえて、品川区としてどう対応するかというご説明をいたしましたときに、区の考えは十分わかったからということで。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、計画された安心安全ステーションがどれぐらいの大きさかというのを、１つ具体的にお聞かせいただきたいんですけど、縦・横の長さと平米数を教えていただきたいのと、それとあとは、私は地域の要求としては交番を残してほしいというのが皆さんの思いで、署名がこれだけ集まったというのが事実だと思うんですね。それが皆さんの思いです。","respondent":"山田区民生活事業部長","answer":"その中で警視庁のほうで、１回廃止をしたものをまた新たに建てて、そこを交番とするという考え方は持たないということを明言され、荏原警察署の署長を含めて私どものほうにご説明に来ました。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回は財政効率のためにやるのではなくて、パトロールの強化をするためにこういう統廃合をやっていくのだというのが警視庁の言い分ですから、これに照らしても、今、荏原町駅前交番に配置されている警察官ＯＢを含む３人は、そのまま荏原町の今度区が建てる建物に残していただくというのは、警視庁の言い分からいっても可能であると思うんですけれども、ここら辺の見解についてはいかがでしょうか。","respondent":"金子生活安全担当課長","answer":"何で難しいのかについては検討中であり、具体的なことは警視庁のほうの考え方でありますので、申しわけございませんけれども、詳しいところまでは回答できないのが正直なところです。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは９月２８日の警察・消防委員会の中でも、自治体管理に対しても警察官ＯＢを原則として置きますということではっきり答弁しているんですね、この議事録をいただきましたけれども。そういうところでは、ぜひ区としてこの地域の思いをしっかり受けとめて、せめてこの自治体管理の交番と同じように、警察ＯＢの配置を最低でも置くようにということで取り組んでいただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問・要望","question":"１０５ページ、会計管理費、そして１０８ページ、住居表示管理事務費、戻りまして１０２ページの代替職員雇用経費、職員互助会補助金、職員被服貸与費ということで教えていただきたいと思いますが、まず最初に１０５ページの会計管理費のほうからということで伺います。昨年１２月末日をもって収入役がご退任されております。今、収入役不在の状態で、副収入役が今されているわけです。","respondent":"日下部企画財政課長","answer":"確かに地方自治法が改正になります。来年４月から収入役の廃止ということで施行になるわけでありますけれども、その辺を受けての組織的な体制をどうするかということにつきましては、今後具体的な検討に入ってまいりたいと考えているところです。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問・要望","question":"今後具体的な検討ということで、まだ６カ月ぐらいありますが、今の段階ではそうだと思います。収入役室が廃止になり、新しい部なり課ができた場合に、独立性というのか保たれるのか、それとも独立性を保つ何か担保というのは、きちんとしたものがあるのか教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"その辺が、具体的にＩＴの進歩も含めまして、かなり会計上の処理の形態が変わってきたということで、今回、法改正に結びついてきたというわけでありますけれども、基本的には今申し上げましたような、詳細については今後なんですけれども。","id":"exchange-100"},{"speaker":"大沢委員","kind":"質問・要望","question":"現段階でははっきりとした青写真というのは出ていないということで、これからのということで、私はお願いをしておきたいのは、きちんとしたチェック・アンド・バランス、公金に対してきちんとした処理ができる、それでなくても昨今、自治体ではいろいろな事故なり事件が起きておりますので、本区においてはないと絶対に信じておりますので。","respondent":"上川内戸籍住民課長","answer":"住居表示がされてから議論としてあったかどうかということですが、私の認識ではございません。","id":"exchange-101"},{"speaker":"大沢委員","kind":"質問","question":"私のサイドではないということは、地域ニーズもなかったと理解をしなければいけないんでしょうか。","respondent":"山田区民生活事業部長","answer":"住居表示のほうは、課長が申したとおり、昭和３７年の法に基づいて、利便性等を勘案し、効率的な施行ということで定着はしてきていると認識しています。","id":"exchange-102"},{"speaker":"大沢委員","kind":"質問","question":"どうしたら地域コミュニティーが高まっていくのかという議論が依然として続いていると思います。１０年や２０年ではできない。そうなった場合、やはりそういう作業というのも今まで行政のほうはないとおっしゃっていましたけれども、僕は非常に重要なことだと思いますけれども、私の意見を述べた後に、その意見についてのご所見をお伺いしたいと思います。","respondent":"山田区民生活事業部長","answer":"そんなところと連携しながら、区は順次進めさせていただきたいと考えています。","id":"exchange-103"},{"speaker":"大沢委員","kind":"質問・要望","question":"土地に愛着を持つ日本、日本というのは騎馬民族じゃなくて農耕民族ですから、定着性があるわけですから、やはり自分の土地に愛着を持って、歴史そして由来を知るということは、非常に子どもたちの教育にとっても大事でしょうし、高齢者の方たちの横の結びつきにとっても大事だと思いますので、そういう場所がなければぜひともご議論していただくような場所をちょっとでもつくっていただきたいと思いますし。","respondent":"榎本人事課長","answer":"職員被服貸与につきましても毎年見直しをかけているところですけれども、平成１７年度につきましても、定例的に貸与を繰り返す被服につきまして、若干破損時対応ということで、着られなくなったら補充をしますという形に切り替えたところがありますので。","id":"exchange-104"},{"speaker":"大沢委員","kind":"意見","question":"今、平成１７年度の成果報告書で、これに基づいて１７年度の予算の額をお話しさせていただいたんですけど、１８年度になると金額が落ちています。落ちたというか、金額を下げているんですけれども、これもまた何か意味があるのか。より決算額に近いような額になっているんですけれども、これは今、３つとも倍なんですよ。今、半分の決算になったことについて説明をいただきましたけれども。","respondent":"榎本人事課長","answer":"この中で予算に対して決算が同規模になるのは互助会の補助金だけでございまして、残り２つにつきましては、当年度の新たな予測というのがありますので、その中で執行していきたいと考えております。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"確認と要望をしたいと思います。１０３ページの生活安全推進事業と、それから１０８ページの先にご質問がありました住民表示管理事務費の件に関しまして、その後は１０６ページの防災対策費、１０２ページの国際友好都市交流事業、１０１ページの私立幼稚園保護者補助金についてお尋ねいたします。確認ですが、先ほどの交番の統廃合についてというお話で、さまざま委員のほうからもご質問がありました。","respondent":"金子生活安全担当課長","answer":"現在、警視庁の考え方ですと、交番から地区安全連絡所、仮称ですけれども、こういった形をとって、人員的にはそこに安全連絡員という形で警察のＯＢを何名か配属をするというふうに聞いております。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、あそこは以前から見てみますと、不在が多くて、いつ人がいるのだろうという交番でもありまして、巡回のほうも西大井駅のほうの交番のほうで、派出所のほうでいろいろやりますよというお話もいただいているようなんですが、要望として、ＯＢの方も含めて、しっかりと見守りをしていただきたいということで、これは要望にさせていただきたいと思います。隣は出石町会というんですけれども、読めない。","respondent":"田村地域活動課長","answer":"それと、町会のエリアですけれども、やはり町会は確かにまたがっていたり、町丁目別と区分けは確かに複雑なところがありますけれども、それに合わせて再編というのは、もう長い歴史があるのでなかなか難しいかなと、そのように考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな事情がありますので、すぐに町名と町がリンクするというのは難しいかと思いますが、先ほど、品川、大崎のほうですか、自主的にというお話がありました。これは要望です。それで次に、防災対策費についてですが、避難所連絡会議というのがあると思いますが、今、避難所連絡会議の実施状況はどのぐらいになっているのか。１００％やられているのかについてお尋ねします。","respondent":"久保田防災課長","answer":"学校の避難所連絡会議の開催状況ですが、設置は５８校全校で設置しておりますけれども、昨年度は３４校で実施しているという状況です。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"そうすると、１００％はされていないというところだと思いますが、その理由はどういうものでしょうか。避難所連絡会議がとれない、会議がやれない事情というのは何かおありになるのでしょうか。","respondent":"久保田防災課長","answer":"私どももこの避難所連絡会議、最低年１回はやってほしいということで各学校あるいは町会にも呼びかけているんですけれども、やはりいろいろ、例えば学校長が異動でかわってしまったときとか、そういうときになるとブランクがあいてしまうというのが傾向としています。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"それの重要性。それから、学校を避難所にしているというところで、自分の地域がどの学校にいて、何年何組の部屋に与えられているのかというところまで、今の状況だとわかっている、もちろんご存じの方はいらっしゃると思いますが、やはり末端までそれが周知されていないのではないかなというふうに感じるんですが、その辺はいかがでしょうか。","respondent":"久保田防災課長","answer":"その延長上に各町会の部屋というか、教室の割り振りを最初にやっていこうというようなことが、どうしても町会のほうからこれは出てきていますので、その関係で割り振ってはいますけれども、それは町会の役員たちを通じて、それぞれ町会員の方にはご周知はしておりますけれども。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"町会等々の役員たち、非常に一生懸命地域の安全を守るために頑張っておられるのはよくわかります。ただ、そもそも先ほどもなかなか会議をすることができないというところですが、中心になる人、声をかける人はだれになるのか、責任者はどこにあるのかということをまず確認させていただきたいんです。","respondent":"久保田防災課長","answer":"したがって、その方が連絡会議の招集とかという形になるわけですけれども、それだけではやっぱり十分ではありませんので、私ども防災課、地域センター、それから学校の校長先生、副校長先生が一緒に事務局として、これは町会長たちを支えて運営しているというのが実態です。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"そういう意味では、事務局になっている学校長が率先をして声をかけて、ＰＴＡの方たちもいらっしゃると思いますので、その方たちと一緒に話をしていくとか、そういう形でもう少し町会の方たちをサポートするような形で、やはり枠組みとしては学校単位があるわけですから、学校の中での位置づけというのがもう少し発揮できないものかなというふうに思いますが、いかがでしょうか。","respondent":"久保田防災課長","answer":"確かに全地区ではないので、ほかの地区にも今後そういう形で呼びかけて、今、委員がおっしゃっているような趣旨で充実していきたいというふうには考えております。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"ぜひやはり危機感を持ってやっていただかないと、いつ災害が起きるかわかりませんので、機会あるごとにお願いいたしたいと思います。もう１つ、教室の割振表というのが、この間、大田区の学校を見たときに、クラスにちゃんとここの避難所の対象になる地域の方は何番から何番地の人ですよというような表示があったんですね。それは全校には今後展開していくということはありますでしょうか。","respondent":"久保田防災課長","answer":"ただ、今お話ししたように、ちょっと避難所連絡会議が遠のいている学校については、いろいろ教室の使用が変わることがあるので、それの対応ができていないところは一部あると思いますので、今後そちらのほうも充実させていきたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"よろしくお願いします。次に、国際友好都市交流事業ですが、歳入が６５０万円余、歳出が７,７３０万円余あるんです。これは今後どういう形で、かなりの歳出になってしまっているんですが、考え方はいかがでしょうか。","respondent":"桑村総務課長","answer":"その意味で、当初、昭和６２年度から始めているわけですけれども、そのときにいわゆる区が直接やらずに、いわゆる民間の団体というところが交流を進めたほうがより一層広い範囲で交流が進むだろうということがありまして、国際友好協会。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、やはり外部にお願いしているという部分があるならば、もう少し採算まで行かなくても結構ですけれども、もうちょっとこれが費用対効果ということがあると思いますが、その辺も含めて今後検討していただきたいなというふうに思っています。これは要望で終わりたいと思います。大体年収によって違うというのはわかりますが、比較できる層、所得の層の中で比較ができれば教えていただきたいんです。","respondent":"高橋幼保一元担当課長","answer":"それで、その差というものはあるんですけれども、就園奨励費等、保護者補助費等も含めまして、６１％の方が月々１万５,０００円程度補助をさせていただいているということを考えますと、今、８,０００円と９,０００円の差があるというところで。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"済みません、保育園のほうはいかがですか。保育料との比較はいかがでしょうか。","respondent":"高橋幼保一元担当課長","answer":"公立保育園もなっています。保育園のほうの保育料につきましては、階層別ですので、４歳、５歳について一番高い方が１万９,６００円ということで、その私立の所得の階層というのがこちらで把握していませんので、ちょっと比べることが難しいかなと思います。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問","question":"確かに年収、所得によって違う階層になっていますので比較は難しいとは思いますが、ただ、大体所得の階層、例えば保育園の場合は２１階層ありますけれども、それの１０階層が大体の中間といいますか、世帯が多い、もう少し高所得まで行っていると、そっちのほうも人数が増えているというのは見えてはいるんですけれども、そのできれば１０階層ぐらいのところとの比較はいかがでしょうか。","respondent":"小林保育課長","answer":"Ｄ１０ですけれども、Ｄ１０ですと、幼稚園の場合は、四、五歳児ですけれども、Ｄ１０で１万９,６００円になっております。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、受益者負担になっていくというところにおいては、この辺の私立幼稚園、保育園、それから保育園のほうの保育料の整合性というのは、今後どのように考えているのかだけ教えていただきたいと思います。","respondent":"小林保育課長","answer":"基本的には、幼稚園と保育園で保育時間等が違うというところはありますが、その辺の時間、それから保育・教育の内容を含めて勘案して、０－５歳トータルで公平性を確保するように保育料ないしは幼稚園の保育料を含めまして、体系については検討してまいりたいと思います。","id":"exchange-118"},{"speaker":"石田委員","kind":"質問・要望","question":"済みません、今の私立保育園のこと、１０１ページは後でやります。先ほど、ボランティアのネットワークという話があって、今、一生懸命それをやっていただいていて、私は頑張っていただきたいなと考えていますが、そうなってくると、例えば子どもというところをとらえると、社会教育委員会議で以前答申も出ていて、ネットワークをつくったらどうですかという答申があったと思います。","respondent":"堀越行財政改革担当課長","answer":"次世代育成支援の行動計画をつくりまして、今、その対策を進めているですけれども、その子育て支援のネットワークに関しましては、現在進めている中で、その進捗状況を見ながら、そういった、今、委員のご指摘の部分も含めて。","id":"exchange-119"},{"speaker":"石田委員","kind":"質問","question":"じゃあ、それをどういうふうにスタートさせるんだ、そこに学校も入れるのか、学校でもよく私も言うけれども、各学校で校長先生が頑張っていらっしゃって、いろいろなことをやっていらっしゃる。ここら辺の先ほども言ったボランティアのネットワークも今できたわけであれば、横串をしていくことが子育て支援にとっては本当に必要だと思うんだけれども、そこら辺の点のご見解をもう一度お聞きしたい。","respondent":"堀越行財政改革担当課長","answer":"関係課の課長に集まっていただいて、庁内のそういったこの施策についてどうやって進めていこうかというような検討も進めておりまして、その中で、今、委員ご指摘のありましたような形についても検討を進めていきたいなというふうに考えております。","id":"exchange-120"},{"speaker":"石田委員","kind":"質問・要望","question":"それで、もし今みたいな形で検討を進めるのであれば、私は横串で横断的な、例えば区民にも見えやすいような、各課にも全部そういうものを言えるような、例えば子育て支援室みたいなものをつくって、そこが課でもいいけれども、そこに課長なり係長なりいるのか、そういう目に見える形で品川区はこのことについて取り組んでいきますよという、そういうものをつくるべきだと考えていますが。","respondent":"新美企画部長","answer":"ただいまご質問の青少年の健全育成あるいは子育て支援ということにつきまして、これは大変古くて新しいテーマでありまして、昭和３０年代から始まった青少年対策、社会教育委員制度、青少年対策地区委員制度、さらに児童課、児童センター、その他行政サービスが充実し。","id":"exchange-121"},{"speaker":"石田委員","kind":"質問","question":"今の部長の答弁は非常にありがたくて、課長の答弁と同じなので、私はその先で、それを区民に広く見せるためには、そういう部屋なり、課なり、そういうものをドンと打ち出さないと、なかなか今おっしゃっているところが我々には見えづらいところがあるので、難しいというお話もあったけれども、難しいのであれば、そういうところを逆に部屋なり課なりをつくって、区民に向けてみんなで一緒にやりましょう。","respondent":"新美企画部長","answer":"私ども、組織をつくって、その機能がすぐ発揮できるのであれば組織をつくりたいと思いますが、組織だけで十分行くだろうかということもありまして、きょうのご質問も十分参考にさせていただきながら、来年度に向けて検討をさせていただきたいと思います。","id":"exchange-122"},{"speaker":"石田委員","kind":"質問・要望","question":"じゃあ、これはこれでやめます。ぜひ本当にそういうことが必要だなと考えていますので、大変なことかもしれませんが、ぜひそれをやっていただきたいなと思います。それから、保育園もあるけれども、あとはアパート経営をされている方であれば、民間の区民住宅もある。","respondent":"日下部企画財政課長","answer":"その際に例えば減価償却でどのくらいなのかということも含めて、イコールではございませんけれども、比較的そういう形で民間の原価計算の手法等についても活用しながら、より合理的な１つの仕組みづくりということで検討を進めている、そういう経過があります。","id":"exchange-123"},{"speaker":"石田委員","kind":"質問","question":"もちろんそういうことをしながら、先ほど来あった受益者負担の部分と、区民サービスの部分、区がやる部分ですから、区民サービスの部分でやる部分はもちろんあっていいです。私はそこの部分をしっかり人材育成ではないけれども教育をしてほしいなと思ってこの質問をしているわけです。原価がどれぐらいかかっていてもいいんです、それは。だけれども、しっかりその数字を押さえてくださいよ。","respondent":"日下部企画財政課長","answer":"ですから、例えば公会計のいろいろな検討なんかも今、大きなそういう流れにあるわけでありますけれども、委員ご指摘のように、官と民のそれぞれの役割、あるいはその基本的な考え方、目的、いろいろ違いはありますけれども、今ご指摘のように、その違いは違いとして、じゃあ。","id":"exchange-124"},{"speaker":"石田委員","kind":"質問・要望","question":"だから、じゃあ、手を抜いているかといったら、そんなことは絶対にないわけで、行政側はどうしてもそういう、そこの部分が走りやすいのじゃないのかなと思っています。だから、そういう方には、ぜひそういうのを伝えていただきたいと思うんだけれども、その伝えるという部分のちょっと答弁があまりなかったような気がするんだけれども、その考え方だけお聞きします。","respondent":"日下部企画財政課長","answer":"具体的なその辺の伝え方という問題でありますけれども、今、民間委託化に向けての検討を私ども企画部中心で各所管と連携しながらやっておりますので、そういう１つの検討の中で具体的なその辺の伝え方、あるいは自分たちがどういうふうにそれを理解し、受けとめていくのか。","id":"exchange-125"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうからは、２点教えていただきたいと思います。１つは、成果報告書１０２ページにあります非核平和都市品川宣言事業に関連をしてです。２点目が、１０６ページの防災対策に関連してです。最初に、非核平和都市品川宣言事業、この中に青少年平和使節派遣、これは前、青少年広島の旅という形で行われていた事業がございましたけれども、これの目的と現況についてちょっと教えていただきましょうか。","respondent":"桑村総務課長","answer":"現在の平和使節の派遣というふうに申していますけれども、平成１５年度から、広島、長崎、それぞれ広島のほうは中学２年生ですけれども１８名、長崎については青少年対象で５名ということで、非核都市品川宣言ということでやってきたものを。","id":"exchange-126"},{"speaker":"堺委員","kind":"質問","question":"青少年については公募方式によると、こういうふうになっておりますけれども、この辺は、今、どのような状況になっているのでしょうか。学校のほうで１人決めていただくに当たっては、本人からの申請というんですか、希望、あるいは学校のほうから、あなた行ってきたらどうかとか、その辺の決め方というんですか、仕組み、それはどうなっているのか。","respondent":"桑村総務課長","answer":"現在、大体８名から９名ぐらいの応募ということで、その中で抽選で５名の方に行っていただくような形になってあります。","id":"exchange-127"},{"speaker":"堺委員","kind":"提案","question":"この中で順次拡大をされて、広島から長崎へというふうになったわけですが、そこで、私も平成４年、決算特別委員会の総括質問で、今から１４年前になりますが、このときにこの事業の拡充ということで、かつて広島と同じように原爆を投下されて悲惨な目に遭った長崎や、あのひめゆりの塔で有名な沖縄を含めた派遣事業に拡大をしていただきたいと、このように提案をさせていただいた経緯があります。","respondent":"桑村総務課長","answer":"そういう意味で、今、いわゆる沖縄というようなお話だと思いますけれども、もう少しこの状況を見させていただいて、その中で次のステップに移りたいと思います。少しご検討の時間をいただきたいと思います。","id":"exchange-128"},{"speaker":"堺委員","kind":"質問・要望","question":"平和事業につきましては、ぜひひとつ拡充の方向で前向きにご検討いただきたいと思います。時間の関係で２点目に移りますが、成果報告書１０６ページに医療救護体制の整備および救護所の設置ということで、今回、約３００万円支出されておりますが、これの中身についてちょっと教えていただけますか。","respondent":"久保田防災課長","answer":"それから２つ目が、これは各学校避難所全部ですけれども、簡単な軽症に対応できるものということで、医療のミニセットということで、いわゆる救急箱的なものですけれども、これを２セットずつ配備しております。これも入れかえ時期だということで、それも１２０万円ほど。","id":"exchange-129"},{"speaker":"堺委員","kind":"質問","question":"それと合わせまして、私はこういう地域センター単位に決めた１３の学校には、救護所という明確に位置づけられたところがあるわけですから、そういうところが例えば防災訓練なんかのときに生かされているのかどうかということなんです。その辺も含めましてご答弁いただけますか。","respondent":"久保田防災課長","answer":"ここでは主に負傷者が集まってこられるということで、トリアージをするということになっていますので、そのための訓練を学校を会場にするところについてはほとんどやってあります。","id":"exchange-130"},{"speaker":"堺委員","kind":"質問","question":"ほとんどということですが、例えば、今回も私、ある防災訓練をやっている学校に２カ所行きましたら、こういう形を含めた防災訓練になっていなかったと思うんですが、いかがですか。","respondent":"久保田防災課長","answer":"例えば、これからやる荏原第四地区の源氏前小学校では、トリアージ訓練も毎年やっております。第二延山小学校でもやったことがあると思います。これからもそういう形で充実します。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"成果報告書の１０２ページの庁舎等維持管理費の考え方と、各種団体分担金、これは特別区人事・厚生事務組合と特別区協議会について質問します。品川区の総合庁舎が、耐震診断の結果、耐震補強工事が必要であると。補強したときに、実際、何年ぐらいもつのか、その辺をちょっとお聞かせください。","respondent":"宍戸施設担当課長","answer":"新築との比較ですけれども、こちらのほうの試算ではもっとかかる、１００億円前後かかるのではないかということもありますし、あと、区民にご迷惑をかけないようサービスを継続し続けながら工事を行わなければいけないという大きい命題がございまして、そういう意味では。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問・要望","question":"２５年もつということなんですが、私、思うに、建築物でも柱でもみんな同じだと思うんですけれども、基礎というのがあらかじめそれ相当にできていないと、やっぱり何でも、建物でも橋げたでもそうなんですけれども、基礎がしっかりできていないとなかなか耐震補強というのは私は難しいのではないかな、ものづくりのほうでもそうなんですけれども、やはり基礎があらかじめ。","respondent":"宍戸施設担当課長","answer":"もう１つは、機能自体が古くなったために更新するというふうな考え方もございまして、学校教育そのものがある程度新しいものになってくれば、新しい器というものも必要になるということで、その辺は全体的、総合的に比較検討しながら選択しているということだと思います。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問・要望","question":"よくわかりました。本当に資源といいますか、資金のほうも限りがあると思いますので、本当にきちんと判断してやっていただきたいと思います。特別区協議会のほうと、あと、特別区人事・厚生事務組合のほうをちょっと質問します。今、品川区のほうでは、２億３,０００万円、毎年分担金として出しております。","respondent":"桑村総務課長","answer":"１つは、特別区協議会、特別区人事・厚生事務組合ですけれども、それぞれ特別区協議会についてはいわゆる財団法人ですので、特別区の全体としての区としての利益というんでしょうか、そういったものを目的としている財団ですので、それについてのいわゆる執行機関につきましては。","id":"exchange-134"},{"speaker":"須貝委員","kind":"意見","question":"今回、この中身を見ましたら、特別区の自治に関する調査の研究とか、その資料の収集なんかがあるんですけれども、これなんかは各自治体でリンクすればいいのかなというのが第１点と。第２点は、品川区の総務部と比較して、自治会館の建設事業を事業費を除けば予算規模もほぼ品川区の総務部と同じだと思うんです。ですが、職員は３７０人といって品川区の約１.５倍。","respondent":"桑村総務課長","answer":"数字のところがちょっと私は理解していなくて申しわけないんですけれども、１つは、特別区協議会自体はそういった調査研究というのは今でも特別区の制度調査会みたいなものを立ち上げて、いわゆる自治権の拡充ということをやってあります。","id":"exchange-135"},{"speaker":"須貝委員","kind":"意見","question":"実際これだけどんどんストックが増えているわけなので、それに対して各自治体が毎年２億３,０００万円の分担金を出すというのは、ちょっといかがなものかなというふうに思いますので、一応それだけ意見を言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-136"},{"speaker":"築舘委員","kind":"質問・要望","question":"それと、最後、１０６ページの保養所のことに関してですが、先ほど、川西委員からも質問がありましたが、暖景苑が今年いっぱいでということですが、その後、かわりのものがまだこれからということですが、その辺のことをどうしていくのかというのは、ただやめるというだけで決めていないというのもおかしなものなので、もう少し詳しくお聞かせいただきたいということと、それから、ほかの品川荘、箱根荘など。","respondent":"桑村総務課長、田村地域活動課長、鷹倉区民課長","answer":"ジュネーヴの１５周年ですけれども、これはジュネーヴのほうにご連絡を申し上げまして、非常に残念だったようですけれども、ただ。特にこの方たちは、それ以外につきましては、できるだけお年寄りの方、引きこもりになったり、外出が困難というよりも、やはりできるだけ外に出たり。この方式がうまくいくということであれば、先ほどお尋ねの品川荘なり、箱根荘が活用できないという方向にも持っていければなという方向で進めてあります。","id":"exchange-137"},{"speaker":"築舘委員","kind":"質問・要望","question":"そうかと言って、最近家庭がやっぱりいろいろな意味で難しくもなってきているということもあり、そこである程度の方向性といいますか、家庭が基礎ですから、それで地域が成り立ち、そして国が成り立っていくわけなので、一番のもとなので、そのあたりはある意味では区だけでやるのかどうかという問題にもなってくるわけだと思うんです。そんなところですが、もし何かお答えがあれば言っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"土井委員","kind":"質問・要望","question":"私からは、総務費全般にかかわるんですが、総務管理費に関連をして時間外勤務に関する中身についてお伺いをすることと、１０９ページの都議選、衆議院選ということで執行しておりますが、毎年毎年選挙がありますので、それらの事務の進め方、特に開票絡みも含めたところについてお伺いをしたいというふうに思います。アベレージ的にはどうなんだろうかということをまずお伺いをしたいと思います。","respondent":"榎本人事課長","answer":"それと、全庁的にはやはり時間外勤務が縮減ということで、やはり今般の次世代育成等もありまして、働き方を見直していく、要は、働き方、その家庭生活を見直していくという形もありますので、引き続き時間外勤務の縮減を進めていきたいというように思っております。","id":"exchange-139"},{"speaker":"土井委員","kind":"質問","question":"原則は時間内に効率的に仕事を進めると。だから、そのように一生懸命やっているんだけれども、１００時間を超えるのが二、三出ているということで、その健康管理等のために今、面談をしてやっているというお話だったんですけれども、どういう部署なんでしょうか。どうなのかな。それによっても対策が違いますので、対応、対策を含めてどう考えているのかというところをひとつもう１回。","respondent":"榎本人事課長","answer":"そんなところが大体のところでございまして、平成１７年度につきましては大体５０人ぐらいがその月１００時間を超えるところに該当してくるという形です。","id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"それはこの事務経費という中か何かに入っているんだと思うんですが、その理解でこれはいいかどうか、後から聞かせてください。こういう形で残業になる部分があるんですけれども、この予算、決算特別委員会等のところだけ切り取ったとしたら、どういう残業時間等になっているのかなというのをちょっと考えてしまったものですから、どのように掌握、把握をされているのでしょうか。","respondent":"榎本人事課長、野田口選挙管理委員会事務局長","answer":"決算特別委員会対応のときの時間外の把握ですけれども、これも実際には各事業部の職員給与費の中に入っているんですが、その中だけをちょっと時間対応を切り出すというのが、ちょっとどれぐらいここの後ろに。事務従事者の経費がどこに載っているかですけれども、選挙費のところで、投票事務の従事者については投票事務、開票事務のところに、それぞれのところの事業で掲載されてあります。","id":"exchange-141"},{"speaker":"土井委員","kind":"質問","question":"選挙関係のほうに移らせていただきます。ただ問題は、そのほかの事務の進め方という形の中で、もっとマニュアル化してきちんとわかりやすく誤解を招かないようなやり方も含めてやっていかなければならないということが幾つか指摘をされた面もあったのではなかろうかと考えていますから、そこら辺についてちょっと認識をどうされているのか、これからどう考えられていくのかを少し伺わせてください。","respondent":"野田口選挙管理委員会事務局長","answer":"それからもう１つは、一たん積載台のほうに移動したものを、また確認するために点検台のほうに戻して誤解を生じたというようなことで、そこら辺の不徹底さが今回見られたかなというふうなところを感じているところです。","id":"exchange-142"},{"speaker":"土井委員","kind":"質問・要望","question":"開票事務ですからどんどん進んでいくんですね。票がどんどんあいていくわけです。見ているのはどうでもいいんですけれども、それをさらに確認が終わったよと持ってくる、ここら辺のところのやっぱり不徹底さみたいなものがどうもあったので、何か多かったのか、少なかったのか、何だかよくわからなかったという疑問が出てきて、まさか二度勘定しなかっただろうなとかという話になってしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"三上委員","kind":"質問・要望","question":"私は、成果報告書１０６ページ、防災対策費に絡みまして、学校等の避難所機能の充実、それから集中豪雨等対策費、それから防災無線という形になるのか、それともケーブルテレビ関係という形になるのか、システムがちょっと違いますのであれですけれども、要するに、情報伝達的な部分についての件でちょっとお伺いしたいと、こう思います。お願いします。","respondent":"久保田防災課長","answer":"避難所機能の中の仮設便槽ですけれども、これは震災時に学校避難所に避難された方々が臨時に使うトイレでございまして、各学校６基、大きさは１ｔ掛ける６ということなので６ｔほどの便槽になってあります。","id":"exchange-144"},{"speaker":"三上委員","kind":"提案","question":"平成９年の第１回定例会で私も一般質問で、北海道の江別市の例を挙げて貯水槽の応急給水槽の整備について提案しているんです。それから、ついでですから質問していきますけれども、防災情報の提供についてでありますけれども、安否情報ということについて、今、品川区はどういうふうに取り組んでいるのか、これも簡単でいいですからお伺いしたい、こう思います。","respondent":"久保田防災課長","answer":"受水槽のほうなんですけれども、水道局の関係からですと、応急給水槽、多分ちょっと合っていないかもしれないんですが、水道局では応急給水槽、私どもの区内では大体３カ所、１,５００ｔクラスの応急給水槽を設置しています。","id":"exchange-145"},{"speaker":"三上委員","kind":"提案","question":"仮設トイレの件については、もう十分わかった上で私も質問しておりますので、そういったことについてのせっかく新しい学校をつくっていこうとする状況下にあるわけですから、これも先ほど来から横断的なというようなお話が出ていますので、そういったところでやはり１つの課だけで固まってこれ以上はもうやらないぞということではなくて。","respondent":"久保田防災課長","answer":"今お話が出ていたような安否情報の件につきましては、私ども、新しい情報機器の検討ということでいろいろやってあります。今一番考えているのは、やはり災害情報の伝達ということで、ケーブルテレビをより活用しようということでいろいろ検討を重ねてあります。","id":"exchange-146"},{"speaker":"三上委員","kind":"提案","question":"いずれもしっかりと研究をしていっていただきたいということで提案しますので、真剣に受けとめていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-147"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１０３ページ、品川文化振興事業助成金に関連しましてアルゼンチン国債の問題について改めて伺いたいと思います。しかし、アルゼンチン債問題は今でも区民の中では非常に怒りがあります。そこで、まず初めに聞きたいんですけれども、この不正を許さない高い倫理意識、そういう決意で区政運営に当たるのかどうなのか、まず初めに伺いたいと思います。","respondent":"濱野区長","answer":"そのとおりです。","id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうであれば、このアルゼンチン国債の購入問題というのを改めてはっきりさせていくということが必要だと思います。初めに伺いたいのは、文化振興事業団からアルゼンチン国債の問題では、結局、損害が幾らになったのか、その報告は受けたでしょうか。受けてあれば、その金額、内容についてもお知らせいただきたいと思います。","respondent":"鷹倉区民課長","answer":"今のアルゼンチン債の交換ということを既に行われているわけですけれども、それの経過、結果につきましても、文化振興事業団の理事会あるいは評議員会において、平成１７年度の事業報告という形で了承済みというふうになってあります。","id":"exchange-149"},{"speaker":"宮崎委員","kind":"確認","question":"ということは、私は区がしっかり報告を受けたかということを聞いているんですけれども、それはもう文化振興事業団の内部で報告しているからそれで終わりという態度なんでしょうか。そこのところを確認したいと思います。","respondent":"鷹倉区民課長","answer":"私ども区から補助金が出ているわけですけれども、その補助金が適正に執行されているかどうかの区の監査についても既に済んです。適正に執行されているということを私ども報告を受けてあります。","id":"exchange-150"},{"speaker":"宮崎委員","kind":"確認","question":"損害が出たわけでありますけれども、それでは、元助役、当時の副理事長ですね、購入した直接の責任者、そして指示を受けて購入した元事務局長に対する処分等はあったんでしょうか。あればその内容、事業団のほうの処分、そして役員を派遣していた側の区としての処分があったかどうか確認したいと思います。","respondent":"山田区民生活事業部長","answer":"文化振興事業団におきますアルゼンチン債の問題については、この間、再三お答えをしています。文化振興事業団の中で評議員会、理事会という組織があり、それぞれのところで審議をいただいて、決定をして、今、粛々と進めているところです。","id":"exchange-151"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこのところを押さえて質問しているんですけれども、私は、ですから、区側に報告があったのか、そういうことをしっかりこの損害が確定した時点で受けるべきだという、そういう問題意識から質問しているんです。改めて、当時、役員を派遣していた側の区としては、そういう処分等の考え方はあったのか、そして、事業団では何らかの処分をしたという報告を受けているかどうか伺いたいと思います。","respondent":"山田区民生活事業部長","answer":"当時においては、適切な処置をとるということで、規定等も改訂し、そのほか内部的な部分については、それぞれ都の監査、区の監査も受けて、適正な会計管理は実施をしている。","id":"exchange-152"},{"speaker":"宮崎委員","kind":"確認","question":"結局、その後、適切に処理するとか、そういう約束が私は確認されていないのじゃないのかなというふうに私は思うんです。例えば、最近のニュースで調べただけでも、例えば、先日は河北新報というところでは１４万円の着服で懲戒免職。大阪市３６５万円。こういう場合には、処分を受けるようなことはないのでしょうか。公金を不正なやり方で使ったということは、そういう場合の処分というのはないのでしょうか。","respondent":"山田区民生活事業部長","answer":"ご質問の趣旨が、着服であるとか、横領であるとか、いわゆる犯罪性の高いものとしてそれぞれの機関のところでどうかというご質問なのかと思いますけれども、今回のこのことについては、そうした事件性のあるものというふうにはとらえておりませんので、お答えしがたいなと。","id":"exchange-153"},{"speaker":"宮崎委員","kind":"確認","question":"今の事件性が少ないというのは、それは区の判断ですか。どこの判断ですか。それを確認したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"},{"speaker":"宮崎委員","kind":"質問","question":"それを半年間、高橋区長に報告しなかったということなんですけれども、この調査報告書では、なぜ半年間報告しなかったのかということが書いていない。これは調査団、当時の調査団、今でいくと本間総務部長しかいないと思うんですけれども、区長もいますけれども、その調査団はなぜこの半年間報告しなかったのかということを報告書に書いていないんですが、これは事業団にただしたのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-155"},{"speaker":"宮崎委員","kind":"質問","question":"委員長、ちょっと説明すると、これは平成１４年３月４日に総務委員会に提出された資料。財団法人品川文化振興事業団の財産管理に関する調査報告、これについて質問しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"宮崎委員","kind":"質問","question":"私が言っているのは、当時、総務委員会、区議会に報告されたこの資料で、この点がちょっと不十分ではないのか、この点を聞いたのか、ただしたのかということを聞いているんです。その点について、なぜ答えられないのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問","question":"これは全く無責任です。私が聞いているのは、当時の調査団が何を調査したのかということなんですよ。例えば、この半年間報告しなかった、報告を受けたときに高橋区長、理事長は、これをすぐ売れと、そういう指示を出したというふうになっています。ところが、やっぱりこの半年間のところでどんどん事態は悪くなったんですよね。だから私は質問しているんですよ。調査したんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問","question":"委員長、それはやっぱりないですよ。私はこの報告書に基づいてやっているんですから、議会への説明ですよ。じゃあ、質問を変えますよ。もう１つ聞きます。ここのところでは、なぜ当時の副理事長の濱野現区長が調査委員会の責任者になったのか、ここのところは高橋前区長からどういう指示を受けたのでしょうか。ここのところをぜひ答弁をお願いしたいと思います。どうぞ答えをお願いします。","respondent":"山田区民生活事業部長","answer":"それも何年もたってそれぞれのところでやってきているわけですから、このことの部分で、今、私どもに聞かれましてもお答えできないです。","id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問","question":"区の調査、これがどう行われたのかということを聞いているんです。国債というふうに書いています。国債というふうに書くと、これは通常日本国債というふうになってくるんですけれども、この日本国債というふうに受け取られるように、アルゼンチン国債、あるいは外国債と書かなかった理由について、ここのところでは調査団のところでは、調査委員会はここのところはどういう調査をされましたか。","respondent":"山田区民生活事業部長","answer":"今、アルゼンチン債か国債かというご指摘がありますけれども、この点も含めて、理事会、評議員会という別の団体、法人の中で、きちんと議論されることが一番進むことだということで、区としてもそう考えているです。","id":"exchange-160"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと時間もなくなったので、本当に高い倫理意識だとか言うけれども、結局これですよね。もともとやっぱり、もともとの責任者がやっぱり私は今の説明では、元助役だと思います。このことを指摘します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-161"},{"speaker":"須藤委員","kind":"意見","question":"町会へもやはり同じように助成金、補助金、いろいろ出てきているんだけれども、きょう昼間からずっとありますように、地域のコミュニティーというものを考えた場合に、青少年対策地区委員とか、いろいろなことがあるので、その辺を１回、美化整備費だとか、環境整備費だとか、いろいろな町会に対して補助をしている、それはそれの形でいいと思うんだけれども。","respondent":"日下部企画財政課長","answer":"補助金、助成金等、表現も含めまして、その辺の整理をどういうふうにしているかということでありますけれども、例えば、１０２ページ、今ご指摘ありました上から５行目の国際友好都市交流事業につきましては。","id":"exchange-162"},{"speaker":"須藤委員","kind":"質問","question":"１０６ページ、１０７ページの区民斎場運営費と、臨海斎場運営費の稼働率というのか、利用率というのか、区民斎場のほうが臨海斎場ができてどういう変化になったのか、それから臨海斎場については５区で運営をしていくという形になるので、そのうちの品川区ではどの程度の利用率になっているのか、そのあたりがわかれば教えてください。","respondent":"日下部企画財政課長、鷹倉区民課長","answer":"助成金等についての考え方ですけれども、確かに委員ご指摘のように、もう少しやはり明確にその内容がわかるような形というのが必要な面もありますので、その辺、表現の仕方も含めまして。ただ、あちらのほうが満杯状態になっているといいますか、待ちがかなり長い状態が出てきた関係で、お客様が私どものほうのなぎさ会館のほうに復帰されているというのが平成１７年度の状況というような状況です。","id":"exchange-163"},{"speaker":"須藤委員","kind":"質問","question":"臨海斎場で品川区民の利用はどの程度あったのかというのを教えてください。そうした場合に、やはりそこもしっかり有効活用するという方策を、今までと同じような絵でつくっていくのではなくて、何らかの策をしていかなければいけないだろうと思うんですが、いかがでしょうか。","respondent":"鷹倉区民課長","answer":"今回も外壁あるいは空調の関係を改善いたしました。新しいリニューアルしたような形で、今、再スタートしているような状況です。したがいまして、利用が伸びていくのではないかと、このように考えているところです。","id":"exchange-164"},{"speaker":"須藤委員","kind":"質問","question":"１０５ページの防災区民組織の育成費等がありますが、補助金がやはり１,７００万円で、実際に執行がそれにプラス９００万円ぐらい足されたような費用になってきている。このあたりもどういう育成の仕方をされているのかなというのを教えていただければと思います。","respondent":"久保田防災課長","answer":"防災区民組織の育成の内容ですけれども、大きくは２つありまして、まず防災区民組織そのものの育成ということで、これは要するに、町会内の世帯数とか、それに基本額を掛けまして、その分を支援しているというのが１つです。","id":"exchange-165"},{"speaker":"須藤委員","kind":"質問・要望","question":"町会等については、いろいろな地域地域にやり方があって、先ほど来いろいろあると思うので、そのニーズに合うように、今後いろいろ検討されていっていただきたいと思います。ページ１０４に関係して、防犯協会助成金に関連して、荏原町の駅前交番について、先ほど来ちょっとお話がありましたので、品川区としては、このことについてどういう経緯でタッチされてきたのかお知らせください。","respondent":"金子生活安全担当課長","answer":"したがいまして、他の４つの交番と荏原町駅前交番については全く趣が異なりまして、廃止になるのであれば区としては最大限できることはないのかという観点に基づいて、今回は補正を組んで防犯拠点等ができるのではないかという、そういう考え方で取り組んでまいりました。","id":"exchange-166"},{"speaker":"須藤委員","kind":"質問","question":"自民党でもそのことを討議しまして、第４回定例会で一般質問させていただきました。荏原町駅前の交番は非常に大切な場所に、位置にあるんだというような一般質問をさせていただいた。そのときに、区側も我々と一緒になって都側に折衝していただいたり、所轄の署長にお会いになったりといろいろやっていただいたという経緯があるんですが、いかがでしょうか。","respondent":"金子生活安全担当課長","answer":"そのとおりです。","id":"exchange-167"},{"speaker":"須藤委員","kind":"質問","question":"そういう経緯があって、今度、東京都のほうでまた春になって絵をつくり出した。そして今、品川区でコミュニティーのそういう安全の基盤としてくるときに、次に我々が心配するのは、そこに動く人たち、応援しようという人たちに何かあったときの、事故があったときの補償はどうするんですか。それはどういうふうに対応するんですか。そのあたりを聞かせてください。","respondent":"金子生活安全担当課長","answer":"非常に難しい問題です。保険の関係については、まだ細かいところまで詰め切っておりません。ただ、これは町の方に育ててもらう防犯拠点ですので、今後も町の方といろいろな機会で話し合いの場が持たれると思います。","id":"exchange-168"},{"speaker":"須藤委員","kind":"質問・要望","question":"というのは、荏原町のほうで青少年対策地区委員がマラソン大会を応援していたときに、その後に心臓発作で亡くなってしまった。ですから、やはりここで同じようにボランティアの人がいろいろやったときに、寒い日に立っていたときに、パッと何かあったときに、きちんとそういった保険だの何だの手当てをしていただけるようなシステムを構築しておいていただきたいと思います。いかがでしょうか。","respondent":"金子生活安全担当課長","answer":"十分検討させていただきたいと考えます。","id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/249249?Template=document&Id=1262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":117097,"voices":379}},{"id":"h18-20061017-4","meetingId":"h18-c-settlement","date":"2006年10月17日","dateIso":"2006-10-17","committee":"決算特別委員会","time":"午前１０時０２分～午後６時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を145件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"おはようあります。成果報告書の１１２ページ、品川介護福祉専門学校、それと１１５ページの障害児放課後生活サポート事業、その後１１３ページの介護予防ですとか、新就業システムですとか、その辺を質問させていただきたいと思います。それでまず、学校全体の運営経費の総額に対しての助成金の割合というところを教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長、西島障害者福祉課長","answer":"平成１７年度につきましては３３名就職をいたしまして、このうちの２２名が区内の法人、あるいは関連の事業者。残りの１１名が区外の法人等というような状況です。それからにじのひろばのほうですが、これは趣旨としては同趣旨ですけれども、これは国のタイムケア事業を活用いたしまして、平成１７年９月から実施した事業でございまして、利用者数は９月からということで４６４人。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"介護福祉専門学校なんですけれども、おそらく人件費が相当ウエイトを占めていると思うんですけれども、社会ニーズに合ったところだと思いますので、その辺はしっかりとやっていただきたいと思うんですけれども、介護福祉専門学校のカリキュラムなんですけれども、例えば高齢者の問題で、品川区の政策でこの部分が必要だというのがいろいろ出てくると思うんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"カリキュラムについてのお尋ねですけれども、最近では、現場、高齢者のニーズに即した内容にカリキュラムを変えてきております。特に、認知症高齢者が今後増えてくるということで、認知症ケア、認知症対応の時間を増やしているというところが最近の傾向です。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう取り組みもあるということなので、これは学校に限らずいろいろな現場でも視野を広げていただきたいと思います。それで、介護福祉専門学校の予算づけというのが、おそらく必要なところには必要な措置を、そうでないところにはそれなりの対応という、これからの予算編成等あると思うんですけれども、その辺の社会全体でのニーズが高まっていると思うんですが、その辺の考え方についてお聞かせください。","respondent":"蓼沼高齢福祉課長","answer":"そういうことで、今後の予算に対する考え方につきましても、そういったカリキュラムの変化、あるいはニーズの変化に対しまして、適切に対応してまいりたいと思います。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"もちろん、これからの高齢化に対しての対策ですから、それは非常にありがたいんですけれども、例えば、もう何年も前なんですけれども、健康増進ということでぶら下がり健康器が一時期はやりました。もちろん、今、取り組まれている高齢者への対策としてはほんとうにありがたいと思いますが、ちょっとだけ教えていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"この事業は、平成１７年度にモデル実施をさせていただきまして、２回行っておりましたが、拠点を広めると委員おっしゃいましたように、平成１８年度におきましては拠点を３カ所広げる予定でございまして、現在といたしましては荏原地区で行っております。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区長が新しく誕生されましたので、ここでぜひお伺いしたいんですが、障害者の人権、そして、自立をしていく、社会参加をしていくために、生活を守っていくために、この応益負担というのはほんとうに妨げになると思うので、ぜひこれに反対を表明をしていただきたいし、国の悪政をただして区民を守る地方自治体の立場に立っていただきたいんですが、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"負担が今後どのようになっていくかというのは、大変大きな課題ではありますけれども、障害者自立支援法、さまざまな３障害を１法にするとか、障害児がもっと働ける社会にするとか、幾つか理念がありますけれども。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このところを見ると、国際的にＧＤＰで比較をするとドイツの５分の１、スウェーデンの８分の１、こういった低い国の予算の中で、障害者の皆さんの生きる権利も、今、切り縮められているという状況の中で、障害者の福祉を削るほど日本の財政が困難になっているとは、私は決して思えないので、こういった面では、自治体の長としての立場を、ぜひしっかりと示していただきたいんですが、区長、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"この負担が、幾らが妥当かどうかというのは大変難しい議論ですけれども、障害福祉サービスを充実・発展させていくためには、あるいは障害者以外の理解を得るためには、一定の負担というのは必要であろうと考えています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"この間のご答弁でよく伺うのが、区民の理解を得る、障害者の方々に、今まで障害者福祉にかけていた税金が、「これは多過ぎる」とか、「不公平である」とかいうような声がどこからか出ていたんでしょうか。私はすごく疑問です。私は、税金の無駄使いをただせはこんなひどいことを言わなくて済むと考えているんですが、裏づけは何なんでしょうか。","respondent":"西島障害者福祉課長","answer":"今回の法律改正につきまして、私ども、懇切丁寧に説明をさせていただきました。私だけでも各団体、あるいは各法人に行って説明をしてくれというのは、おそらく１０回では足らないぐらい説明いたしました。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"私は裏づけを聞いたんですね。説明をされているのはわかっています。ほんとうにこの負担が大変だということは、この間、多分区のほうも伺っていると思うんですね。私はぜひ、その裏づけをもう１回。今、答えていません。","respondent":"西島障害者福祉課長","answer":"そういう意味では、サービスの向上に必ずしもつながらなかった部分が、サービスを受ける側であると同時に、今度はサービスを支える側にも入るわけですので、そういう意味では、今回の制度改正を、単に財政上の問題だけではなく、障害者福祉サービスを充実していく。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の応益負担の導入で、利用者負担の総額が国において、厚生労働省の試算だと８６０億円にも上るわけですね。私は、その辺をちょっと明らかにしてほしいのと、その分で区の独自の軽減策をぜひやっていただきたいと思います。手話通訳同様無料にすることと、もっと使い勝手をよくすること、そして、ぜひ全身性の障害のある方にも利用できるようにしていただきたいと思いますが、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"４月から６月までの数字を見ましたところ、おおむね７割の方がこの３％の軽減措置に該当しているというふうに思っておりますので、先ほどお話ししましたように、制度のバランス、あるいは負担の公平性を考えて、このまま実施して参りたいと考えているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"利用時間数だけ比べても、区によって１０倍ぐらい違う区があるというので、わたしは２３区を比較して改めてびっくりしたんですけれども、いろいろな条件があるにしても、もっと使い勝手がよくなってほしいなと思うのでその辺が１点と、あと、区の独自負担軽減策で、そんなにたくさんの増にはならない、また、いろいろ使うとなくなってしまうというみたいなお話が、今、あったんですけれども、じゃあ。","respondent":"西島障害者福祉課長","answer":"それから３点目の地域生活支援事業にどれだけかかるかということになりますが、その辺はまだ、国・都の動向が定かでない中で区のほうで決めたのは、いわゆる支出事業と言われている４事業を実施するということで、委員会では報告をさせていただいたところですが。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、区民の声をしっかりと聞いて、今回の障害者福祉を根底から崩すような応益負担、これを少しでも負担をなくすための努力を、ぜひ区でしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"私は成果報告書の１１１ページのホームレス地域生活移行支援事業、１１６ページのシルバーセンター運営費、１２０ページの生活支援型一時保育の３点をお伺いしたいと思います。初めに、ホームレス地域生活移行支援事業ですけど、大体の内容はわかるんですけど、具体的にはどんな内容をされているのかということと、この平成１７年度で結構なので、実績を教えてください。","respondent":"志村生活福祉課長","answer":"ホームレス地域生活移行支援事業の事業内容についてご説明を申し上げます。これは、都内にホームレスが大分増えてまいりました平成８年以降、東京都と２３区でいろいろ有効な手立てを打ってまいりました。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、今、３７人品川区にということなんですけど、それは民間のアパートにお住まいなんでしょうか、その辺のところと、あと、お聞きしたかったのが、この間新聞に、東京都全体ではホームレスは減っているんですけれども、６区が増えている、品川もその中の一つということで、人に優しい町なので品川に来たのかななんてとらえたんですけれども。","respondent":"志村生活福祉課長","answer":"ですので、この駅舎の１７人につきましては、今後、私どものほうからいろいろな福祉の施策等についてこちらからアプローチをかけていくことを、今、考えているところです。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"駅のほうに移動しているというような状況だということなんですけれども、ＪＲの大井町の東急のところに、１人小柄の男性が、あの辺を通るとよく見かけるんですね。足もけがをされているような感じがして、ああいう方には具体的にはどんな対応をされているのか、それともしようとされているのか、具体的に教えていただけますか。","respondent":"志村生活福祉課長","answer":"ただし、これが一番難しいところなんですけれども、ご本人からしますと、これ以上は放っておいてくれということでありまして、私どもからしますと、健康状態等も含めて、私どもの相談窓口に来ていただいて、例えば大田寮というんですか、そうしたところで１カ月間。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問・要望","question":"ご苦労のほどはわかりました。それから１１６ページのシルバーセンター運営費のところで、西大井のシルバーセンターが原小学校のあとのほうに移転するという計画が出されて、それでパブリックコメントが求められて、それでこれは決定されたんでしょうか。それとも、決定されていないとすれば、西大井のシルバーセンターについてはいつごろ決定するんでしょうか。","respondent":"日下部企画財政課長","answer":"西大井のシルバーセンターですけれども、今、委員ご指摘ございました原小学校跡への移転ということですが、今、検討を進めているという状況です。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"原小学校の跡についてパブリックコメントをやられましたけれども、そのパブリックコメントを求める基準みたいなのは何かあるんですか。","respondent":"日下部企画財政課長","answer":"今、具体的に基準という形では持ってございませんけれども、とりわけ大きな施設の跡地利用等、幅広く区民の皆様のご意見をいただくような、そういう必要性があるものについては、そういう取組みを進めてまいりたいと考えています。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして、１２０ページですけれども、生活支援型一時保育オアシスルームについてですが、平成１６年度から５園でスタートしまして、私も平成１６年の第２回定例会で地域格差をなくす意味で拡充をしてくださいという趣旨の一般質問をいたしまして、平成１７年度から１０園でやられているということですけれども、平成１６年度、１７年度、また今年度の今までの利用実績。","respondent":"小林保育課長","answer":"通称オアシスルームの利用実績のお尋ねですけれども、平成１６年度は、ご指摘のとおり５園で延べ２,７１３名、平成１７年度は、６月より５園を追加し、１０園で６,３６５名です。平成１８年度は、現在９月までの集計ですが、同じく１０園で３,２４３名です。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"９月までで３,２４３ということなので、おそらく年間通せば昨年よりも少し上回ってくるのかなと思いますけれども、その辺の利用状況を、今後どのように見ていらっしゃるかということと、今後、拡大される場合の、もしくは今時点の、保育園では狭いんじゃないかとかいろいろそんな声も聞いているんですけれども、その辺の課題みたいなところがありましたらお知らせいただきたいと思います。","respondent":"小林保育課長","answer":"ただ、内容的には、在宅で子育てをしているいろいろなニーズ、例えばリフレッシュですとか、それからちょっとした用事、あるいは学校の参観日への対応、利用目的がわかってまいりましたので、よりそのニーズをとらえた内容の変更、そしてまた。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"保育園で、非常に手狭なところでやっていらっしゃるというようなこともちょっと聞いているんですけれども、そうした意味で言いますと、例えば今、児童センターと保育園を併設しているところがあるかと思うんですけれども、そういうところは、この間の定例会で、うちの若林議員も児童センターの拡充ということでやらせていただきましたが、そういった児童センターの活用について。","respondent":"諸岡児童課長","answer":"今後におきましては、保育課のほうとも連携を進めまして、一体的に地域における子育て支援を進めていきたいと考えております。","id":"exchange-019"},{"speaker":"阿部委員","kind":"質問・要望","question":"このたび皆様のお仲間に加えていただきまして大変光栄に思っております、阿部祐美子です。さて、本日私が質問させていただきたいのは、１１９ページ、保育園の運営費の中の下のほうから、賄費、教材費等という項目があるんですが、こちら、賄費と教材費というのはかなり性質が違った支出であると思われますので、まずその内訳と、それぞれの金額について教えていただければと思います。","respondent":"小林保育課長","answer":"教材費の関係ですが、保育園の教材、もしくは教材的な消耗品ということで、２,６００万円弱。その他、行事用の消耗品、維持管理の消耗品、厨房関係等あわせまして、こちら３億１,９００万円余の金額になっております。","id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"今、教材費が２,６００万円弱ということだったんですけれども、これ、保育園の定員３,２６２人、実際にはもうちょっと多いかと思うんですが、ざくっと計算しますと８,０００円弱ぐらいと計算できるかなと思うんですが、よろしいでしょうか。","respondent":"小林保育課長","answer":"単純な割り返しではそのように思います。１点、申しわけございません。賄費・教材費、今年度３億３,７００万円余です。訂正します。","id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"幼稚園は４時間平均である。登園日数につきましても、幼稚園は保育園の３分の２程度であるということを勘案しますと、ちょっとこの保育園と幼稚園の教材費の差が大き過ぎるのではないかと感じるのでありますが、この辺についてはどのようにお考えでしょうか。","respondent":"小林保育課長","answer":"その中で有効活用して、相互に使うことによって充足している部分もあります。ただ、今後、幼児教育の充実等のニーズがありますので、幼稚園・保育園問わず、教材・教具の充実には努めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"そのために、教材の用意が遅れてしまって、なかなか思うような教育が行えないといった状態も聞いております。こういった違いが出てくるというのも、幼保一体化を進める中で、ただ施設を一緒にするだけではなくて、教育の環境、保育の環境を、就学前の子供たちの育っていく環境の条件をそろえていくという意味でも、この辺の改善があってしかるべきだと思うのですが、いかがでしょうか。","respondent":"小林保育課長","answer":"今後も、その辺の状況に応じて、現場で十分な保育ができるようにという配慮は継続してまいりたいと考えております。","id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"先ほども申し上げましたとおり、幼稚園と保育園、そこにそれぞれ在籍する子どもたちの教育環境、そして教材の環境が大きく差がないような形にしていくために、一層の努力をお願いしたいと思います。先ほどもちょっと質問で出てきたオアシスルームなんですけれども、すみません、ちょっと私理解不足でして、決算の項目ではこのオアシスルームに関する費用というのは、一時保育のところでよろしいのでしょうか。","respondent":"小林保育課長","answer":"決算上は、生活支援型一時保育ということで、通常の保育とは分けてあります。ページ数から申しますと、お手元の成果報告書１２０ページの上のほうにあります。こちらの金額につきましては、経費として計上しているのは、人材派遣の経費等が主なものとなっております。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"すみません、これは不確かな話で、間違っていたらご指摘いただきたいんですけれども、このオアシスルームについて、今後、保育園と切り離して部分委託をするようなお考えも、区役所の中にあるのではないかという話を聞きまして、そういったお考えがあるかどうかというのをまず確認させていください。","respondent":"小林保育課長","answer":"１点は、先ほど児童課長から話がありましたように、施設、マンパワーという点では児童センター、保育かという子育ての担当部署と連携することによって、サービスの向上と資源の活用を進めていくということを、現在検討している途中です。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"すみません、まだちょっと言葉遣いに慣れなくて。その中で執行体制を考えていく、工夫をしていくということことは、委託も含めて考えていくというふうな理解でよろしいでしょうか。","respondent":"古川児童保健事業部長","answer":"今お尋ねのオアシスルームにつきましても、在宅の子育て支援の大きな柱というふうにとらえておりますし、１０園で６,０００名、決算が約６,０００万ということをとらえましても、より多くの方々にこのオアシスルームについての利用。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"私としては、このオアシスルームを保育士が行うことというのは、ただニーズにこたえるだけではなくて、保育士の資質向上にも大きく役立っていると、そのように評価していたものですから、そういった視点もできれば加えていただいた上で総合的に判断をしていただければと思います。よろしくお願いします。","respondent":"小林保育課長","answer":"その場合に転園希望が出てまいりますが、基本的にはこちら、転園も通常の入園申し込みと同じルールで、その必要性に応じて対応しております。ただ、全く同水準であった場合には、お１人入っているという点での若干の考慮はしています。","id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"既にばらばらに措置されている子ども、つまり、既にどちらも入所している子どもの転園についてお伺いしたんですけれども、転園の場合は、一つ動けば一つは空きが出るわけですから、その場合、理屈としては。要は、ある保育園への転園と、その保育園でないところでもいいという希望がある場合には、どちらが優先されるのでしょうか。","respondent":"小林保育課長","answer":"お２人が、今、ＡとＢという保育園にそれぞれ在園していらっしゃる。できれば一緒にしたいので、Ｂの弟さんを、お兄ちゃんのいるＡ園のほうへ転園を希望するというような形で申請が上がってまいります。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"手続のことを長々と聞いて失礼いたしました。どうしても保育園の入園以上に転園の仕組み、なかなか利用者にとってわかりにくい部分があるものですから、ぜひ、こういう仕組みで、転園というものがどのぐらいの頻度で審査が行われて、結果どうであったというのを、できるだけ利用者、あるいは申請者にわかりやすくお伝えしていただくようお願いいたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"１１９ページの保育園運営費と、時間がありましたら１２１ページの家庭あんしんセンターについてお伺いいたしますが、まず保育園ですが、ここ数年の申込者数と、入園決定者数を教えてください。","respondent":"小林保育課長","answer":"平成１８年度の申込者数は１,１８５、そのうち入園に至りましたのが１,００３となっております。平成１７年度の推移といたしましては、申込者数が１,１９５、入園者数は９９６。平成１６年度は１,１４４に対しまして９６０と、ほぼ同程度で推移しています。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"すみません、もう１回数字をお伺いしますが、この年度でいいので、待機児の推移と、それと特徴についてお伺いします。","respondent":"小林保育課長","answer":"こちらの意思表示、４月２日以降もまだ入れていないので入園を希望しますよとご回答いただいた方は、９０名弱の水準です。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"待機児ということですが、国も待機児ゼロ作戦というのをスタートしたと思いますし、現在も進行していると思いますし、品川区も待機児を減らす努力は今までずっとなさっていると思うんですけれども、それでも待機児というのは出てしまうと思うんですが、その辺の減らす展望についてお伺いしたいのと、特にその辺というのは１歳児が増えていると思うんですけれども。","respondent":"小林保育課長","answer":"この間、入園をお待ちになっている方、その中でとりわけ急を要する待機児という数が一定するあることは事実ですので、これに対する対応といたしましては、既存の保育園、施設の拡充に伴う定数の増、あるいは認証保育所の活用、そしてまた、既存の定数を超えて。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"全園ではないにしろ、一部を民営化するお考えがあるのかというのが１点と、それと、特に、前高橋区長は公立保育園の民営化はお考えになっていないとお話ししていただいておりましたが、濱野新区長は、この辺についてはどのような方向で考えているのか、できましたら理由も含めてご答弁していただきたいと思います。","respondent":"古川児童保健事業部長","answer":"したがいまして、ただいまのご質問の中で、部分的に民間の委託をするのか、園を丸ごとですね、そういう考え方には、現時点では立っていないというふうに、私は考えております。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"成果報告書の１２１ページの生活保護費と、１１９ページの児童福祉施設費の家庭あんしんセンター運営費、１１６ページの社会福祉施設費の心身障害者福祉会館運営費についてお伺いをしたいと思います。生活保護費なんですけれども、生活保護を受けている方には保険証がありませんけれども、こういった受給者の方から、その点で要望、困っていることとか、そういった要望は区のほうには届いていないでしょうか。","respondent":"志村生活福祉課長","answer":"例えば、「子どもが修学旅行に行った先でけがをしたりして病院にかかったときにそういったものがあるといいんですけれども」という話とか、「そういうときに、学校で保険証を集めるようなときに、生活保護世帯の子にはそういうカードがありませんので。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"今の、子どもたちにとってどうなのかって、すごく大切な問題だなと思っています。そういうところで、全国的な制度とはいっても、すべての人に受給者証をということではないにしても、そういった子どもたちに発行するということが全国的な制度といっても、そこのところを品川区で検討してほしいと思いますけれども、その点についてはどうでしょうか。","respondent":"志村生活福祉課長","answer":"おっしゃる中身については重々承知しています。そういった子どもさんを持っている親から、そのような声も聞いたことはあります。ですので、先ほどご答弁したとおり、これは私ども一自治体でというのはなかなか難しいと思ってあります。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"すべてがないわけではなく、私が聞いたところによると、八王子市では受給者証を発行しているという事例もありますので、品川区は人権尊重都市宣言をしているわけで、ほんとうにこの宣言は誇りを持てるものだと思いますので、ぜひ、品川区として積極的に働きかけをしていただいて、実施いただきたいと要望します。","respondent":"諸岡児童課長","answer":"家庭あんしんセンターの、いわゆる先駆型といわれるものの変更ですが、この先駆型と申しますのは、大きくは虐待防止に関しまして、虐待防止の機能を持ったセンターであるということの意味です。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"この辺のところを予防としてどういうふうに考えていらっしゃるのかということをお伺いしたいと思うんです。","respondent":"諸岡児童課長","answer":"今、委員のほうからお話ございましたように、平成１７年度まで、産後ヘルパーということで派遣しておりましたけれども、平成１８年度から、産前・産後を通じまして、育児支援ヘルパーというふうに改めまして、内容も大幅に、産後１カ月であったのを１年、産前も含めて行うです。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"その産前のヘルパーということでは、実績としてはどのぐらいあるんでしょうか。","respondent":"諸岡児童課長","answer":"産後支援ヘルパーの派遣実数ですが、平成１７年度で６５人。回数で申しますと１６８回です。これは平成１７年度の産後支援ヘルパーでございまして、産前につきましては平成１８年度からです。まだ集計をとっておりません。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、ほかの衛生費のほうでもかかわっていましたけれども、妊婦への訪問事業などもありますので、ぜひ、そちらのほうと連携をとっていただいてお願いしたいと要望します。次は、心身障害者福祉会館運営費なんですけれども、平成１６年度と１７年度の経費が６,０００万余変わっているというところで、このことについてどういう変更があったのか内容を教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"決算の数値で申し上げますと、平成１６年度は心身障害者福祉会館にかかわる経費が２億６,４００万、それから平成１７年度が１億２,７００万で、１億３,０００万ほど動いてありますが、これの大きなものは、一つは心身障害者福祉会館、改修工事を行いましたので。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"この会館は４月から指定管理者制度を導入されておりますので、そのことについて、運営委託費の中で６,０００万ぐらいの増があって、それは人件費ということなんですが、指定管理者になっての経費の変化というものはあったんでしょうか。","respondent":"西島障害者福祉課長","answer":"指定管理者になって以降も、事業の中身については毎年精査をしていくという中で、受けた側も努力の部分は努力として評価をしながら、削減できるものは削減しているというところで進めているところです。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"その辺で、指定管理者の導入は、コストもさることながら、利用者のサービス向上というのが目的の一つにあるわけですが、その辺の低下が絶対にないのかということを利用者はすごく心配をしているわけですが、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"この心身障害者福祉会館は、品川区として初めて指定管理をした施設ということもございまして、利用者に対する説明の際も、単に経費の削減だけではなく、サービス水準を上げていくんだ、現行のサービスと、少なくとも同じレベルではやるし。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"平成１９年度からは、都の障害児のタイムケア事業補助金というのが廃止されるということで、そのことについて、このやんちゃっ子も、にじのひろばも、大変ニーズがあって、今まで障害者の放課後対策というのが遅れていた、手がつけられなかった状況で、やっとそこに目が向けられて、子供たちの放課後対策としては、全児童対策、障害があってもなくても、また。","respondent":"西島障害者福祉課長","answer":"この点につきましては、今年度は既に実施をしている事業ですので、このまま実施をしてまいりますけれども、来年度以降どうするのか。キャパシティーの問題も含めて、十分検討させていただきたいと考えているところです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"非常に利用者にとってはニーズがあるということで、また、前回私も質問させていただいたときに、全児童対策として、コストの面では１時間１,６００円というところでは、何らかの対応をしていただきたいというふうに要望しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"虐待の相談件数で３倍なんですが、実際に虐待があったとされる数字はつかんでいらっしゃるのかどうかというのが１点と、この虐待に対しては、虐待防止地域ネットワーク構築ということで、品川区の児童虐待防止協議会というのを発展的に拡大して、先ほどの品川区家庭あんしんネット協議会ということで移行をさせて、平成１７年４月１日の法改正で。","respondent":"諸岡児童課長","answer":"ケース会議につきましては、既に先行いたしまして、５回にわたって行っております。合計して４０人の方々にご参加いただいているわけですが、この中でさまざまな虐待ケースについて検討されまして、早期発見、早期対応に向けた効果を上げてきているです。","id":"exchange-044"},{"speaker":"原（雅）委員","kind":"質問","question":"全体会を７月に１回開かれたということで、地域会議のほうはこれから、そしてケース会議のほうは５回行ってきたということで、この中ではケース会議がかなり具体的にいろいろと活動されているのかなと思っているところですけれども、そうしますと、ここに関する共通のいろいろな理解がないと、この構成をしている関係機関の中で共通理解を持てないと。","respondent":"諸岡児童課長","answer":"こういう中で深刻なケースにつきまして、ケース会議のほうで対応を進めているわけですが、具体的には、身体的虐待でありますとか、ネグレクト（育児放棄）が中心でございまして、これにつきまして早期発見、早期対応ということで対応を図りまして、現在についても。","id":"exchange-045"},{"speaker":"原（雅）委員","kind":"質問","question":"そうしますと、今のご説明でいきますと、かなりの部分でいろいろ守秘義務が出てきていると思うんですよね。関係機関も非常に多い中で、ケース会議それだけでも、人数的にも何人かがかかわっている。そうすると、その守秘義務については規定なり、要綱なりが統一されているのかどうかというのも含めて、ここでの守秘義務の伝達の仕方というか、実際の中でどういう形をとられているのかについて伺います。","respondent":"諸岡児童課長","answer":"これは個人情報保護法には抵触しないということが定められたわけです。そういった、あんしんネットの多くの利点がありますので、これを活用して、私どもとしましては虐待防止対策を進めていきたいと考えているところです。","id":"exchange-046"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"守秘義務につきましては、構成している関係機関が非常に多く、全体会で１９という数字が出てきていますから、かなり規程・要綱でそれぞれ決められていて、個人情報も含めて連携をして、しっかり守っていっていただきたいというのが一つ要望です。","respondent":"諸岡児童課長","answer":"そういう意味で、警察もこれに伴って迅速な対応を図るということで、危険の場合はただちに立ち入るというふうなことで全国的に徹底をしたということを聞いております。","id":"exchange-047"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"児童虐待、非常に多くなってきている中で、先ほども出ていましたけれども、乳幼児の虐待についても、ゆさぶられっ子症候群というんですか、そういったことについての心配もあるわけです。その辺のところ、特にケース会議を含めて、ネットワークの組織を現実的に、そして具体的な活動がしっかりできるような体制を、よりつくり上げていっていただきたいと思うんですが、その辺のご決意を聞かせてください。","respondent":"諸岡児童課長","answer":"それが一番、発見、早期対応を困難にしています。私ども、相談がいろいろございまして、緊急対応を図る場合には、まずは児童相談所のほうへ通告をします。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"私は、１２０ページの児童センターについて伺わせていただきます。今後の児童センターのより大きな改革に向けて、たくさんお話を伺いたいと考えています。宣伝も兼ねまして、今朝の読売新聞の朝刊で、東大井児童センターで、今度は食育ではなくて花育の事業を進められたと、こういう特色づくりも進められているようですので、そこら辺のアピールも含めて、今後の流れを教えていただきたいと思います。","respondent":"諸岡児童課長","answer":"児童課におきまして、平成１５年に内部検討ということで、一定の児童センターの改革についてまとめたところです。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"当然、こういう観点もさらに進めていただきたい。今後は地域の方々、特に子どもたちの遊び、また見守りを行うボランティア等も含めた地域の方々が集いやすい、そういうような施設といいますか、そういう場所になっていただきたいと非常に感じました。あえて言えば。こういう観点で、もう１回児童センターの今後の改革について、ご所見を伺います。","respondent":"諸岡児童課長","answer":"そういう意味で、これからの児童センター、地域のゼロ歳から１８歳までの児童の健全育成の拠点として、地域の方にも認められるように、地域と連携を図りながら、さまざまな活動を行っていきたいと思っているところです。","id":"exchange-050"},{"speaker":"若林委員","kind":"意見","question":"地域の方々は、児童センターがこれからどのように変革をしていくのか、変化をしていくのかを、今、じっと見ている部分があるなと感じました。今後は、この地域との距離感をどのように縮めていくのかということが、もう一つの非常に大事な観点ではないかと考えていますので、もう一遍、特に地域と児童センターとの距離感をどのように縮めていくか、これについてもう一言お願いします。","respondent":"諸岡児童課長","answer":"地域に出て行くけれども、地域の方々にも児童センターに来ていただいて、児童センターをよく知っていただくといった取組みが大事だと考えていますので、この両方をあわせて。","id":"exchange-051"},{"speaker":"若林委員","kind":"質問・要望","question":"夜、区役所におりますと、３階の正面玄関のほうにライトがついておりまして、ちょうどガラスがミラーがわりになるんですね。今回は児童センターということでご要望しますが、そういう方たちへの目的外使用として、現在は休日を除く月曜から土曜の午後６時１５分から９時半まで、また平日も土日も含めてやっておられますけれども、こういう目的外使用に対してご所見を伺いたいと思います。","respondent":"諸岡児童課長","answer":"これからもティーンズプラザ、中高生向きの館もあります。そういったところを中心に、今おっしゃったような青少年の健全育成といった事業を積極的に進めていきたいと考えています。","id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"私は１１８ページの子どもすこやか医療費助成についてお伺いしたいと思います。平成１７年の１月からこの事業が小学６年生までを対象に拡大いたしましたけれども、この所得制限を撤廃したことは大変喜ばれていると私も認識しておりますけれども、区は今度の拡大したこの事業についてどのように認識を持っておられるのか、評価をしておられるのか。そこから伺いたいと思います。","respondent":"諸岡児童課長","answer":"平成１７年の１月から小学校６年生まで所得制限をなしということで実施をしてきております。この趣旨とか目的ですが、子育て支援の一環として、具体的には経済的支援になろうかと思いますけれども、強力な子育て支援施策の一環として品川区が先進的に行っている事業です。","id":"exchange-053"},{"speaker":"南委員","kind":"提案","question":"そして今年のその点についての確認も後でしていただきたいと思います。それから、つけ足すと、市長会、そして町村会、これは東京都内のようでありますけれども、小・中学生への拡大を今年初めて東京都に要望しているとなって、この制度に対する拡大を求める声というのは住民だけでなく、さまざまな行政関係からもどんどん高まっていると認識するんですけれども、その点についての見解はいかがでしょうか。","respondent":"諸岡児童課長","answer":"子どもすこやか医療費助成事業につきましては、この間、制度運営が順調に推移してきているです。この制度等につきましては今後につきましても、やはり子育て支援策、経済的支援、それ以外のものも含めて全体として総合的に考えていく施策だろうと理解をしております。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"多方面から出ていることについての認識も伺ったのですが、答弁がないので、改めてしていただきたいと思います。私どもは改めてこの委員会の中で、中学生までの義務教育期間、すべての子どもたちを所得に関係なく医療費の無料化ですこやかに育てられる経済的な支援をしていく、子育て支援をしていくという角度からの要望をさせていただきたいと思っています。","respondent":"諸岡児童課長","answer":"先ほどのすこやか医療費助成制度についての考え方のお話ですが、私どもとしましても区長会を通じて東京都のほうへ所得制限の撤廃等の要望をこの間行ってきて、そういう努力をしてきているところです。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"これについて、やはり私はこれだけ切実な住民の要望があって、それを受けとめている行政の姿勢があるんだと見ているわけですけど、品川区でもトップを切って実施することはできなかったわけですけれども、しかしそういうことよりも、むしろ住民にとってどういうふうに生活を支え子育て支援策を進めていくかという角度からとらえていく必要があると思いますので。","respondent":"古川児童保健事業部長","answer":"総合的な観点からこの問題については慎重に検討していくべきものだと思ってありますので、今直ちに中学３年生までどうかというご質問には直ちにはお答えできないというのが現実です。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"その点からして、義務教育終了まで東京都がそういう実態になってきているところを受けて、やっぱり検討していく方向を示すべきではないかと思うんですけれども、その点についてどういうふうにお考えかどうか伺います。したがって、現実的にあるお母さんに聞いたんですけれども、ちょっと風邪を引きやすい子どもさんのようで、医療費が年間１０万円ぐらいかかるというんですよね。","respondent":"古川児童保健事業部長","answer":"都の状況、あるいは他区の状況も当然私どもは承知しているわけですけれども、この問題だけを取り上げてというわけにはまいりませんので、全体の中で慎重に検討していくべき課題、このようにお答えしたわけです。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"中学生の子どもさんの就学援助の受給率というのは、今減っているんですか、増えているんですか。ですから、その辺の整備状況が障害者の方々も自力で避難をしていくための支援の設備というのはどの程度設置されているのか、整備されているのかちょっとそこを伺って、そしてまだ不十分なところがあるのであれば、それを積極的に進めていただきたいということを申し上げたいと思うんですが。","respondent":"西島障害者福祉課長","answer":"今ご質問にありますのは特に障害者施設かと思いますが、具体的に日常生活用具の中ではそういった器具等を各家庭に条件に合わせて支給をしていますが、各施設につきましては、大きな施設についてはそういったものもありますけれども。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"障害者のための施設に限らず、調査をするのであれば、できたら公共施設全般に広げて、やっぱり整備しなければいけないところは整備するという方向でぜひ取り組んでいただきたいという要望を強く求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"大沢委員","kind":"質問","question":"私は、最初に全部にまたがるんですが返還金のことについて、次に１１１ページのホームレス地域生活移行支援事業と障害者福祉サービスの評価向上、そして、最後に１２２ページの生活保護について伺いたいと思います。","respondent":"日下部企画財政課長","answer":"これは、今ご指摘になられました１１２ページは都の支出金の返還金ですけれども、あとは国庫の支出金の返還金ということで、大きくは２種類ありますけれども、いずれにしましても、この国と都の負担金でありますとか補助金につきましては、毎年度。","id":"exchange-060"},{"speaker":"大沢委員","kind":"意見","question":"成果報告書で、今、平成１７年度をやっているわけですけれども、以前においてこれだけたくさんの返還金が出ていなかったと私は記憶をしておりますけれども、それはそれで今年の場合は何かいろいろな面で事情があったと思うんですけど、聞かせてください。","respondent":"日下部企画財政課長","answer":"これは私どもも年度の当初の見込みを立てる段階で、できる限り前年度の実績等も含めて、あるいは制度改正があればそれを踏まえて、先々１年間の見通しをしっかり立てる。","id":"exchange-061"},{"speaker":"大沢委員","kind":"質問","question":"次にホームレスの地域生活移行支援事業ですけれども、これは例えばホームレスの国の自立支援法に基づいて都が同様な事業をやってきています。その都の事業と同じように区が同じ形で出ていますけれども、先ほど品川区はホームレスが増えたということを伺いました。若干、個人情報とかいろいろな面で難しいところはありますけれども、そういう傾向には変わりないということで理解してよろしいわけでしょうか。","respondent":"志村生活福祉課長","answer":"ホームレスのお尋ねです。先ほど午前中にもお答えしたとおり、私どもも平成１６年度に個別の調査を実施させていただきました。その際に５３名の方から詳細なお返事をいただきましたので、その内容を分析しますと、以前品川に住んでいた。品川で事業をしていた。","id":"exchange-062"},{"speaker":"大沢委員","kind":"意見","question":"すいません。ちょっと簡潔にいきます。さっき住宅の支援ということで午前中にご答弁いただきましたけれども、就労の支援については近くに働き場があるからということで今聞きました。ちなみに、私がちょっと聞きたかったのは、アルミ缶を集めて生業としている。あれが間接的には就労支援になっていると私は思うんですけれども、どのようにお考えになっていますか。","respondent":"志村生活福祉課長","answer":"ただし、私どもが行っている就労支援からしますと、やはりハローワーク等を通じて、いわゆる生業についていただくということを主眼に行っておりますので、アルミ缶の収集についてはそのようにとらえてございません。","id":"exchange-063"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、アルミ缶はくしくも正業ではないと。あれで月に３万円ぐらい稼いでいるということですが、あれもやはり何かの形でリサイクルという部分で何か、確かに区とは関係ないような部分で、個人であの方たちは集めていらっしゃるわけですね。ですから、何かまた機会がありますれば光を与えていただくような何かお考えを持っていただきたいと思います。それに対してどのような体制を敷かれているのか。","respondent":"志村生活福祉課長","answer":"ただし、老人、それから障害者、児童がいろいろな意味で分野が広がってまいりました。これに個別に対応していくには、やはり個別の窓口をつくっていこうということで、品川ではそのように対応させてもらっているところです。","id":"exchange-064"},{"speaker":"大沢委員","kind":"意見","question":"生活保護についての話はこれで終わらせていただきます。今度は障害者福祉サービスのことですが、私は第１回の定例会でも出させていただいたんですが、内部障害のオストメイトの方なんですが、これは内部障害をお持ちで、外に見えにくい。オストメイトに対する対策の区のお考えを、障害に序列はありませんけれども、この内部障害の方をどのようにとらえていらっしゃるのか聞かせてください。","respondent":"西島障害者福祉課長","answer":"具体的なサービスといたしましては、いわゆるストマ用器具の支給を申請に基づいて行っているというようなことがあります。年内の予算額でいいますと、約３,０００万円程度をストマ用器具として支給しているという実績があります。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"ちなみに、都ではオストメイトの方を集めてというか、オストメイトの方たちの講習会というか集まりをされている部分があるんですが、品川区ではそういうのはやっているのでしょうか。","respondent":"西島障害者福祉課長","answer":"東京都、あるいはオストメイトの方たちが自主的に団体を構成して、それぞれ研究会なりそういう講習会をやっているというのは聞いてありますが、品川区では特にオストメイトの方だけを対象にしたそういった催し物は実施してございません。","id":"exchange-066"},{"speaker":"大沢委員","kind":"意見","question":"ちょっと款が違ってまいりますけれど、私が一番心配しているのは、やはり災害のとき彼らがどういうふうに対処をするのかということ。これは私はきちっとやっていかないといけないと思っていますので、オストメイトに限った催しはされていないということですが、やはりこれは非常に難しい問題だと思いますので、ちょっとそこのところを重く考えていただければと思います。","respondent":"西島障害者福祉課長","answer":"これに合わせて、区が単独で実施できるということで、このストマ用器具につきましては、納めていただく業者と防災協定を結ぶことを現在検討して、そういったことを考えているところです。","id":"exchange-067"},{"speaker":"大西委員","kind":"質問・要望","question":"私からは、決算書の１６６ページの国民健康保険、それから成果報告書の１１４ページの年賀状等送付、それとひとり暮らし高齢者福祉の中の食事の配食についてちょっとお尋ねしたいと思います。そして、先ほど警察というのがありましたけども、子どもの命にかかわることであろうと思いますので、そういう形で区が直接的にそういう現地調査をするという考え方があるのかどうかを教えてください。","respondent":"原国保年金課長、蓼沼高齢福祉課長、小林保育課長、諸岡児童課長","answer":"数字としてはそういった数字ですけれど、国民健康保険料の支払いができない方につきましては、ご相談の中で分納をしながらお支払いをいただく。配食の関係ですけれども、地域活動課のほうで主にひとり暮らしの配食サービス、学校給食の配食サービスを実施しておりますけれども。オアシスルームの申し込み方法等のお尋ねですけれども、オアシスルームは利用予定日の１カ月前から３日前まで。虐待についてのお話ですが、虐待に対する対応につきましては児童福祉法の中で一応の役割分担が決まっておりまして、都道府県。","id":"exchange-068"},{"speaker":"大西委員","kind":"質問・要望","question":"それとあと、高齢者の食事サービスですが、これは今の中では資格要件というのがほとんど出てこなくて、どなたでも高齢であれば結構ですよということでしたが、これはさきにほかの委員からもできるだけ外に出せという話がありましたけれども、これは当然残存能力の維持ということでは当たり前のことであろうかと思いますけれども。","respondent":"原国保年金課長、蓼沼高齢福祉課長、小林保育課長、諸岡児童課長","answer":"こういった場合についても、例えば７０歳以上の高齢者についてはそういった資格証を出さないとか。年賀状に関してですが、せっかくの貴重なご意見ですけれども、事務事業評価で、この年賀状については次回から廃止ということが決まっておりますが。しかしながら、急な必要性の方もおられますので、それにつきましては現在でも３日を過ぎても余裕がある場合、受け入れておりますし。虐待防止に関するご質問ですが、先ほど原則的な流れについてご説明をさせていただきました。","id":"exchange-069"},{"speaker":"築舘委員","kind":"質問","question":"１１３ページの認知症高齢者ケア事業、それから介護予防モデル事業、特にいきいき脳の健康教室ということで質問します。選挙中ですけども、区長は都政新報で、絶対にこれだけは成し遂げたいという公約を一つ挙げてくださいという質問で、高齢者福祉ということ。一つは認知症のケア、そして認知症の方がいると、家族の方の行動が制約される。まちにとっても、世の中にとってもマイナスになると。","respondent":"濱野区長","answer":"初日にもお答え申し上げましたけども、高齢者福祉については、高齢者の方々の数がこれからも増えていくと、これが大前提です。そういった意味では、ニーズが拡大をしていく、この拡大にこたえていかなければならない。","id":"exchange-070"},{"speaker":"築舘委員","kind":"質問・要望","question":"第一ですので、しっかりと実行していただきたいということですが、認知症ということで、「痴呆症」から「認知症」になったわけですが、英語では、「デメンティア」というふうにいうんですね。よくわかりませんけど、一応、ものの本によりますと、そうなっております。症というのはそういうことですか。その辺は国が決めていますが、区としての見解はどうかというのを教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"いろいろ総合的に勘案して、あるいは既に使っている部分ですとか等々含めまして、そういういろんなもろもろの論議の中で認知症というふうに決まったというふうに記憶しております。","id":"exchange-071"},{"speaker":"築舘委員","kind":"意見","question":"その辺にしておきまして、それで、第３期の品川区の介護保険の事業計画、いきいき計画２１では、やはり認知症の高齢者ケアの体制というのをしっかり築いているわけですね。","respondent":"蓼沼高齢福祉課長","answer":"グループホームにつきましては、地域バランスを考慮しながら、亀田邸あるいは民間の事業者が手がけるようなものもサービスの質の確保を図る観点から区としても支援していくというような形で整備する一方で。","id":"exchange-072"},{"speaker":"築舘委員","kind":"質問・要望","question":"それでも、第３段階までに分かれていて、第１段階は基礎的な課程で、基礎を修得する、第２段階では認知症に関する医学的理解と対人援助技法の進化を図る専門課程、それから第３段階では、それをさらにケアチームのリーダー層を育成するということで、高度な対応ということでありますが、その点に関して、第１段階、第２段階、第３段階というのを人によって使い分けるというか。","respondent":"蓼沼高齢福祉課長","answer":"福祉カレッジにおきます認知症ケアの専門コースの実施状況につきましては、今ご指摘のとおりです。","id":"exchange-073"},{"speaker":"築舘委員","kind":"質問","question":"そういうことで、現場対応には欠かせないという、やっぱりノウハウをしっかりと教えておいてあげるということは大切なことだというふうに思います。それを家族もわかっていないと、対応の仕方を間違えちゃうということになると、よくなるのがまたさらに悪くなっちゃうというようなことになりますので、その辺の対応の仕方、家族に対する支援というのが適切に行われているかどうかをちょっと聞かせてください。","respondent":"蓼沼高齢福祉課長","answer":"家族の方への認知症ケアの支援ですけれども、例えば各法人で家族懇談会等を実施したりとか、あるいは介護者、家族に対する研修、日帰り研修あるいは宿泊研修というものを実施しております。","id":"exchange-074"},{"speaker":"築舘委員","kind":"質問","question":"一般的に言いますと、本当に施設入所者では８割ですか、認知症だということもありますし、そういうことでの今後高齢者も増えてくるということもあります。女性はいろいろ多趣味ですし、料理もしたりして、なかなか認知症にはならないんですが、その点、やっぱり介護予防に関しては、７０歳以上じゃなくて、もう少し下げたほうがいいと思うんですけど、その点お聞かせください。","respondent":"冨岡高齢事業課長","answer":"いきいき脳の健康教室の年齢ですが、７０歳というふうにおっしゃいました。平成１７年度は７０歳ですが、今年の平成１８年度からは６５歳ということでやらせていただいております。会場も増やして積極的に事業をいたしている状況です。","id":"exchange-075"},{"speaker":"中島委員","kind":"提案","question":"これは以前、私も取り上げて心のこもったものにしてほしいという提案をさせていただいたんですが、廃止ということで、その前に、「皆様の区役所です。お気軽に何でもご相談ください」と、こういった、やはり皆さんの区役所ですというこの意識を職員の方、皆さんがお持ちになっていただけたらなと常々思っているんですが、そのことを１点、区の見解をお伺いしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"ベッドの関係ですけれども、これにつきましては、今回の制度改正で、高齢者の自立支援あるいは制度の持続可能性を高めるという観点で、状態像からは利用が想定しにくい要支援などの軽度者の方につきましては、保険給付の対象から外して。","id":"exchange-076"},{"speaker":"中島委員","kind":"質問","question":"そうですか。わかりました。わかりました。それから、２４時間の訪問介護も非常に私はうれしいことだなと思います。特に高齢者だけの所帯も増えておりますし、単身の方、そういう方たちがこれを利用しやすいようにたぶんされると思うんですが、この点の費用とか、そういったものはどのようになるのか、これを１点お伺いしておきたいと思います。その辺のところを、もう一回お願いします。","respondent":"蓼沼高齢福祉課長","answer":"夜間対応型訪問介護の利用料ですけれども、基本料が一月１,０７２円です。それから、通話料が１分につき４２円、そのほか、ヘルパーが訪問した場合の料金ということで、随時訪問が１回６２２円、定期巡回につきましては、１回３７０円という状況です。","id":"exchange-077"},{"speaker":"中島委員","kind":"提案","question":"児童福祉施設費、ここでちょっとお尋ねしたいんですが、病後児保育というものがありました。これは平成１１年に私も枚方市まで行って視察をして提案をさせていただいたものなんですが、３園で約８７８万円と出ております。ところが、児童福祉総務費のほうに、１１８ページなんですが、１園４７０人で６６０万円とあるんですが、これはどういうふうな違いがあるのかお知らせください。","respondent":"小林保育課長","answer":"ご指摘の１１８ページのほうは、病後児保育の中で、１園、私立保育園のどんぐりで病後児保育をやっております。こちらの１園というのはどんぐりで、４７０人というのは、延べの人数です。このどんぐりの実施分につきまして、区が保育助成をしているものです。","id":"exchange-078"},{"speaker":"中島委員","kind":"質問","question":"そうしますと、区立保育園のほうの３園の８７８万円というのは、これは何名なんでしょうか、人数を教えてください。","respondent":"小林保育課長","answer":"病後児保育の区立分ですけれども、こちらが西大井と、それから清水台、西五反田、この３カ所です。それぞれ西大井が３７７人、清水台が１８５人、西大井が７８人、年間実績で６４０名になってあります。","id":"exchange-079"},{"speaker":"中島委員","kind":"質問","question":"６４０名で８７８万円、４７０人で６６０万円、これが妥当なのかどうかちょっと今数字に弱いものですから、わからないんですが、どうせ載せるならば、やっぱり３園で何名とか、人数がないと、なぜここに人数がないのかなとちょっと思ってしまいますので、載せなかった理由が何かあったのかなと思ってしまいました。どういった内容なのか、簡単に教えてください。","respondent":"高橋幼保一元担当課長","answer":"こちらにつきましては、平成１５年度から１６年、３カ年におきまして、保育園におきましての幼児教育ということで、３７園に実施したものです。","id":"exchange-080"},{"speaker":"中島委員","kind":"意見","question":"先ほど教材の話が出ておりましたけれども、保育園の場合というのは、人数割では年齢の幅が０歳からありますので何とも言えないと思うんですが、単純に割るものではないと思いますけども、やはり教材をもっと充実してほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"成果報告書１２１ページの児童センター事業費についてお伺いいたします。今日、全国で児童虐待ということで、いろいろ新聞、テレビで報道されております。品川区では、主に児童センターで児童の虐待の相談を受けておりますが、この品川区役所の職員の中に、児童福祉士は何人ほどいるんでしょうか。そしてまた、品川区担当の東京都の児童福祉士は何人ほどいるのか、もしわかりましたらお願いいたします。","respondent":"諸岡児童課長","answer":"区の職員の中に、児童課の職員の中に児童福祉士はいるかですが、非常勤で１名おります。それから、東京都のほうの体制ですが、児童相談所のほうに児童福祉士ということで１６名配置されているです。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっとお聞きしたいんですけど、先ほどいろいろ虐待の相談件数等々が報告されていたんですけど、実際、「突撃」とか「突来」とか、子どもを保護するためにアポなしで突然そのお宅を訪問したり、子どもが突然助けを求めてきたり、あと実際職権で保護したりしている、そういう数はわかるでしょうか、件数。","respondent":"諸岡児童課長","answer":"これは児童相談所のほうで平成１７年受けた虐待実件数ですが、品川区内を対象として品川児童相談所が受けた数は９２件です。","id":"exchange-083"},{"speaker":"須貝委員","kind":"質問・要望","question":"今ちょっとその中に踏み込んでお聞きしたんですけど、突撃とか、急に子どもが助けを求めてきたとか、職権保護したという数はわかりませんか、今は。","respondent":"諸岡児童課長","answer":"児童相談所のほうで取り扱ったケースですが、虐待で施設入所ということで、一時保護したという形ですが、３７人です。品川児童相談所が品川区、目黒区、大田区を管轄しておりますので、３７人のうち品川区は１１人です。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"その場合に、保護施設というのは、品川区にも東京都の保護施設があるかと思うんですけど、これはちょっと参考までに足りているんでしょうか。実際、そこに一時預かるとか、そういう場合に、保護する場所はあるんでしょうか。","respondent":"諸岡児童課長","answer":"児童保護につきましては、東京都のほうでも役割分担という形でやっておりますが、かなり施設はいっぱいだというふうに聞いております。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問・要望","question":"したがって、今品川区の中で非常勤で児童福祉士が１人、もちろん東京都の中で要するにいらっしゃるという話なんですけど、やはり予防ということも大切ですけど、一番大切なのは子どもたちの命とか、親もやはり救うということを考えれば、誤って虐待をしちゃうわけですから、そういう相談員もさることながら、実際すぐ行くというようなやはり職員、対応が区のほうでも必要だと思うんですけど。","respondent":"諸岡児童課長","answer":"虐待の対応につきまして、私どもとしましては、家庭あんしんネットというのを立ち上げまして、この中で連携を密にしながら迅速な対応を図っていくということで取り組んでいるところです。地域におきましては、やはり早期発見、早期対応、迅速な対処が必要です。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"最後の質問なんですけど、今そういう対応をするということなんですが、職員がすぐとりあえずそのお宅に行ってベルを押せるような対応ができるんでしょうかということをちょっと今もう一度もし回答いただければお願いしたいのと、あと実際子どもたち、親もそうなんですけど、どこに相談すればいいんだということがやはり一番問題だと思うんですね。先生もいらっしゃいます。","respondent":"諸岡児童課長","answer":"迅速な対応ですが、地域の中に児童センターがありますので、通報があった場合、すぐ児童センターの職員が駆けつけられるというような体制はできているつもりです。","id":"exchange-087"},{"speaker":"石田委員","kind":"提案","question":"団塊の世代の人がこれから増えてくるとなると、サポしながわも含めてかもしれませんが、区としてこれからいろいろ人が増えてくる中で、今の体制のままいくというわけにもいかないとなると、ある程度もちろんシルバー人材センター本体の提案、それなりの事業運営があるわけだけれども、それを区としてはどうやって今見ているのか。","respondent":"西島障害者福祉課長、志村生活福祉課長、諸岡児童課長、冨岡高齢事業課長","answer":"駐車禁止の対象除外の話ですけど、障害者の場合は、対象が視覚障害者１級、２級、それから体幹機能と内部障害は１級から３級。私から大田寮の中での事故等についての対応はというお尋ねです。毎年、広報のほうでは、４月に子育て特集号ということで、いろんな児童センターにおいての楽しい取り組み、子育て特集として紹介をしますので。今現在会員制の、６０歳以上の会員制とあわせて、サポしながわ、これは５５歳からの部分の社会福祉協議会との連携をとりながら運営をしていますが。","id":"exchange-088"},{"speaker":"石田委員","kind":"質問","question":"大田寮からいきます。２階の床が抜けて。もっとやっぱりそういう部分は、頑張っているのはすごくわかるんだけど、そういうんじゃなくて、やっぱり品川区として、そういう子育てをもっとしっかりみんなでやっていこうよ、こういうことだって、みんなこういうふうにいろいろつらい面もあるけど、楽しい面がこれだけあってやっているんだということをぜひ打ち出してほしいなと思いますが、ご意見をお願いします。","respondent":"志村生活福祉課長、松嶋交通安全担当課長、堀越行財政改革担当課長","answer":"お尋ねの大田寮の中での事故ですけども、基本的には保険の中で対応していくということであります。駐車禁止除外の関係ですけれども、これは２種類ございまして、１種類は東京都公安委員会が出すもの、もう一つは警察署長が出す駐車許可、それで、要介護者。先ほどの委員からのお話ですけれども、次世代育成の計画の中で、基本理念といたしまして、「子どもが、人が、地域をつなぎ。","id":"exchange-089"},{"speaker":"石田委員","kind":"質問・要望","question":"担当の警察に行くのはわかるんですが、ぜひ障害者とか介護者のは窓口があるわけですから、それで、そういう形の困っていらっしゃる方というのは、たぶん品川区でも把握ができると思うんですね。そういうご相談とかがあったときは、ただ行ってくださいというか、ご相談に行ってくださいじゃなくて、やっぱり仲介ぐらいはぜひとっていただきたいなと考えていますので、それはぜひ要望だけして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国民健康保険会計と介護保険についてお伺いをしたいと思います。国民健康保険についてお聞きしたいんですけれども、平成１７年度というのは、医療分と介護保険料分をあわせると均等割が４万１,０００円から４万４,１００円に上がって、所得割が住民税１００に対して２３４から２４２に値上げをされた。","respondent":"原国保年金課長","answer":"そういった中で、先ほどの率になってありますけれど、短期証です。平成１７年度末でいきますと、５,９９４世帯、それが今年の９月末で４,８１７世帯、資格証ですけれど、今年の平成１７年度末が２０７世帯、今年の９月末で１７３世帯、こういった数字になってあります。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一つは高齢者で住民税増税に連動して国民健康保険料が値上げとなった人数について教えていただきたいと思います。高齢者何人に対して何人かということで教えていただけたらと思います。そして、その中でも、住民税非課税から課税となって値上げとなった方の人数も教えていただきたいと思います。そのために、増収となった額もわかったら教えてください。","respondent":"原国保年金課長","answer":"今回の税制改正で老年者控除の廃止、それから公的年金控除額の縮小ということでの税制改正がございましたけれど、この人数ですけれど、両方で対象になっている方が９,０００人ということで把握しています。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、９,０００人と６,０００人、あわせて１万５,０００人が４万９,０００人のうちで値上げとなったということで考えていいんでしょうか。非課税の方も含んでの９,０００人ですか。あっ、わかりました。国民健康保険料に連動すると思われる人数についても教えていただきたいんですが、５％から１０％に上がる人数、それから、１３％から１０％に下がる人数を教えていただけないでしょうか。","respondent":"原国保年金課長","answer":"結果としては、国としては難しいというところをいただいているところです。かといいましても、課長会におきましても影響が当然あるということで今考えておりますので、課長会として、何らかの対応ということで現在検討している最中です。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこれは本当に下がる人がいる一方で、所得の少ない方が上がるという、そういう仕組みにすべての障害者の自立支援にしてもそうですし、介護保険にしてもそうですし、すべての社会保障がそういう方向になっているということが本当に重大問題だと思うんですけれども、しかもこの５％から１０％にというふうなことで、賦課総額に対しての所得割というふうなことで出てくるので。","respondent":"蓼沼高齢福祉課長","answer":"基金の関係です。決算書で申し上げますと、２５７ページにこの基金の運用状況報告書が記載をされてあります。金額につきましては、約１８億５,０００万円です。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。そしてもう一つお聞きしたいのは、先ほども出ていました要支援１と要支援２、それから要介護１の方を介護ベッドや車いすの給付対象から外す問題なんですけれども、この問題では、３月時点で介護ベッドを使われていた方が８５８人、車いすが５９６人、その方が９月末でどうなったのかについて教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"この間、１月以降、この制度の説明をして、複数の代替案を示しながら対応を適切に図ってきたところです。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一般質問の答弁では、スリーモーターは必要ではないというふうなことの部長からの答弁だったんですけれども、これは介護保険ではワンモーターも、ツーモーターでも介護保険の適用になるということで、スリーモーターでなくても、そういうベッドであっても賄えるという方もいらっしゃると思うんですけれども、ベッドは軽い方でも必要だというふうなことだと思うんですけど、その点についてはいかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"その中でも、引き続き対象になる方は自力で起き上がりができない、寝返りが打てないという方ですが、これについて約１.２％の方が該当しているです。そのほか、この制度改正の趣旨に、説明してご理解いただいて、特段の自費で購入、レンタルをされなかった方が３.５％いるです。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこの実態から見て、区が必要かどうかと、必要だと思わないのかということを聞いたので、そのことについてしっかりと答弁していただきたかったんですけれども、私は今回現場の声をずっと聞いてきたんですね。今回改めて東京都がこういう対策をとりましたし、区としてもこれを受けてしっかりと区独自の施策を現場では求めていますから、ぜひとっていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"堺委員","kind":"質問・要望","question":"それに関連する形で、小規模多機能型居宅介護という件について３点確認の意味で教えていただきたいと思うんですが、なお、この件につきましては、平成１７年度の成果報告書の中にも記載がされておりますが、今申し上げましたように、確認の意味で何点かお伺いをしておきたいと思います。２０００年、いわゆる平成１２年には高齢化も１７％を超えて、平成１４年の２００２年には１８％に達した。","respondent":"蓼沼高齢福祉課長","answer":"介護予防事業につきましては、先ほどの三つの高齢者の類型の中での自立支援のうちの特に特定高齢者と言われておりますけれども、要支援、要介護状態になる、何もしないと、おそれのある人という方を特定高齢者というふうに位置づけまして。","id":"exchange-098"},{"speaker":"堺委員","kind":"提案","question":"今年度荏原南学童保育クラブの跡を利用して、こういう事業が始まりますけども、ぜひこの事業についても各地域に順次拡大をしていただきたいということをこの際提案させていただいたわけですが、その当時の保健高齢事業部長が、「この事業につきましても、順次地域バランスを考慮して実施地区を拡大していきたい」と、このように介護予防という点でお答えをいただいておりましたけども、今のご説明ですと。","respondent":"冨岡高齢事業課長","answer":"これは平成１７年度にはモデル実施を品川保健センターで実施した部分ですが、今年につきましては、さらに、先ほどおっしゃいました荏原いきいき倶楽部と称しておりますけども、そちらのほうでも実施をいたしまして、また、今工事をしておりますけれども。","id":"exchange-099"},{"speaker":"堺委員","kind":"提案","question":"そこで、今回このようなグループホームが既に小山の家、あるいは月見橋の家、あるいは平成１８年度予算のプレス発表の際にも、地域密着型という形で亀田邸跡、あるいはこれから都南病院跡地にもそういうものをつくってまいりますというふうに発表されておりますが、これからこの認知症高齢者を対象にしたこのグループホームの需要がますます高まってくる、このように思うわけでありますので。","respondent":"蓼沼高齢福祉課長","answer":"今後とも地域バランスを考慮しながら、その他のケアホームあるいは小規模多機能居宅介護といった機能もあわせながら、認知症高齢者の施設整備について対応を図っていきたいというふうに考えてあります。","id":"exchange-100"},{"speaker":"堺委員","kind":"質問・要望","question":"地域バランスを考慮しながらですが、やはり、先ほど来からも出ておりましたように、認知症の方を家族として支えていくというのは大変困難な状況といいましょうか、そういうもので、どうしても本来的には自分の家族でありますから、家庭の中で場合によっては自分の親かもしれませんから、介護したいとは思うものの、なかなか現実的には難しい場がありますから。","respondent":"蓼沼高齢福祉課長","answer":"お尋ねの小規模多機能居宅介護につきましては、亀田邸、都南病院跡地で実施してまいる予定です。はこの２カ所の実施状況を十分検証しながら今後の方向については検討していきたいと考えています。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問","question":"私は１２１ページの生活保護費、それから、生活保護受給者就労促進事業に関連して質問いたします。生活保護でありますけど、生活保護の申請から開始までの手続と、それから生活保護と認定する基準について、まずその二つを教えてください。お願いします。","respondent":"志村生活福祉課長","answer":"お尋ねの生活保護の申請から開始等に至る手続です。私どもの窓口、相談係に置いてありますけども、こちらで相談を受けます。その方のこれまでの生活経歴ですとか、それから扶養の親族等々の相談を受けます。","id":"exchange-102"},{"speaker":"伊藤委員","kind":"質問・要望","question":"認定する基準について答弁がなかったと思われますので、そのことを後で教えていただきたいのと、それから、このことについて民生委員の方といろいろ話し込むことがありまして、民生委員の方の率直な感想として、ある方は本当につめに火をともすような思いで生活をぎりぎり詰めながら、保護は受けませんと頑張っている方も中にはいらっしゃる。私も随分賛同する部分があるんですが、処遇方針の話がありました。","respondent":"志村生活福祉課長","answer":"私どもに相談に来られる方についても、よく言われるのが、私はお上の世話にはなりたくないわということで、実際は生活基準より低いかもしれませんけれども、先ほど申し上げたとおり、私ども福祉の場合、あくまでもその方が申請をするというのが原則でありますので。","id":"exchange-103"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、そういう働けると思われる生活保護対象者の方々に対して、まずどういう報告を対象者から求めているのか。それから、どういう頻度でそういう報告を求めているのかということが一つ。あわせて、そういうことに対して、品川区はどういう指導をしていくか、どういうふうなことを具体的にサポートしていくかという体制をどのようにつくっていくかということをお聞かせください。お願いします。","respondent":"志村生活福祉課長","answer":"残りの１,６００人、４２.６％なんですけど、この方がいわゆる稼働年齢層、１６歳から６５歳までですか、いわゆる働くことが十分な可能な年齢というふうに判断しています。先ほど私が説明しましたこういう方が例えば保護の申請に参ります。","id":"exchange-104"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのほうがおそらく個人個人の人生の上においては幸せなはずだと考えていますから、改めてそういう具体的なサポート体制、例えば具体的な頻度はわかりません。例えばどういうふうに報告を求めて、それから相談を受けて、それに対してどういうふうに具体的に相談に乗ってあげて、できれば就労自立につなげていくかということについてのもう少し具体的な答弁をお願いいたします。","respondent":"志村生活福祉課長","answer":"ちなみに、この辺の経費につきましては、国庫補助１０割をいただいて、国もそういう意味では、この自立の助長に向けて取り組んでいこうということでありますので、引き続きこの辺につきましては、なかなか難しい課題ではありますけれども、取り組んでいきたいと。","id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私たちとしては自立のためにこの生活保護は一つの通過点であると思っていますので、ぜひそういう方向で対応をよろしくお願いいたします。お伺いしたいのが、具体的にこれはどういうように事業を展開してきたのかということが一つ、それから、できれば、これは今後ぜひ拡大していっていただきたいと考えていますので、今後の拡大の方向性についてをお聞かせください。","respondent":"志村生活福祉課長","answer":"その一般財源の減になりましたのが１,２００万円です。ですので、先ほど申し上げたとおり人件費は国から１００％まいります。私どもの一般財源は１,２００万円下がります。こうした事業展開はこれからも続けてまいりたいと、今はこのように考えてあります。","id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問・要望","question":"時間がありませんので、要望だけしておきますけど、生活保護自体を否定するわけではありません。それはぜひきちんとやってください。ただ、あくまでもそれを私たちは一つの通過期間として考えておりますので、ぜひ自立支援の方向をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"いきいき筋力向上トレーニング、いろんな方からご質問がありましたけれども、どういった方が主に、例えば年齢であるとか、それから体調などはどういう状態の方が多く来られているのか、まずそこをお聞きします。","respondent":"冨岡高齢事業課長","answer":"いきいき筋力向上トレーニング、これは介護予防に向けた取り組みですが、対象者といたしましては、概ね６５歳以上の区民の方、それで、現在運動するのに支障がない方、あるいは事前の事業説明会と体力チェックに参加が可能な方。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"今、平成１７年度の実績として荏原地区なんでしょうか、幾つかできているということで、今後広がっていくんだという話がありました。たしかここのトレーニングの内容としては、マシンを使っているんだと思うんですね。このマシンを設置しますと、相当な金額がかかると思います。それに対しての助成金が出るはずなんですが、区の持ち出しと、どのぐらいの助成金が出ているのかお聞きしたいと思います。","respondent":"冨岡高齢事業課長","answer":"マシンにつきましては、１カ所１５０万円ということで、東京都から出ているものです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"１５０万円で今何台か入っていると思うんですが、それで全部賄えているという理解でよろしいんでしょうか。","respondent":"冨岡高齢事業課長","answer":"１カ所に４台ありますけど、ワンセットで１５０万円、こういうことです。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、４台のセットで、それぞれが使われているということで、たしかマシンだけではなかったと思うんですよね。これは数カ月間のコース型になっているので、その後、そこのコースが終わりますと、やはり継続性がないということがありますので、マシンではなくて、タオル１本でできるような、例えばレインボー体操とかいろんな種類があるんですが、その辺の導入は今後考えることはあるんでしょうか。","respondent":"冨岡高齢事業課長","answer":"いきいき筋力向上トレーニングの間ですけれども、内容といたしましては、マシン運動のほかにもウォーキングとか、それからもちろんストレッチとか、あるいは家庭で継続してできるような使わないプログラム、こういうものも入れて行っているところであります。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、もっと地域につくっていくためには、やはりそれなりの、今は全額保障されているということですけれども、簡単にできる方法がありますので、そういう意味では、もっと違う方法を使って広めていただきたいというふうに要望で終わります。その中で、委託先の変更というのはどのように今後考えられているのか、その辺についてはいかがでしょうか。","respondent":"小林保育課長","answer":"しかしなから、今までの実績の中で各業者の給食に対するサービス、質も安定し始めていますので、その辺を踏まえまして来年度の契約のあり方については協議をしてまいりたいと考えております。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"実績がかなり出てきているところがあるかと思います。その中で、いろんな業者が入られて、それなりにノウハウを蓄積して実績をつくられていったということを踏まえると、また来年度、年度契約になっているんでしょうか。入札に入ると、保育課と経理課という形でいろいろ関係が出てくると思うんですが、その関係できちんと保育課の要望を考慮した業者の選定になっているのかについてはいかがでしょうか。","respondent":"小林保育課長","answer":"私ども主管課としましては、この１年の成果と業者の正しい実績をまずきちっと伝えていくというところから経理課と協議を進めて、しかるべく公平かつ的確な業者の選定ということが実現できるように対応してまいりたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"その特徴をいい方向に持っていただいて、拡大する部分もあるでしょうし、または新たな業者が出てきて、その中での特徴を入れて、特色を入れていくとか、子どもたちのためにいろんな工夫をしていただきたいなというふうに要望したいと思います。その中で、歳入のところでちょっとお話ししたんですけれども、保育園ＰＴＡの会費とか、それから保険とかというのはどういう形になっているのか。","respondent":"小林保育課長","answer":"子どもを育てるときに、親と保育園との関係、これは親御さんが子育てをする、その必要性に応じて私ども保育事業として、また保育士として寄り添っていくということでは、親御さんの保育にかかわる機会というのを増やしていく。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そういう意味でありますと、新米の親であっても、保育園にかかわることで学んでいくんだろうというふうに思います。ただ、やはりありますと当然使うんですよね。長いほうがいいと思います。改善はあったのかどうかという点と、それから、先ほどオアシスルームの話がありました。ですから、子どもさんがなかなかほかの方だとミルクも飲まないという状況なのに、１時間という約束なのに帰ってこない。","respondent":"小林保育課長","answer":"逆に１０時までの保育が６.４％ほど増えている、こういった数字からいいますと、ある意味では総需要は安定して対応しているんですけれども、どうしても必要なところへ集約しつつあるのかなという一定の効果を感じております。","id":"exchange-115"},{"speaker":"川西委員","kind":"質問","question":"高齢者関連３点、１１１ページの福祉カレッジ、１１３ページのシルバー成人式、１１４ページの高齢者住宅、その後で児童センターと家庭あんしんセンターのことをやらせていただきますが、この高齢者関係３点一括で質問します。そういう意味で、この平成１７年度の中で、民間事業者のスタッフの福祉カレッジへの参加状況を教えてください。","respondent":"蓼沼高齢福祉課長","answer":"福祉カレッジですが、例えば臨床ケア専門コースで申し上げますと、約２００人の受講者が参加をしているという状況です。そのうち、民間事業者につきましては、約３割ぐらいの参加です。","id":"exchange-116"},{"speaker":"川西委員","kind":"確認","question":"そうしますと、民間事業者の、いわゆる派遣事業者のことなんですが、３割というと、例えば１年間のうちに全然研修会に参加させない事業者もいるんでしょうか。その辺のところの、資質の向上で、在宅福祉ですから、いわゆる民間でケアマネジャーも抱えていますよね。そういう方々がちゃんと福祉カレッジに参加の強い意思があるのかどうか、そこを確認したいんです。","respondent":"蓼沼高齢福祉課長","answer":"ですから、これに対しては３割ということの状況ですけれども、そういう独自のものとこういう外部の福祉カレッジへの参加とあわせて質の向上をそれぞれ取り組んでいるです。","id":"exchange-117","title":"議員研修会の内容と所要時間"},{"speaker":"川西委員","kind":"質問・要望","question":"広さ、それからスタッフの対応というか。じゃあ、どこがいいんだというようなわがままもありますよ、９０歳に近いから。７０歳になりまして、今年シルバー成年式に本人として行ってまいりました。しかし、催し物というんですか、昨年まで品川区の島倉さんという方が来ていまして、今年からかわりました。その内容はとやかく言うといけないのですが、どういう内容の企画の方法なのか、教えてください。","respondent":"冨岡高齢事業課長","answer":"それで、歌謡ショーの内容が変わったですが、実は平成１７年から、去年ですが、去年から変わりました。それで、去年から変わりまして、前の島倉さんが１０年と長く出ておられたということで、今回変えてみようということがきっかけで、かえさせていただいたという状況です。","id":"exchange-118"},{"speaker":"川西委員","kind":"質問・要望","question":"２０歳になる成人式は実行委員会というんですか、募集をして、いろいろ企画を練って、皆さんでご希望を出し合いながら区の予算の中で決めていくというような方式をとっていますよね。予算というのは、シルバー成年式が７５０万円あるいは２０歳の成人式は６５０万円ぐらいで、結構シルバーの成年式にお金を使っているなというふうに改めて見て思いました。要望します。ご意見を伺いたいと思います。","respondent":"冨岡高齢事業課長","answer":"委員のようにこれから新しいことを考えたほうがいいだろうということで、いろいろ貴重なご意見をいただきましたので、さまざまな角度からまた検討しながら、そちらに向けて進めてまいりたいと考えております。よろしくお願い申し上げます。","id":"exchange-119"},{"speaker":"川西委員","kind":"質問","question":"高齢者住宅では、歳入でいろいろ質問があって、申し込みとそれから入れるパーセンテージも聞いておりますので、そこは避けますが、ちょっと勘違いしているといけませんが、民間住宅家賃助成は平成１７年度で終わりでしたか。これからもやるんですか。","respondent":"冨岡高齢事業課長","answer":"民間住宅の家賃助成ですが、これは平成３年７月に始まった事業ですけれども、平成１２年の４月に新規の受け付けを廃止いたしまして、本年度、つまり平成１９年３月末をもちまして助成を終了という形で進めしています。","id":"exchange-120"},{"speaker":"川西委員","kind":"質問","question":"それを去年たしか伺っていたような気がしましたので、質問がほかに行っちゃうといけないと思いました。そうしますと、高齢者の人が例えばひとり暮らし、たまには夫婦というのもありますけれども、比較的年金の低い人たちが入る住宅の対策というのは、これからはどういうふうにしていったらいいんでしょうか。","respondent":"冨岡高齢事業課長","answer":"あわせて、所得の制限がありますが、転居等を迫られている場合の住宅のあっ旋という制度がございまして、これにつきましては、転居助成金という形で対応するということです。","id":"exchange-121"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、私はいろいろ統廃合、あるいはこれから空いてくるところをやはり高齢者住宅に本当にこの委員会が始まって、ずっと新区長、新区長というお言葉が皆さん、委員の中からも出ておりますが、やはり、もう一度そういう住宅を考えていただく方策を来年度に向けてぜひ検討していただきたい。次に移ります。総括質問も私はお当番があるもので。それから、決算ですからそういうことばかり言ってはいけません。","respondent":"諸岡児童課長、小林保育課長","answer":"そういった中で、家庭あんしんセンターそのものの機能というところまではいかないかもしれませんが、児童センターの機能を充実させて、家庭あんしんセンター的な役割も担えるような。保育園におきまして特別支援児童の概況ですが、平成１７年度実績で３６名、参考までに本年度は４０名と若干人数は増える傾向にあります。その傾向ですが、総じて軽度発達障害という部分が多いかと思います。","id":"exchange-122"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、非常にやはり条件が少ないと。ですから、私はどこかの跡地を利用して、少しちゃんとした今のあんしんセンターぐらいの規模のものをつくっていただくことがいいと思います。狭いところで、改築でやったんではだめだと思います。ですから、ああいうところは全面的に改築しまして、少し抜本的な児童センターのあり方の新しいものを模索していただきたい。横に首振らないでください。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"須藤委員","kind":"質問","question":"１１２ページの高齢福祉費に関連してと、それから時間があれば、１１６ページのシルバーセンター運営費についてお尋ねします。区内の高齢者のうち、要支援とか介護に該当しない、いわゆる元気なお年寄りというのは８割から８割５分というふうに推定をしているんですが、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"委員おっしゃるように、大体８割から８割５分です。","id":"exchange-124"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、ここでいろいろ福祉、高齢福祉、元気な方々の事業がずっと載っているんですが、考え方がいわゆる元気なお年寄りという見方をするのか、年配者でどうのという見方をしているのか、その辺がというのが高齢者の生きがいづくりとか、生きがい対策、何かしてあげようというようなことと、それから言葉の中で、いきいきカラオケ広場、いきいき広場事業、いきいき脳のトレーニング、いきいき。","respondent":"冨岡高齢事業課長","answer":"いつまでも地域の中で元気でお年寄りに生活していただきたいということで、よりボランティア等で活躍していただきたいというような思いも込めまして、生きがいづくり等に取り組んでいる部分もあります。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"何だかわからない。そういうような視点でとらえてもらえないのかな。同じように、筋力、体力をきちんと保持するためには、どういうやり方があるんだということが出てくると思うんですが、そのあたりは筋力トレーニングの数字が少ないというのは、名前もちょっと筋力トレーニングという名前だけで皆さん嫌になっちゃうかなと思うんだけど、そのあたりの差は何ですか。","respondent":"冨岡高齢事業課長","answer":"いきいき脳の健康教室につきましては、その前の年にモデル実施をいたしまして、平成１７年度はある程度本格実施という形で始めたものですので、それだけ差が数字的にはあらわれているです。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"そういう人たちがやはり同じような健康体を毎日維持していくということに必要なことは何だろうと。いわゆる好奇心を持ちます、常に笑いをとりますとか、外に出歩きます、人との会話をします、あと、睡眠、快食、快便というような、そういった健康体をキープしますということが必要だろうと思うんだけども、そのあたりはいかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"そういう意味では、このような事業につきましても、引き続き進めていきたいというふうに考えているところです。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"先ほど来あります税の関係もあって、今まで非課税だったのが課税になると１,０００円だったのが２万幾らになっちゃうよというような極端な差が出てきています。そのほうが結果的にはいい結果を生むんじゃないかと思うんですが、そのあたりはいかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"先ほどのご説明のところ、不十分な点がございました。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"元気な方々が元気に毎日過ごせるようなシステムづくりを全体的に見ていっていただければと思いますので、よろしくお願いします。そういったときに、シルバーセンター自体が今までのままでいいんだろうかと、その辺の全体的な絵の流れの中でつくっていったほうがいいんじゃないかと思うんですが、そういった考えはいかがでしょうか。","respondent":"冨岡高齢事業課長","answer":"現在の利用者ですけれども、やはり、３６万ということで、去年に比べましても増えているという状況がありまして、シルバーセンターを利用されることで交流とか図られている方もおいでになると思いますが。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問・要望","question":"もちろん使っているのは事実なんだけども、全体的な絵の中で、それなりの役割をつくっていくような形で踏み込んでいってやれば、場所によってはほっとサロンみたいなものがつくれない地域もあれば、そういうところを活用する、あるいは地域センターの一部をどうするのかとか、いろんな絵の書き方があると思うんだけど、いわゆる高齢者に対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"三上委員","kind":"提案","question":"ところが、職員の人たちも含めて、年齢の若い人たちが、むしろ積極的にこのグループが使用するというんであれば、じゃあいすを並べなきゃならないなとか、こういうことでの積極的な絡みというか、接遇的な部分について、やはり、一歩そういう考え方に立った指導というものを徹底していただきたいということでお願いしたいんですけれども、そこらあたりはどういうふうに取り組まれているか。","respondent":"蓼沼高齢福祉課長、諸岡児童課長、冨岡高齢事業課長","answer":"今後整備されます亀田邸、あるいは都南につきましては、設置をしてまいる予定です。児童センターにおきまして、悪質商法対策ゲームですか、これの導入につきまして、このゲームの内容につきまして、よく中身を検討させていただきまして。シルバーセンターのいすの件ですけれども、積極的に対応するように職員と人材センター等を問わず、指示をしています。","id":"exchange-131"},{"speaker":"三上委員","kind":"質問・要望","question":"もっと小規模なものであれば、水道管直結ということもあるわけですから、それは国の制度にまでさせていった品川区であるわけですから、そういったことを活用するということ、それを取り組んだ形でまた全国にも品川区はこういうことをやっているというようなことでの導入というものも図っていっていただきたいとお願いするわけですけども、時間があったらちょっとお願いしたいと思います。","respondent":"冨岡高齢事業課長、蓼沼高齢福祉課長","answer":"具体的な場所等をお伺いした上で、よく対応します。消防設備と安全対策については、さまざまな制度の活用を含めて十分配慮していきたいというふうに考えてあります。","id":"exchange-132"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１１７ページ、児童福祉費に関連してお尋ねいたします。特に私は非常勤職員が増えている問題について、保育関係で聞きたいのでよろしくお願いします。最初に品川区が行っている保育事業の現時点の正規職員の数と、非常勤と派遣の職員の数がそれぞれどれぐらいになっているのか、それから、本来の職員の定数と、財政効果はどうなっているのかについて質問したいと思います。","respondent":"小林保育課長","answer":"それで、事業を行っていく上での人材の活用ですが、基本的には各事業を行っていくのに十分な人員構成ができているというふうに考えております。","id":"exchange-133"},{"speaker":"沢田委員","kind":"意見","question":"十分な人員構成、私が聞いたのは、保育園職員が何名かということと、それから、非常勤等に置きかえたことによって財政効果は、昨日何か６億円の財政効果があったと言ったけど、保育の分野ではどれぐらいの財政効果があったと判断しているのか、平成１７年度は、それを聞いています。","respondent":"小林保育課長","answer":"定数を保育士で見ますと、定数は直近のものですと、５７１人というふうに考えております。","id":"exchange-134"},{"speaker":"沢田委員","kind":"意見","question":"それが出ないと、財政効果、昨日６億円とかとおっしゃっていましたよね。どうやって出したのかなというふうに、わからないので、改めて、保育課長レベルでわからなければ、財政担当なり何なりで説明を願えればありがたいと思います。そこらについての考え方をお尋ねしたいと思います。","respondent":"小林保育課長","answer":"そもそも事業を行っていくときに、例えば私ども保育士、保育事業が長年培ってきたノウハウ、それから経験、それを生かすという点からいえば、例えばその事業を行っていくときに、１名の経験豊かな職員がいたときに、それを経験の浅い正規職員、ときにはそれが派遣職員であったり。","id":"exchange-135"},{"speaker":"沢田委員","kind":"質問・要望","question":"もう少し実態をお尋ねしたいと思うんですが、３９４人と８７人の非常勤、派遣の人たちが、年間どれぐらい退職しているのか、あるいは新規にそこから募集をしているのかという数がわかれば教えていただきたいということと、それから非常勤職員に限った場合ですけれども、月額の実収入は大体どれぐらいになるのか、わかったら教えていただきたいと思います。","respondent":"小林保育課長","answer":"しかしながら、例えば平成１７年度の状況でご説明いたしますと、年度当初に対して、年度中に新たに変わりました人員として、２０名前後の派遣職員の異動があったというふうに考えておりますが、これにつきましては、派遣職員の性格から。","id":"exchange-136"},{"speaker":"沢田委員","kind":"質問","question":"非常勤の保育士でやると１,５００円ですから、月額１１万２,５００円、先ほど答弁がありましたけど、４１歳から５５歳までの生活保護の基準が８万１,６１０円で、このほかにたしか５万３,０００円ぐらいの住宅補助が出ると思いますから、そうすると、いずれも生活保護の基準を大幅に下回っている。雇用保険はどうなっているのかをあわせてお尋ねしたいと思います。","respondent":"小林保育課長","answer":"社会保険等につきましては、派遣職員につきましては、もちろん派遣先の雇用の中で対応されているものですが、非常勤職員につきましては、非常勤制度、区統一の制度といたしまして、現在４時間ないし５時間の非常勤職員については。","id":"exchange-137"},{"speaker":"沢田委員","kind":"質問・要望","question":"なぜやらないのか。ですから、１年で切っちゃうんです。私は改めて非常勤の人たちや派遣の人たちが、品川区の職員と負けず劣らず一生懸命働いてやっているんですから、改めて１,２００円の時給の引き上げの問題、あるいは社会保障の適用の問題、一時金の支給の問題、長期雇用を望む人には正規雇用の道を開く問題などについて、根本からの待遇改善を求めたいと思いますが、いかがでしょう。","respondent":"小林保育課長","answer":"その非常勤職員を３時間、ないしはもっと前は長かったじゃないかということですけれども、これは事業を運営していく場合に、最も最適な配分をということから、正規職員のシフト等を考えたときに、逆に非常勤職員の方に６時間、８時間ということではなくて。","id":"exchange-138"},{"speaker":"沢田委員","kind":"質問","question":"たしか３年前、ちょっと年数は一、二年ずれるかもしれないですけれども、これが導入されたときに、非常勤の方からこれをやらないでほしいというのがものすごい勢いで出ましたよ。それなのに、率先してこういう不安定雇用、安上がりの雇用、労働条件劣悪なとは言いませんけれども、常勤と比べてかなりの差があるような状況をすることが、地方自治体としてのやるべきことなんでしょうか。","respondent":"古川児童保健事業部長","answer":"私の聞き間違いじゃなければよろしいんですが、保育園における短時間労働者を部品として見なしているというような発言がもしあったとすれば、大変残念でありまして、今、３時間の非常勤の問題、あるいは７時間、８時間の非常勤を短時間に、数年前でしょうか。","id":"exchange-139"},{"speaker":"沢田委員","kind":"質問・要望","question":"それならそれで労働条件を変えてもらうように、一般職員と同じ仕事、等質の仕事であるならば、そういう努力をしていただきたいと思います。あるいは今日の保育園の状況はどうなのかということが聞けないということが最大の親からの不安の声として出されています。これもパッチワーク保育と言っていますけれども、こういう不安定雇用をやった結果だということを示して、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"林（宏）委員","kind":"確認","question":"こんばんはの時間になりました。最後ですから、なるべく一発回答ですぱっと終わりたいと思いますので、よろしくお願いいたします。ちょっと細かい数字で申しわけないと思うんですけれども、決算の数字ですから、確認をさせてください。４万円幾ら合わないんですけど、この数字の説明をしてください。葬祭費のほうが、１,８２４件。こういう予算って、たまたま偶然なんですかね。それから、あと２つ。私立。","respondent":"原国保年金課長、日下部企画財政課長、小林保育課長、蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"実績を当然平成１７年度については計上していますので、たまたまぴったり合ったです。ですから、次のもう１点の、それに昨年の４月から５月末の平成１６年度分の出納閉鎖の部分がこれに加算をされて。各園の定員についてですけれども、もちろん施設の基準、それから人員配置の基準を満たす範囲内で、定員の弾力化ということで。委員おっしゃっておりますのは、二葉一丁目に開設予定のものだと思いますが、この計画は、まず基本的に介護つき有料老人ホームということで。","id":"exchange-141"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そのタイムラグはわかります、２カ月の。だけど、ここに入っていると、平成１７年度の決算書ですから、１７年度のお金の動きがあって、それは平成１６年度の分のお金だろうと僕は理解、４万何がしかというのは１６年度のお金で、１７年度の決算額としては三千九百何万だという。介護付きなんですか。老人医療会計のほかにもう１つ会計ができるのかなという疑問も出てくるわけで、その辺を説明してください。","respondent":"冨岡高齢事業課長","answer":"後期高齢者の会計ですけれども、老健会計は清算の部分がありますので、２年ほど残ります。それから、新たに特別会計をまたつくりまして、保険料は区のほうで徴収いたしますので、それに対応するようになっております。","id":"exchange-142"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、老健会計というのはなくなって、後期高齢者医療会計と呼ぶのかどうかわかりませんけれども、新しい特別会計になると。そうすると、老健そのものが全部なくなってしまう。じゃあ、７４歳までの人たちはどこで対応してくるのかなと、そういうここが変わりますよというのをちょっとわかりやすく説明をお願いします。","respondent":"冨岡高齢事業課長","answer":"そうしますと、約半年間で、先ほど申し上げました平成２０年の４月にはその方たちがもう７５歳になっておいでになりますので、移行していくと、こういうことです。","id":"exchange-143"},{"speaker":"林（宏）委員","kind":"意見","question":"わかりました。７５歳以上の方はこういうシステムの中で医療を受けていく。じゃあ、７４歳までの人、今、いわゆる老健の対象になっている方々はどこでどういう仕組みの中で品川区は医療制度を組み込んでいくのかなというのを聞かせてください。","respondent":"原国保年金課長","answer":"今、高齢事業課長が申し上げましたように、従来は７０歳から老人医療でございましたけれども、この５年間で老人医療の対象年齢を上げております。そうした結果、その方々については、国保加入者であれば７４歳までの方は国保加入という形になってあります。","id":"exchange-144"},{"speaker":"林（宏）委員","kind":"意見","question":"なぜ後期と呼ぶのか。後期というのは、前期があるから後期で、７４歳まで０から７４は前期ということになるのもおかしいでしょう。だから、わざわざ後期とつけるのは、現在は７５というラインがあるよというんでしょうけれども、これから先は、僕は要らないような気がするんです。これは広域連合でやることで、品川だけつけないとかはないんでしょうけど、考えだけ聞かせてください。","respondent":"原国保年金課長","answer":"後期があれば前期があるです。前期につきましては、６５歳から７４歳までを前期高齢者ということで位置づけております。その方は国保です。","id":"exchange-145"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/249249?Template=document&Id=1264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":119386,"voices":339}},{"id":"h18-20061018-4","meetingId":"h18-c-settlement","date":"2006年10月18日","dateIso":"2006-10-18","committee":"決算特別委員会","time":"午前１０時０３分～午後６時１０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","topics":[{"id":"topic-01","title":"◯松澤委員長 ただいまより決算特別委員会を開会いたします。 それでは平成１７年度品川区一般会計歳入歳出決算","agenda":"◯松澤委員長 ただいまより決算特別委員会を開会いたします。 それでは平成１７年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"ひとつよろしくお願い申し上げます。１つ、ここでお伺いをさせていただきたいのは、近年の品川区においてのカラスの数というか、カラスの増減というんですか、近年カラスが増えているのか、それとも減少しているのか、どっちなのかということと、それから推定でよろしいんですけれども、東京都および品川区のカラスの数をちょっと教えていただきたいと思っているんですが、よろしくお願いいたします。","respondent":"田中環境課長","answer":"簡単に言いますと、大きく巣の撤去等、昨年から補助制度をつくって運用しておりますので、その効果があらわれてきたのかなと思っておりまして、ちょっと委員ご質問の増えているという認識と違って、相談件数等も減ってきているし、全都的な状況としても。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"大変区のほうも努力されているということで、すみません、そのような話をどうしても住民の方から伺うものですから、ちょっと質問させていただきました。それから現在、カラスを減少させていく方法というのは、やはり巣を撤去するしか方法はないんですか。それとまた将来、何かカラスをもっとより減少させる策というものを区のほうではお考えになられているのか、その辺をお伺いできればと思います。","respondent":"田中環境課長","answer":"抜本的には、カラスのえさになるようなものを出さないことが大切なわけですので、きちっとしたごみの処理等をやっていただくということの対策の積み上げと、昭和６０年ごろはカラスが７,０００羽ぐらいだったわけですので、それに向けて捕獲。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"次に私が質問させていただこうと思ったんですが、今、ごみの問題が出ました。カラスは何か黄色いものにすごく拒否反応を起こすということで、黄色いごみ袋というものを今後推進していくという話を聞いておりますけれども、品川区のほうではその黄色いごみ袋というものをどう、これから住民に対して推進をしていくのかということをちょっと伺いたいのですが。","respondent":"中山資源循環推進課長","answer":"従来、集積所に対して、ごみ用のネットを出していたんですけれども、今、ご質問があった戸別収集に対応して、袋の研究をやっております。平成１７年度も区民の方、約３６０人、それから事業所にも約３４０カ所ほどに配って、この黄色の袋の実験を行いました。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"続きまして迷惑猫、いわゆる野良猫の問題についてちょっとお伺いします。ペットで一番多いのは犬か猫かということだと思うんですが、飼い犬は行政に対して登録をするんですが、これはちょっと質問なんですが、何で飼い猫は登録しなくていいんでしょうか。","respondent":"谷田部健康課長","answer":"犬の登録につきましては、狂犬病予防法という法律がございまして、その法律に基づいて飼い主が登録する義務があるということで制度があります。ただ、猫につきましては、そういうような登録する根拠法がございませんので、そういう意味では登録制度はないです。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問・要望","question":"今、区に寄せられている野良猫に対しての苦情というんですか、その内容と件数というのを教えていただきたい。","respondent":"谷田部健康課長","answer":"件数のほうについてはちょっと把握してございませんが、苦情の多い内容で言えば、いわゆる飼い主のいない猫によって、ふんですとか尿ですとか、その辺が非常に迷惑だというような苦情が多いということと、それからむやみやたらにえさをあげていて。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"この制度はどういうのかというと、その自治体の職員が野良猫に餌付けをしながら、捕獲をし、捕獲をした後、不妊、それから去勢の手術をし、そして駆除しないで、生き物ですから、共存しながら減少させていくという取り組みをしているらしいんですが、品川区としてはこの野良猫、この件数を見ますと３４件、野良猫を捕まえて、それで手術をしているんですが、この野良猫をどうやって捕まえて。","respondent":"谷田部健康課長","answer":"品川区におきましても、昨年から飼い主のいない猫との共生プランということで、区内全町会、自治会にこのようなプランを進めていきたいということで、昨年の１１月１０日、庁舎内において説明会を開きまして、そこでいわゆる飼い主のいない猫の繁殖をこれ以上増やさない。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問","question":"初めてのことですから、次の緑化維持費について、ちょっと質問させていただこうと思ったんですが、もう時間がありませんので、これにて終わらせていただきますが、これからひとつ、またよろしくお願い申し上げます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"清掃関係の問題で質問したいと思います。そして、自治体負担が増えているということについて、区はごみ行政を進めていくのに当たって、どういう見解を持っておられるのか、まずここから伺いたいと思います。","respondent":"中山資源循環推進課長","answer":"いずれにしても効率的な収集の体制を組んでいくという考えをしっかり持ってやってきているということです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"自治体負担が増えてきている傾向にあるのかどうかという認識もちょっと伺ったんですけれども、改めてその点について答弁をいただきたいと思います。そして処理をする自治体の負担が増えるばかりとなっているんじゃないかと思うんですね。","respondent":"中山資源循環推進課長","answer":"ただ、先ほど申し上げたように、区ごとのいろいろな独自の取り組みも含めて、重点的に体制を組むものはやっていくという考えでありますけれども、その際に当然繰り返しになりますが、効率的な運営を工夫していくという考えでやっていきたいと考えています。","id":"exchange-009"},{"speaker":"南委員","kind":"確認","question":"それで廃プラスチックの焼却と、そして今度売電をするということで、新会社を設立するということになってきており、この品川区としても５２０万円の出資金を出していくという補正予算が組まれてきているわけですけれども、こういう問題について、中央区と港区と杉並区だったか、３区がこういう状況については反対だという表明をしていると聞いておりますが、その点についての確認をしたいのと。","respondent":"中山資源循環推進課長","answer":"きちんとＰＲしていくことが大事だと考えています。それから焼却の安全性についても、２３区の中でそういった事故は一切ございませんし、きちんとした今までの東京都時代から培った経験を踏まえて、安定的に運営していくものと考えています。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"分別をしていた廃プラスチックを今度は燃やしていくわけですから、分別をここではしないわけですね。ですから、分別はするから変わらないんだということは違うじゃありませんか。そして最後に時間がないから、申し上げますけれども、黙ってお聞きください。そして５年前からだと思いますけれども、３３％のごみの減量に成功したということで、今、結構脚光を浴びているじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"武内委員","kind":"提案","question":"私は１２３ページの自動体外式除細動器設置費、１２５ページの飼い主のいない猫、１２９ページの資源回収、時間がありましたら１２４ページの健康診査普及事業の４点についてお伺いしたいと思います。それで今回、ここの衛生費の中で出てきているという、その辺の考え方というのを教えていただきたい。","respondent":"谷田部健康課長","answer":"歳入の関係で申し上げますと、これは東京都の包括補助金の制度、１０分の１０の補助を活用しまして、歳入のほうで計上しているものでございまして、ＡＥＤは区民の健康に直接結びつくという内容ですから、歳出のほうでは衛生費の科目の中で補正をお願いしたという関係です。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、それぞれの款であえてやらずに、ここでまとめてということで、そういう考え方でよろしいでしょうか。後であわせて聞きたいと思います。それから今の、ここで５３カ所と、小・中学校、教育費のほうで７９カ所と、１３２カ所設置というふうになっていますけれども、すべてこれは設置されているというふうに理解していいのかどうか、あわせて教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"それから設置の状況ですが、昨年、最終補正でお願いいたしまして、議決を待って速やかに購入し、すべての施設に設置しているという状況です。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"それであわせまして、私どもも議会で１回、講習を受けさせていただいたんですけれども、また学校も含めて、職員の方についての講習というか、研修についてはある程度行われていると思うんですが、その辺の状況と、あと実際にＡＥＤは設置されていますけれども、これまでに倒れたとかということで、使用したケースがあったのかどうか、それをあわせて教えてください。","respondent":"谷田部健康課長","answer":"講習の関係ですけれども、今年の補正に向けて、３月の当初から、１６回ほど分けまして、職員それから区民の皆様方にお声をかけさせていただきまして、約３００人の方に対して今回の設置に向けて講習を実施したという状況です。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"講習のほうも着実に行われて、また使用も幸いないということで、非常に安心しているんですが、ただこれからいつ、どういうような形で使うことがあるかわからないという中で、今、たしかこの当時、補正のときに組み入れて購入していただいた際には、まだ薬事法とかいろいろな関係で、ＡＥＤについては８歳未満、体重２５キロ以下の方については。","respondent":"谷田部健康課長","answer":"設置したときのＡＥＤの使用の対象者は８歳以上の者に限るという国の定めがございました。当然８歳以上に対応する、いわゆる電気ショックを送るパッドなんかも、そのようになってあります。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"４月２１日、厚生労働省で承認されまして、いわゆる小児用のそういったパッドというのが７月ぐらいから発売されているということなんですね。これは正しいかどうか、もしわかれば教えていただきたいんですけど、一応フィリップス社製のＦＲ２という除細動器については、そのパッドが使用できると。その辺も含めて、もしわかれば、どこの社のだということを教えていただけますか。","respondent":"谷田部健康課長","answer":"平成１７年度に購入いたしましたＡＥＤにつきましては、フィリップス社製のハートスタートＦＲ２という機種を区長部局、それから教育委員会とも購入いたしました。計１３４台です。","id":"exchange-016"},{"speaker":"武内委員","kind":"確認","question":"そういった細かいのは結構なんですけれども、ＦＲ２のほうも購入されているということなので、ＦＲ２に関しては１万９,０００円で小児用パッドというのは対応できると、私は聞いているので、ぜひこれは確認していただいて、金額的にもそれほどのものではないので、やはり８歳以下の方、こちらの区庁舎にしても、地域センターもそうですけど、幼児も来ますし、ぜひこれは検討していただいて。","respondent":"谷田部健康課長","answer":"今の小児用パッドというのは、私もちょっと勉強不足で申しわけございませんが、現在設置してあるＡＥＤに小児用パッドをつけ替えて対応できるものなのか、それともＡＥＤ本体に小児用パッド、いわゆる子ども専用施設にもとから専用のＡＥＤとして開発されたものか。","id":"exchange-017"},{"speaker":"武内委員","kind":"質問・要望","question":"私が確認したところだと、そのＦＲ２ですと、ＡＥＤ自体を替えなくてもできると確認していますけれども、一応もう一回確認していただいて、パッドについては別に小さいのと大きいのがありますから、その辺は理解できれば対応できるかなと思いますので、要望します。","respondent":"谷田部健康課長","answer":"飼い主のいない猫との共生プランに実際に取り組んでいただいているのは、上大崎の目黒駅前の町会が１カ所ございまして、昨年から生息数の調査ですとか、それから生息場所の確認ですとか、そういうことを行いまして、ボランティアの方と調整しながら、餌付けして、捕獲して。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"モデル地域を絞ってやられた中で、今年度も予算がついていますので、実施されているということで、ぜひ拡大してもらいたいんですけど、ただ、今たしか前も個別にご質問しましたけど、期間を限定してやっていらっしゃると思うんですけど、いつごろこれはやっていらっしゃるんですか。","respondent":"谷田部健康課長","answer":"昨年１１月１０日に区のほうのこのプランの説明会を開いて以降、興味関心のある町会の申し出があって、私どもは一緒に取り組んでいるわけでございまして、興味は示したけれども、なかなか取り組むまでには至らない町会が３つ、４つあるですので。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問・要望","question":"共生プランの話をちょっと今、聞かせていただきたいんですが、この飼い主のいない猫、地域猫の去勢・不妊の助成は期間が決まっていませんでしたっけ。何か前にお聞きしたときは期間が限られていて、通年はできないよという話を聞いたんですけど、その辺をもう一回確認させていただきたい。","respondent":"谷田部健康課長","answer":"飼い主のいる猫につきましては、年２回助成期間を定めまして、実施はしています。飼い主のいない猫につきましては、いろいろ定住しているわけではございませんから、通年助成ができるという制度になってあります。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"前にやっぱり地域の方から相談があって、お聞きしたとき、じゃ、私の勘違いだったと思うんですけど、期間が限られているというお話だったので、やっぱりいつそういう事態になるかわかりませんので、ぜひそれを通年にしてもらいたいなと、今要望しようと思ったら、できているということなので、これはこれで結構なんですけど、あとは予算についてですけど、実績を見ながらで結構なんですけど、毎年。","respondent":"谷田部健康課長","answer":"先ほどの答弁を訂正します。飼い主のいない猫、飼い主のいる猫ともに、助成期間は２回ということで、募集期間を定めさせていただいて実施しております。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"この間も地域の方と懇談した際に、やはりどうしてもそれが気になるということで、お話しいただいて、いろいろ区も出す人の意思を表示できるようなごみ袋をつくっていただいたりとか、また緊急通報があった場合のパトロールとか、いろいろやっていただいているというのは、よく理解しているんですけど、第１回定例会のときに、ほかの各区の取り組みも参考にしていただいて。","respondent":"中山資源循環推進課長","answer":"そういう意味で、１年以上継続されているということで、なかなか論点として、これを刑罰の対象にできるかどうかということについて、明確な判断が出ていないという状況です。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問・要望","question":"では時間がないので、これを要望させていただいて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"木下委員","kind":"質問","question":"その点、品川区内の現状はどうなのか。品川区内は大丈夫だとは思うんですけれども、報道等で一般の方々も心配等されていらっしゃるのではないかと思いますので、お聞かせ願えますでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"現状の医師不足ですが、区ごとの正確な数字というのは、こちらでは把握しておりませんけれども、一般的には東京都内では比較的、条件はいいということではあります。ただし、全般的にはやはり産科、小児科の医師不足が進んでいる状況です。","id":"exchange-024"},{"speaker":"木下委員","kind":"質問","question":"品川区内はそういう点では今のところ、医師不足についての問題はないという理解でよろしいんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"現状では取り立てて大きな不具合が生じている状況ではないという認識をしております。","id":"exchange-025"},{"speaker":"木下委員","kind":"質問","question":"それで助成金のことについて、ちょっとお聞きしたいんですが、医師会についての助成金１,１２０万円ありますね。獣医師会、薬剤師会、４０万円、歯科医師会は３００万円。やっている事業についての助成金ですから、医師会といいますと、命にかかわることですので、それなりの部分はあるかと思うんですけれども、その違いについての特徴といいますか、そういう部分をお教え願えればありがたいんですが。","respondent":"谷田部健康課長","answer":"医師会それから薬剤師会、獣医師会等々、さまざまな関係で区民の公衆衛生、それから健康のほうの事業に取り組んでいただいてありますので、その事業内容等によって、助成額が変わってきますし、それぞれ区のほうの事業との連携、それから区民に対するさまざまな事業ということで。","id":"exchange-026"},{"speaker":"木下委員","kind":"質問","question":"助成金の大まかな部分で、かなり金額が多い部分での事業というのは、どういう事業なのか、ちょっと教えていただければありがたいんですが。","respondent":"谷田部健康課長","answer":"それから区民の啓発用にさまざまな事業を行ってございまして、例えばこの間、区民の公開講座、メタボリックシンドロームの関係の講習会を行ったりということで、いわゆる社団法人としての、公益法人としての公益事業というような取り組みの中で。","id":"exchange-027"},{"speaker":"木下委員","kind":"質問","question":"それで、一応設備関係はかなり助成でかかっているということで、１２５ページの予防費として、肺がん検診、うちの会派の高星議員、区民検診で肺がんを発見することができずにご逝去されて、そういう肺がんですとか、そういうのに対する検査、先ほどヘリカルコースがかなり助成でかかっているということなんですけれども。","respondent":"谷田部健康課長","answer":"それで、がん検診の受診率の関係ですけれども、４０歳以上の人口に対して対象人口率というのがございまして、職域で検診を受けられる方もいらっしゃいますので、そういう方を除いて、おおむねの対象人口率、大体がん検診については、７５％が目安なんですが、非常に低くて。","id":"exchange-028"},{"speaker":"木下委員","kind":"質問","question":"人数が肺がん検診で５,０５２人、それからヘリカルコースを受けていらっしゃる方が６７７人ということで、先ほどレントゲンでもなかなか見つからないというのがありましたから、ヘリカルコース、私も昨年ヘリカルコースを受けまして、ものすごく鮮明に肺の中をヘリカル検査で診ることできるということで。","respondent":"谷田部健康課長","answer":"表現は悪いですけれども、首に縄をつけて引っ張っていくわけにはまいりませんので、自分自身、年１回の基本検診を受ける。","id":"exchange-029"},{"speaker":"木下委員","kind":"質問・要望","question":"昨年、カラス実験を２つやったということを聞いております。それが先ほどの区民３６０人の方に実験してもらった際に黄色いごみ袋だと、カラスが袋をつつきにくくなっていると、お話しされていましたけれども、この実験でのことなんでしょうか。それと２つの実験というか、テストをやった際の具体的な結果報告というか、どういう状況、または結果だったのかというのをお聞かせ願えればありがたいんですが。","respondent":"中山資源循環推進課長","answer":"ただし、例えばからし入りの袋については、ちょっと成分の関係で水漏れがあるとか、使い勝手の問題等がありましたが、話題になっています黄色のごみ袋については、昨年も今年度も９０％以上、９５％ぐらいが被害がないということで、先ほど申し上げたように。","id":"exchange-030"},{"speaker":"木下委員","kind":"質問・要望","question":"ただ袋の費用対効果で、あまりにも高いようだと、やっぱり区民の方の利用というのも図れないかと思うんですが、大体黄色いごみ袋にすると、普通の２３区の従前のごみ袋と比べて、費用的にはどのぐらいの違いがあるものなんでしょうか。","respondent":"中山資源循環推進課長","answer":"ただ開発当初よりは値段が下がってきておりまして、杉並区では先ほど申し上げたように、既に一部で購入できるようにしておりますが、広がっていくと下がる可能性もあるかなということで、品川区も先ほど申し上げたような区民の方が使いやすい形にしていくと。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"そして３点目は、このように商店街振興にお金を投入、税金をかけておりますが、いわゆる２３区の中では多いほうなのか、少ないほうなのか、また真ん中あたりにいるのか、３点ほどお伺いいたします。","respondent":"金子産業振興課長","answer":"そういう意味で、地元のさまざまな改革、例えば装飾灯、あるいはイベント等の実施に対して、私どもとしましては、そういう意向に対して積極的に支援していくという姿勢を持っておりますので、現時点におきましてはご指摘のとおりであると考えているところです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"確認","question":"品川区がトップということで、改めて品川区が商店街に力を入れているということを再確認させていただいたんですが、その中にやはり商店街の活性化支援という意味で、空き店舗対策というのがあると思うんですが、今、区が把握している空き店舗の状況というのはどうなっているんでしょうか。","respondent":"金子産業振興課長","answer":"品川区の状況なんですが、うろ覚えで恐縮ですけれども、大体この東京都の平均に近くて、一商店街当たり３から４店あると記憶しています。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"いろいろな自治体に視察調査に行きますと、商店街に関しては、必ず空き店舗対策って出てくるんですけれども、その中であまり成功している例は見受けない中、品川区においては北品川地区の飲食店とか、大井銀座の食育ステーションとか、あと中延のまちのコンシェルジェが東京都の賞をもらったということで、成功していると思うんですけれども、品川区の今後の空き店舗対策を具体的に教えていただけますか。","respondent":"金子産業振興課長","answer":"家賃補助に関しては３年に限るというふうにしておりますので、いかに４年目以降、自立させていくかというのが課題で、今、委員が例に挙げていただいたものも、これから４年目に徐々に入っていくわけですので、それをどう自立させていくかというのが。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、観光推進事業についてお伺いしますが、昨年度、観光アクションプランを策定しまして、私が今年の第１回定例会で質問したときに、この観光アクションプランは全庁的に取り組んでいくというご答弁をいただいたと思うんですけれども、今年は多分、初年度という意味において、具体的に、全庁的にというのはどのような形であらわれていっているんでしょうか。","respondent":"金子産業振興課長","answer":"観光事業の推進に関しての進め方ですけれども、今年度、たしか６月だったと思いますが、観光に関係する所管を集めまして、昨年度、私どもで策定しました観光アクションプランの内容、また今後の観光推進事業の進み方について、具体的にどう連携していくかということを協議して。","id":"exchange-035"},{"speaker":"三村委員","kind":"質問","question":"９月末に清掃一部事務組合の議会のほうが開かれまして、新会社設立についての審議がされたかと思いますけれども、今までこの議会は全会一致で進められてきたと聞いているんですけれども、今回は中央区、港区、杉並区のほうが賛成されなかったというふうに、先ほど別の委員からも出ておりましたけれども、今回、品川区のほうでは補正予算が出されておりますけれども、当然。","respondent":"中山資源循環推進課長","answer":"その際に、基本的な考え方であるとか、企業としての採算性をどういうふうに確保していくのかとか、そういう改めてのご質問があったということは伺っております。","id":"exchange-036"},{"speaker":"三村委員","kind":"質問・要望","question":"合弁会社ということで責任体制が不明確なのではないかというような問題点が指摘されておりますけれども、その点について、区としてはどのようにお考えなのか、お伺いいたします。","respondent":"中山資源循環推進課長","answer":"これは先ほどもちょっとご説明いたしましたけれども、清掃一部事務組合の抜本的な改革という中に経営計画、それとこの３年間の集中的な取り組みとして、経営改革プランというのが定められておりまして、その中に具体的なアウトソーシングのあり方ということで出てきたものです。","id":"exchange-037"},{"speaker":"三村委員","kind":"質問・要望","question":"２３区がイニシアチブをとってやっていくということだったんですけれども、今回、この設立に関連して、２２日に港区のほうで議会として清掃一部事務組合のほうに質問状を出されているんですね。そうしたところ、受け取りを拒否されてしまったというような事態も起こっているんです。２３区に対しても負担が求められてくるようになるのではないかと思いますけれども、その点についてお伺いいたします。","respondent":"中山資源循環推進課長","answer":"基本的にこれは株式会社ですから、企業の経営努力というものがまさに問われる部分ではありますけれども、基本的にはこの清掃工場の運転管理業務を受託していくという中で、一定年数後に黒字に転じていくということを見込んでおります。","id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"杉並区のほうから、清掃一部事務組合議会のほうでいろいろ質問が出ていたかと思いますけれども、今回、工場の経営のほう、また電気の販売のほう、発注のほうも清掃一部事務組合、また受け皿のほうも清掃一部事務組合ということで、競争原理が働かないのではないかという質疑が出されておりましたけれども、こういった点に関連しまして、委員会の中では工場のほうはきちんと随意契約ということで。","respondent":"中山資源循環推進課長","answer":"ただ現在、基本的に、例えば東京電力に売る売電料金よりも、メリットはある購入をしていくという方針から考えますと、東京電力との関係でいっても、一定の競争が生じるというわけですから、いずれにしましても、その時々の電力の売却単価みたいなものは全国的にも。","id":"exchange-039"},{"speaker":"三村委員","kind":"質問","question":"それが今回、新会社のほうに随意契約ということで固定化されてしまうと、逆にそういった競争が働かなくなるのではないかということで、東京電力との関係性ではなくて、ほかのＰＰＳのほうとの競争がきちんと確保されるのかということでお伺いをしているんですけれども、その点についていかがでしょうか。","respondent":"中山資源循環推進課長","answer":"確かにいわゆる電力小売事業者と考えると、東京電力だけではございませんから、１つの指標としての東京電力はありますけれども、ご指摘のとおり、現在でもＰＰＳ事業者が入札をしている部分がありますから、これの額との関係でも当然競争というものが生じてくると思います。","id":"exchange-040"},{"speaker":"三村委員","kind":"質問","question":"そうした中では、逆に先ほど安定しているということだったんですけれども、この電力小売事業者、一部破綻してしまっている企業やなんかもありますし、競争入札ということでありますけれども、現状、今、小売事業者のほうで入札したときには、もう１２円から１３円という、かなり高い価格で入札されているかと思います。その点についてはいかがお考えでしょうか。","respondent":"中山資源循環推進課長","answer":"それにあわせて、電気小売事業もさらに安定させるという説明にはなっておりますので、この安定と申しますのは、基本的な工場の運営受託を行うというベースがありながら、そこをさらに小売事業について、ある種の競争原理を働かせていき。","id":"exchange-041"},{"speaker":"三村委員","kind":"質問・要望","question":"今の質問とも多少関連してきますけれども、１２９ページのリサイクル推進費に関連いたしまして、廃プラスチックのリサイクルについてお伺いをしたいと思います。６月の一般質問のほうでも述べさせていただきましたけれども、国のほうで容器包装リサイクル法、サーマルリサイクルは認めておりませんということで、意見は出ているかと思います。品川区としてはどういった方向性で今後、考えているのか。","respondent":"岩崎環境清掃事業部長","answer":"どの方法をとるのかというのは、その４区の中でいろいろと検討しているようです。マテリアルリサイクルが一番望ましいと言われていますけれども、マテリアルというのは、ちょっとでも汚れていると、もう受け入れてもらえないわけです。","id":"exchange-042"},{"speaker":"三村委員","kind":"質問・要望","question":"そのことによって、周辺の子どもたちの喘息の被害も減ったというような報告もありますので、ただ単にデータ的に基準値をクリアしているからといって、本当に安全かというと、その辺はやはり後から出てくる部分というのも実際あるわけですから、そのことを考えると、安全性ということからすれば、ごみを出さない、増やさないということが一番問題になってくるかと思いますので。","respondent":"中山資源循環推進課長","answer":"昨日も、多分２０回目ぐらいになりますけれども、夜、説明会を行っておりますが、当然、ただ単に燃やすだけの説明をやっているわけではございませんで、リサイクルの徹底、区長会の方針も発生抑制をし、リサイクルを徹底して。","id":"exchange-043"},{"speaker":"大沢委員","kind":"質問","question":"私は１２６ページ、許可および監視指導のところ、それと１３４ページの中小企業事業資金融資あっせんについてお伺いします。先日、所管の委員会で請願が出たんですけれども、東品川でビジネスホテルができるという話を聞いております。その開きを狭めていくために、どのような行政指導を既にされたのか、そして今後どのようにしていくのか、教えてください。","respondent":"高橋保健センター衛生課長","answer":"ホテル運営にかかわるものについて説明会を開催してほしいという要望もございましたので、私どもも業者のほうに開催の申し入れを文書で申し入れているところです。","id":"exchange-044"},{"speaker":"大沢委員","kind":"意見","question":"指導要綱に基づいて行政の指導をされているというお話です。指導要綱なんですけれども、往々にして指導要綱に基づいて相手、双方の話し合いの場を設けるという場合に、その指導要綱があってないような、いわゆる指導要綱の中にある規定、指導要綱自体がプログラムのような規定になっているのではないかということを私は思っているんですけれども、その点、どういうふうにお考えになりますか。","respondent":"高橋保健センター衛生課長","answer":"システム的な指導要綱でございませんので、生活環境の悪化を防ぐということで、住民とのトラブルが生じている場合については十分話し合いをするようにということで、解決がつくまでやっていただきたいということで指導をしてまいっております。","id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"この件で、住民とのトラブルがおさまるまでということで、地域の方は非常にご心配をされております。周辺には教育環境施設がありますので、そこらのところを十分におわかりだとは思いますが、確認をするということで、きちっとした指導をして、話し合いの場を持っていただいて、きちんと合意形成をされるようにやっていただきたいと思います。あったらお示しください。","respondent":"高橋保健センター衛生課長","answer":"直接ではございませんが、電話でのお問い合わせがなければ、十分合意がされたと思います。","id":"exchange-046"},{"speaker":"大沢委員","kind":"質問","question":"私は前回の款で、やはり街なみをきれいにしていきたい。そこに急に異色のものが建つのはいかがなものかということも私、思いますので、そこのところは非常に合意形成の定義というのが出てきそうで、出ないのはわかっているんですけれども、あえて今、お伺いをさせていただいたわけであります。次なんですけれども、融資あっせん事業なんですが、小規模企業特別事業資金についてお伺いいたします。","respondent":"金子産業振興課長","answer":"お尋ねの小規模企業特別事業資金の融資の平均額ということですけれども、約４００万円になります。","id":"exchange-047"},{"speaker":"大沢委員","kind":"質問","question":"製造業、建設業、運輸業、その他の業種にあっては常時使用する従業員が２０人以下、卸売業、小売業およびサービス業にあっては５人以下の企業、まさに品川区の屋台骨、支えている商売の方たちがこの小規模企業ということなんですけれども、その方たちにとっては、やはり１００万円の差、自分が希望した額に添えない、やはり心情としては確かに返していかなければいけないという債務も発生しますけれども。","respondent":"金子産業振興課長","answer":"ちょっと細かいデータを持っていなくて恐縮ですけれども、ご本人様が５００万円の希望を持ってきたか、あるいは４００万円の希望を持ってきたか、その辺は定かでないところはありますが、私どもとしましては決算書等々、相談員が相談をさせていただいて。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問・要望","question":"それをちょっと伺いたくて、５００万円の方のパーセンテージをさっき質問させていただきました。これは事業運転資金ということですけれども、既に事業運転資金が限度額１,０００万円ということで設定をされておりますけれども、年末融資５００万円については、事業資金１,０００万円の中に入ってしまうのか、それとも別枠で借りることができるのか、どうなんでしょうか。","respondent":"金子産業振興課長","answer":"１つ確認しますと、年末のこの特別事業資金につきましては、設備と運転と併用可能というふうにしておりますが、この年末の資金につきましては、既存の融資とは別枠というふうに設定しておりますので、その辺についてはそのようにご理解いただければと思います。","id":"exchange-049"},{"speaker":"大沢委員","kind":"質問","question":"事業運転資金１,０００万円の別に年末事業資金ですから、５００万円ということで別枠でということで教えていただきましたので、そのように私も周りにお話をします。","respondent":"金子産業振興課長","answer":"現時点での小規模企業特別事業資金の融資ということですが、現時点というのは平成１８年度という意味かと思いますので、平成１８年度におきましては、９月末までで３９３件の融資の実行がされております。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問","question":"９月時点で３９３件ということで、そうすると傾向としてやはり年末に関して融資の申し込みが増えるというような傾向があるんでしょうか、教えてください。","respondent":"金子産業振興課長","answer":"委員ご指摘のとおり、１年間の中では年度の後半のほうが多いという傾向はあります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"１２５ページの精神保健費と、１２４ページ、１２５ページの保健事業費、区民健康診査についてお伺いします。２点目として、どのような対応がされているのかというところをお伺いしたいと思います。","respondent":"倉橋品川区保健所保健サービス課長","answer":"その後の医療への結びつきですけれども、専門医相談等を実施しております。保健相談以後、専門医のほうへの相談を紹介しています。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"私は周りの状況からして、増えているのかなと思って、傾向をちょっと今お伺いしたので、その点が１点と、私が言ったのは医療につながらなかったり、相談に引きこもっていて、外に出ていかれない、人と会うのが嫌だというような人をどう助けてくださるのかなという、その辺をちょっと具体的にお伺いしたんです。","respondent":"倉橋品川区保健所保健サービス課長","answer":"そのほか専門医相談で３４７件など、所内での対応をいたしておりますし、専門医への紹介ということで対応しているところが多いと認識しております。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よく病院に通っていらっしゃる方もお薬がなかなか合わないとか、ぴったり合った医者につながらないという悩みもよく聞いたりするんですけれども、保健所のところに相談をすると、今、ご答弁にあった専門医相談、ここのところがとても丁寧にやってくださるというので、この辺ちょっと概要なんかに載っていないので、この辺がどのように回数とか、どこで行われているのかというあたり。","respondent":"倉橋品川区保健所保健サービス課長","answer":"精神保健相談ですが、保健所、保健センター、それから大井保健相談所で、月に４回行っております。予約制でございまして、３所で実施しているという状況です。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういった面ではいろいろ相談に乗っていただいて、その後の対応がされている中で、どのくらい仕事に復帰ができたり、また自立とか、改善がされている方がどのくらいいらっしゃるのか、その辺、把握をされているかどうか、教えてください。","respondent":"倉橋品川区保健所保健サービス課長","answer":"精神保健障害者の社会復帰促進事業、いわゆるデイケアというものですけれども、平成１７年度は２,１２７件を実施しておりまして、復帰というのはなかなか難しい部分でございまして、作業所等に。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保健師のお仕事の今の状況、大変困難状況を抱えた方の相談を幾つも抱えていらして、保健師自体も体調を崩していらっしゃる方がいると、ちらっと伺ったりもしたんですが、１人の受け持ち人数がどのくらいいらっしゃるのかと、あと病欠とか、メンタルヘルスで入院されていらっしゃる方がいらしたら、ちょっとその辺の状況もお聞かせいただきたいと思います。","respondent":"倉橋品川区保健所保健サービス課長","answer":"したがいまして、１件当たりにかかる手間といいますか、時間といいますか、非常な労力がかかるという状況になってきておりますので、保健師にかかる労力の負担といいますか、そこの部分につきましては、常に気をつけて。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"精神保健にかかわる保健師のところはちょっと人数が出ないかもしれませんけれども、１万人に１人ということは品川区で三十三、四名保健師がいらっしゃるということなんでしょうか、その点が１点と、あとハードなお仕事で家庭訪問などもしてくださっている状況の中で、私は本当にいい仕事をしていただくために、保健師にいい状態であってほしいなと思いますし、必要なところにしっかりと時間がかけられる。","respondent":"倉橋品川区保健所保健サービス課長","answer":"保健師の人数ですが、児童保健事業部、保健所・保健センター、相談所を含めまして、３２名となっております。福祉高齢事業部に３名ありますので、３５名ということになっております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次、区民健診のほうに移らせていただきますが、女性の健康診査というのがここに書かれていますけれども、これはたしか年齢が１６歳から４０歳というところでは、率直な疑問として、なぜ男性の健康診査の年齢のところが抜けているのかなと思いますので、そこを教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"女性健診ですけれども、女性健診を始めた経緯と申しますのは、女性の栄養管理、いわゆる貧血対策ということで健診を始めた経緯がございまして、女性特有の疾病に対する対策です。したがいまして、男性はその年齢には健診は入ってございません。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問","question":"今の実態を見た場合に、１６歳から４０歳手前の男性の健診がないということは、本当にこのところメタボリックシンドロームでしたか、あれの問題もあるし、生活習慣病をいかに早く発見して手を打つか、小学生のうちからも心配されているという状況の中で、早く発見をして本人が自覚をして、きちんとした生活をするというところがとても大事であると思うんですが。","respondent":"谷田部健康課長","answer":"これは生活習慣病予防という観点から、中年から老齢期に向かって生活習慣を改善して、健康な体を維持していこうという目的でございまして、先ほど女性健診、１６歳から３９歳と申し上げましたのは、妊娠・出産の関係で。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本の区民健診の充実はもちろん、それはお願いをしていきますが、私が今質問したのは、４０歳手前の男性の健康状態が把握されているのかどうかということをお伺いしたので、これは後で答えていただきたいんですが、やはり病気というのは少しでも早く発見して、早く手立てをしたら医療費の抑制になるんですね。さっきの点は状況については後で答えてください。","respondent":"谷田部健康課長","answer":"平成１６年度までは結核予防法に基づく結核検診という形で、区民健診とあわせてやっておりました。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面でお金を出さないとチェックができないというのは、本当に今の状況の中では、医療を受けられる人、受けられない人という所得のところで振り分けられてしまうという状況が生まれてくると思うんです。法的根拠はなくなったと、さっきおっしゃいましたけれども、この辺の必要性についてはいかが受けとめられていらっしゃるでしょうか。","respondent":"青山品川区保健所長","answer":"それから肺がんにつきましては、これは精度の高いものを皆様方に提供していきたい。肺がん検診をそのような形で進めたいということで、それでヘリカルＣＴ等を充実させていくという方向で考えております。","id":"exchange-061"},{"speaker":"若林委員","kind":"提案","question":"事務事業概要では平成１８年度グリーンバンク制度を行っているというふうに掲載されておりましたけれども、現状、存続しておられるのかどうかだけ確認をさせてください。それから３点目に、今回の定例会で藤田議員からもご質問がありましたけれども、国道、都道において、可能な限り街路樹の植栽を道路管理者のほうに働きかけてほしいというご提案をさせていただきました。","respondent":"中山資源循環推進課長、藤田道路公園課長","answer":"そのほかに例えば清掃事務所のほうでも、カラスにつつかれたという被害があった場合に、そういう現場の対応の中で使っていただければどうかということで、ある種その被害のある方への検証を重点的にやろうということで行ったです。３点ご質問があります。","id":"exchange-062"},{"speaker":"若林委員","kind":"確認","question":"ごみ袋のほうですが、なぜつつかれるのかという理由をちょっと教えてもらいたいです。それから緑のほうは、そうしますとグリーンバンクは申し込めば利用できると理解してよろしいんですねという確認をもう一回します。それから緑被率については、そうしますと細かくてすみません、壁面緑化については、緑被率に入ってこないという理解をしていいのかどうかという、この３点をもう一度お願いいたします。","respondent":"中山資源循環推進課長、藤田道路公園課長","answer":"黄色の袋の効果というのが、大学教授の研究によりますと、カラスの目には過剰に黄色が反応するために、中が見えにくいということが効果の理由だと言われているんですけれども、それでも全くゼロではないということで。グリーンバンクのほうですけれども、現在、お預かりをして、木をストックしてあるというわけではございませんので、申し込みというのが、例えば家庭にある樹木を引き取ってほしいということであれば、そうした樹木については。","id":"exchange-063"},{"speaker":"若林委員","kind":"質問・要望","question":"清掃費のほうは、要するに時間のルールを守っていないところがつつかれているように散見されますので、そこら辺、ご近所の声がけとか、また区からの徹底とかをお願いしたいと要望します。この街路樹の種類の選び方、選定については、今後クールアイランド等、また木陰を増やす等の視点が重要になってくるかなと思うんですが、今後の街路樹の種類についてのご意見を伺います。","respondent":"松代管理工事課長","answer":"街路樹の件です。街路樹は今現在、区内に４,８００本ほどあります。種類としましては、１５種類ほど、大きな種類の中です。大きいものではイチョウ、スズカケの木、トウカエデといったものがあります。","id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"当然、これは入札によって土木業者等が木を切るわけですけれども、どうも美しくない形が残ってしまう部分も見受けられるという地域の方の声もありましたので、そこら辺、ちょっとご意見を伺います。","respondent":"藤田道路公園課長","answer":"ただ、街路樹等になりますと、十分な歩道幅員がない、そういった環境の中で植わっている樹木については、なかなか周囲のことを考えますと、十分な本来の木の形を目指した剪定というのは難しいかなと思ってあります。","id":"exchange-065"},{"speaker":"築舘委員","kind":"質問","question":"成果報告書の１２９ページの屋上緑化等助成のところで質問します。８件ということでございまして、民間の屋上緑化を助成をしていくということで、工事費の一部を補助したりするということですが、その現状はどうなっているか、お聞かせください。","respondent":"藤田道路公園課長","answer":"屋上緑化の関係ですけれども、私どもは平成１４年から屋上緑化の助成等の事業を開始しています。平成１４年には９件、平成１５年には１３件といったような形で１０件前後で推移しています。","id":"exchange-066"},{"speaker":"築舘委員","kind":"質問・要望","question":"それで、先ほどちょっと屋上をのぞいてきたんですけれども、今度壁面緑化コーナーというんですか、これが大分プラスされて、ただ壁面の緑化がまだ育っていないといいますか、うまくいっていないような感じがしたんですけど、これは時期が時期なのか、パネル型、カセット型、いろいろ階段式とかという説明は出ているんですが、その辺のことがうまくいっているのかということ。果物とか。","respondent":"中島経理課長","answer":"それでさまざまな工夫をしまして、いろいろなエリアに沿って、それぞれの特徴をあらわしながら工事を進めて、現在、結構区民の方にも親しまれて、ただ、今、こちらの管理につきましては屋上緑化の推進委員という職員ボランティアがおりまして。","id":"exchange-067"},{"speaker":"築舘委員","kind":"質問・要望","question":"屋上へ行って、庭園のほうへ入るところの右側のヒーリングガーデンというところは、今、ススキが大変きれいで、そして花々もなかなかよくできているんですけれども、さっき言ったようにキッチンガーデンのほうが少し整っていないというか、手入れができていないようなところがあったので、これは職員の皆さん方が本当にボランティアでやっていただいているので。","respondent":"中島経理課長","answer":"今委員の指摘された部分、ちょっと荒れているかなという印象を持たれたのは、収穫した後は、若干色も寂しくなりますので、そういった印象を持ったのかなと思いますけれども、いずれにしましても、今後引き続き、手入れについてはきちっとした形にしていきたいと考えています。","id":"exchange-068"},{"speaker":"築舘委員","kind":"意見","question":"職員の方も屋上に出て、昼とか、深呼吸をすると、また仕事も一段とすばらしいものになってくるということだと思いますので、ひとつ民間の屋上緑化のほうのＰＲも、この庁舎の屋上を見習って、頑張ってもらいたいというような心づもりでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"山村委員","kind":"質問・要望","question":"私からは１２４ページ、予防費から質問します。はしか、風疹、ＭＲ混合ワクチンのほうでただいま予防接種のほうが２回、４月から混合ワクチンになったということなんですが、そのＭＲ混合ワクチンの２回接種という形に切り替えになった理由をもしご存じなら教えていただきたい。","respondent":"倉橋品川区保健所保健サービス課長","answer":"旧来は１歳から２歳ぐらいの間に１回接種という接種方式で実施しておりましたが、なかなか接種率が上がらないという問題がございまして、諸外国並みに２回接種への改正が望まれていたわけです。","id":"exchange-070"},{"speaker":"山村委員","kind":"質問","question":"２回接種に変わったですが、この切り替えのはざまで、接種漏れの増加が懸念されていたと思います。それに関して、品川区ではどのように対応なさったのかというのと、現状、どの程度抗原を持っていない１歳児なり何なり、いわゆる切り替え時に受けられなかった子たちの割合がわかるんでしたら、教えていただければと思います。","respondent":"倉橋品川区保健所保健サービス課長","answer":"そこで経過措置といたしまして、その接種できない児を対象といたしまして、任意の予防接種につきまして、区独自の接種制度を実施しています。","id":"exchange-071"},{"speaker":"山村委員","kind":"質問・要望","question":"区独自の接種制度というのは、単抗原ワクチンに対しては補助を出しているのかということと、それとどの程度抗体を持っていない児童がその切り替えの時期にできてしまったのかということをお知らせいただきたい。","respondent":"谷田部健康課長","answer":"私ども、この制度のはざまになるお子さんを救済するために、何とか抗体をつくるための任意の接種を引き続きやっているという状況があります。それで先ほど、未接種率はどうかというご質問ですが、大体１割ぐらいの未接種のお子さんがいらっしゃるです。","id":"exchange-072"},{"speaker":"山村委員","kind":"質問","question":"単純に忘れている方っているんじゃないかと思いますので、どうかよろしくお願いします。それと日本脳炎の予防接種が今現在、中止されていると思うんですが、この日本脳炎の予防接種はなぜ中止されてしまったかということと、今後もこれは永遠に中止されたままなのか、それとも再開するようなうわさを耳にしたことがあるんですが、そこら辺を心配なので教えていただけるとうれしいです。","respondent":"倉橋品川区保健所保健サービス課長","answer":"この背景には、その副反応が軽減されるであろうと期待されます新型ワクチンが１年ぐらいのうちに開発される予定であったということがございまして、本来ならば今ごろは新型ワクチンというものが認可されているはずでございましたが、開発過程でおくれがございまして。","id":"exchange-073"},{"speaker":"山村委員","kind":"質問","question":"ですから、再開時に何かしらそういうふうに、ただ単に始めるというよりは、まず未接種のお子様たちに関してＰＲ等々、考えがあるのかどうか、そこら辺をもしありましたら、教えてください。","respondent":"倉橋品川区保健所保健サービス課長","answer":"再開時の未接種の方々に対しましては、国の考え方といたしましては、接種制度自体を廃止したのではなく、積極的勧奨を差し控えているだけであるので、特別に今のところは対策を考えていないというような意見であるという、説明会等でそういう国の意見が表明されておりますが。","id":"exchange-074"},{"speaker":"山村委員","kind":"質問","question":"全額補助ですとか、そういう形になると、いろいろとインフルエンザの小児に関する補助がなくなった背景というものがもともとあるでしょうから、そこは難しいとは思うんですが、任意で親が子どもに受けさせる場合に、ある程度の補助をして、できるだけインフルエンザのワクチンを打たせることが、インフルエンザ脳症等の予防にも確実に役に立つと、私は思っておりますので、何かしらそこら辺で。","respondent":"倉橋品川区保健所保健サービス課長","answer":"このような専門家等の結論、報告書などの結論を参考にいたしまして、今後対策などを検討していきたいと考えているところです。","id":"exchange-075"},{"speaker":"山村委員","kind":"質問・要望","question":"これからは確かに国および都の対策がというふうに、小児に対する補助に関してあればというようなことをおっしゃっていたと思うんですけれども、たしか小児に対するインフルエンザの補助自体に関しては、区でもやれるんじゃなかったかと、私は理解しているんですが、どうしてもやっぱり都だとか区とかの許可がないとできないことではないはずだと思うので、そこをもう少し教えていただきたい。","respondent":"青山品川区保健所長","answer":"インフルエンザも、どうも今の高病原性鳥インフルエンザの感染状況を見ましても、むしろ乳幼児や若年者に多いというようなことを考えますと、やはりインフルエンザの予防接種がさまざまな形で効果を持っている可能性もありますので、この点につきましては費用の点もありますし。","id":"exchange-076"},{"speaker":"山村委員","kind":"質問・要望","question":"意外とまだ大まかなことぐらいしかつくっていないんじゃないかという感想がありますので、より細部の部分までつくっていただければという要望と、それと鳥インフルエンザがいつ来るかわからないものですから、夏に来る可能性もありますし、このインフルエンザが最近は冬ばかりじゃないということで、夏に来るということもあるんですけれども、区を挙げて、机上でシミュレーションというか、訓練等。","respondent":"倉橋品川区保健所保健サービス課長、青山品川区保健所長","answer":"区といたしましても、東京都などとの連携訓練も含めまして、どのような訓練を行うべきかというようなことを積極的に検討してまいりたいと考えているところです。品川区におきましては、発生前期、海外発生期、国内発生期、都内流行期前期、後期、それから大規模流行期、それからパンデミック、流行が終わった後の各期に分けまして、かつそれぞれのときの区の方針、それからサーベイランス。","id":"exchange-077"},{"speaker":"伊藤委員","kind":"質問","question":"私は１２６ページの母子保健指導費の中の健やか親子学習に関連をして、それから１３５ページ、近隣セキュリティシステムに関連して質問いたします。先に親子学習のほうですが、簡単にここで行われている事業内容と、それからその対象者、それからここで展開しているカリキュラムの内容を教えてください。お願いします。","respondent":"川口品川区保健センター保健サービス課長","answer":"その次に、これは最近、食育との関連で昨年度から実施していますけれども、クッキング、いろいろな世代に関しての食育指導、これも行ってあります。それからあわせて育児期の子育て安心事業というふうな組み立てで行っているところです。","id":"exchange-078"},{"speaker":"伊藤委員","kind":"質問","question":"で、今お話がありましたこの母親学級、両親学級等々、これはそれぞれすばらしいんですけれども、残念なことかもしれませんけれども、今までごく当たり前のように親としてのあり方とか、それから子どもに対する接し方とか、当たり前になっていたものが残念ながら崩れてきてしまっている現状があるということで、行政としては各家庭の中に入り込むことは非常に困難であるとわかってはいるんですが、しかし。","respondent":"川口品川区保健センター保健サービス課長","answer":"あわせてその後は出産後、これも委員既にご案内のとおりだと思いますけれども、いろんなところで家庭訪問をさせていただいたり、それからいろんな相談をいただいて、その場ではもちろん我々は保健所・保健センターですけれども、健康に関することだけではなくて。","id":"exchange-079"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そこのところをしっかりと品川区のこういう講座があるわけでありますし、それからこれから生まれてくる子どもたち、生まれたばかりの子どもたちに対して、本来行政がやるべきことじゃないとわかってはいるんですけれども、でも、やらざるを得ない背景も出てきた中で線引きが難しいんですが、もう一つ確認していただきたいのが。","respondent":"川口品川区保健センター保健サービス課長","answer":"そういう意味では、職員が教育指導を行うというだけではなくて、自主グループを育成して保健所・保健センター、特に自主グループをいろいろ育成して、その世代世代のお母様方との親教育に関連したような意識を植えつけているところですので。","id":"exchange-080"},{"speaker":"伊藤委員","kind":"確認","question":"大変すばらしいことです。それで確認ですが、ここでも何人か協力員がいるんですけれども、例えばその協力員の方々にここで駆けつけ、どうせい、ああせいという指示が一切ないんです。協力員になったんだけれども、例えばそういう事案があったときに、そこに行ってどうしたらいいですか。要するに万が一のことがあったらという補償体制はどうなっていますでしょうかということをお聞かせください。","respondent":"金子生活安全担当課長、金子産業振興課長","answer":"その考え方については今後とも変わらないと考えております。ただ、研修会並びに今後発行を予定しております協力者通信においても、そういった点についてはっきりうたっていきたいと考えております。この帽子を配付する際に一応、「協力者の手引き」というマニュアルをお配りしておりますので、それをごらんいただきたいというのが１点です。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"意見","question":"それだけです。具体的にその後どうしていくかとか、それから何もないわけでありますので、ぜひこれは例えば研修会と言わないまでも、具体的にＰＲする仕組み、１万２,０００名の方々に対して、その対処をぜひ検討してくださいということをお願いしておきますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"中島委員","kind":"質問・要望","question":"私は１２３ページ保健衛生総務費、１２６ページの保健指導費、１３３ページの消費者対策費、以上３項目についてお伺いたします。それから保健指導費のほうでは、健康教育事業というのが１億６６０万ですか、健康教育事業というのがあるんですが、これの内容、それとその教育に当たってどのような方が担当されて、どのぐらい今、実施されているのか、そのことをお伺いしたいと思います。よろしくお願いします。","respondent":"谷田部健康課長、川口品川区保健センター保健サービス課長、鷹倉区民課長、青山品川区保健所長","answer":"それから３点目の２４時間対応と申しますと、多分コンビニエンスストアかどこか、そういうようなものだと思いますが。１７年度に限ってお話し申し上げますと、この年度は特にどういうことを前年度と比較して行ったかということについてお話し申し上げますと、今年度。５月３０日が啓発の日ということで、街頭でいろいろなものを配っていく、こういうこともやってありますし。","id":"exchange-083"},{"speaker":"中島委員","kind":"質問・要望","question":"それからインフルエンザの予防接種ですが、小児の場合、年に２回ということで確かに費用はかかると思うんですが、ほんとうに多くの若いお母さんたち、高い予防接種で苦労されているわけですので、ずっと子どものままいるわけではなくて、順繰り順繰りに人は育っていくわけですから、やはりその予防という点で、この辺の医療費、子ども医療費でお金を払う費用とどっちがいいのかという。","respondent":"谷田部健康課長、鷹倉区民課長","answer":"このように普及してきてありますので、私どもどういう場面でそういうことがお願いできるかどうか、今後検討してまいりたいと考えています。私ども消費者センターでビデオのライブラリーだとか関係図書を情報提供しているとともに、ＣＡＴＶで消費生活相談員が出前講座に行くというようなこともきめ細かくお知らせしています。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本共産党の安藤泰作です。よろしくお願いします。成果報告書の１３５ページのキャリア支援塾についてご質問いたします。そういった立場から私なりに質問させていただきたいと思います。はキャリア支援塾１４６万円というのは、これはどのように使われたのか、できれば簡潔にお願いしたいんです。","respondent":"金子産業振興課長","answer":"キャリア支援塾のお尋ねですけれども、これは昨年度、２回にわたりまして人材確保で悩む区内の中小企業と、働く意思を有しながら、なかなか就業機会に恵まれない若者とをマッチングさせようという目的で２回行った事業の経費です。","id":"exchange-085"},{"speaker":"安藤委員","kind":"意見","question":"２回何を行ったのかというのがちょっと気になるんですが、それとあとキャリア支援塾とあと６月からスタートいたしました国の事業ですけれども、ヤングキャリアナビとの連携ですとかと関係はどのようになっているのかお聞かせください。","respondent":"金子産業振興課長","answer":"一つは適性診断であるとか、あるいは実際にフリーターから就職された方の体験談、それから模擬面接、区内にあります技術専門校や都立高専のご紹介、それからハローワークの協力を得て合同面接会、さらにパソコン、簿記の技術習得等々。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"そのヤングキャリアナビですけれども、中小企業センターで会場をお貸ししてやっているということですが、区が手を挙げた動機として、今年度の６月の区民委員会の中でこういった動機として雇用について労働法制の変更で、区市町村の役割が少しずつ拡大してきていますので、情報収集の一環を主眼にということで動機づけがあって申し込んだといいますか。","respondent":"金子産業振興課長","answer":"区としましてはそういった全体的な状況を見ながら、区としてできることが何かを探りながら、そういった各種機関の情報を集めて検討してまいりたいと今考えているところです。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"１０年後もパート、アルバイトとして働くことを希望している人は０％となっているというふうな調査もあるんです。私がお伺いしたいのは、このような若者の雇用状況をこれまでも共産党の区議が質問していたんですけれども、改めまして雇用の状況をどう区が認識しているのかということをお伺いしたいと思います。ですから、改めて若者の雇用の状況の今後の見通しについての見解をお伺いしたいんですが。","respondent":"金子産業振興課長","answer":"ただ、今までこの長い不況期で採用が制限されていたそのいわゆるフリーターの方たちを中心に、残っている方たち、この方たちをどう処遇を考えていくのかというのが、これから国を挙げて考えていく問題だろうと考えていますので。","id":"exchange-088"},{"speaker":"石田委員","kind":"質問・要望","question":"１２９ページ、緑化推進費をやります。１２６ページの教えていただきたいんですが、公衆便所適正配置計画検討というのがあります。どういう内容であったのか、いろいろどういう計画を立てたのかも教えていただきたいと考えています。ほかのところにも多分、緑化にかかわることはたくさん載っているんだけど、ここにくくられているというのはどういう意味なのか教えていただきたい。","respondent":"松代管理工事課長、日下部企画財政課長","answer":"そういった公園の今後の整備方針、また維持管理面はどういうふうにしていくのか、いろいろと実際に利用していただける区民の方の利便性をさらに高めるために、いろんな角度から現状の把握をしまして今後の整備等に生かしていきたいと。そういうことを反映いたしまして、緑化について環境費の中に組み込んでいると、そういう考え方です。","id":"exchange-089"},{"speaker":"石田委員","kind":"質問・要望","question":"これについては基本的には緑というものに関して、先ほど来、道路公園課長と管理工事課長が答弁をされているけれども、そこで集約をしているのかというふうに理解をしていいのかどうかをお聞きしたい、この部分については。委託費が去年にあったわけですよね。それでこれで計上されているということは、方針があったというので、その方針の内容についてもう少しちょっと細かく教えていただきたい。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"ただ、学校のほうは学校のほうでそれぞれやっていただいているという形になってあります。特にやはり女性の利用が非常に少ないというところで、今、女性の方にも安心して使っていただけるようなトイレ、だれでもトレイみたいなことでいろいろと工夫をしていますけれども、そういったことについて何とか生かして。","id":"exchange-090"},{"speaker":"石田委員","kind":"質問","question":"緑のほうからいきます。緑のほうは、例えばハードの部分があると思います。ここはこういう考え方で、緑全体をどれぐらいまで持っていきましょう、そういうことの考え方は、変な話、道路公園課でいいのか、これは企画財政課なのか、緑についてだけだけれども、どういう形で今お考えなのか、それをお聞きしたい。こういうのも全部ここに組み込んでいろいろ計画で今検討されているのかどうか、そこら辺もう一度。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"そういった緑全般の考え方ですけれども、基本的には私ども道路公園課が中心になり、横の連携を十分にとりながら進めていきたいというふうに考えてあります。今現在あるトイレをどう使っていただくかということも含めましていろいろ検討しているんですが、増やすだけではなく、適正な配置の中には場合によっては減らすことも考えてあります。","id":"exchange-091"},{"speaker":"石田委員","kind":"提案","question":"そっちはこれでやめます。要望だけしておきますが、ぜひ全体を見渡していただいて、災害時、ピットももちろん重要なことでしょうし、今言ったようにいつでもそういう形の対応ができるように検討していただきたいと。そういうところも区として考えていただきたいと思っているわけですが、今のその考えていただくのと、話があればじゃなくて、話がもうこうしたらという提案型でやれるかどうか、ちょっと。","respondent":"藤田道路公園課長","answer":"ただ、新たな施策の展開につきましては、現在、新水と緑のネットワーク構想ということでさまざまな施策について検討していますので、そういった中で少しでも効果的に発揮できるような形で進めていきたいというふうに考えてあります。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"１２４ページの乳がん検診、１３０ページの清掃総務費、１３５ページの近隣セキュリティシステムについてお聞きいたします。４０歳から検診ということでお知らせが来て始まっているわけですけれども、非常に話題性があります。集まりますと、やはり受けたというのが会話の中にあるんです。それで、その上でこのマンモグラフィの検査というのはどういう検査なのか、そういうことをお聞きしたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"マンモグラフィといいますとエックス線の検査ですが、乳房を板で挟むような形でちょっと広げる操作をしまして、それを軟エックス線といいまして、普通の胸部のエックス線写真とちょっと線質の違った形で、軟部組織のよく映るエックス線で撮影し。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"それで、あと触診というのもしておられると思うんですが、器具を使ってという形もあるでしょうが、あとはいろいろ調べ方があると思うんで、その点はいかがでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"伝統的にはこの触診というものが一般的でございましたけれども、現在では世界的にも、そして日本のがんの標準的な検診方法の報告書を国がつくりましたけれども、その報告書の中でもマンモグラフィによる検診が乳がんの発見に現在のところ一番適した方法であるということで。","id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"私も行かなきゃいけないと思ってはいるんですけれども、非常に痛いという話があります。それと触診があるんですよね。保健所に行って、どういう検査か触診があって、そういう器具を使ってという形はある程度わかるんだけれども、実際行ってみたときにびっくりされたんです。こんなに痛いものかと。それと男性の技師が３人ぐらい並んでいて、その触診の場合は素手で触るらしいのです。いかがでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"これはもともとのレントゲン技師というのはほとんどが男性ですので、レントゲン技師の女性の方はもう優先して対応していただいている結果であるというふうに解釈しております。","id":"exchange-095"},{"speaker":"西本委員","kind":"意見","question":"できればマニュアル等々を渡すなり、待っている間にこれを読んでおいてくださいと。それから、部屋の中には３人の技師がおりますと。１人はこういう役目で、この人はこういう役目でということできちっと説明をすることで安心感があるんではないかと思いますが、その改善はどのようにお考えになりましょうか。","respondent":"谷田部健康課長","answer":"乳がん検診、両医師会のほうに委託して実施しておりますので、私どもが所管しておりますので私どもほうからお答えしますと、いろいろ問題等があるようなお話も伺いました。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"ぜひお願いしたいと思います。次に清掃総務費の中でご質問しますが、各戸収集というのが始まっていると思います。これにしましてから、メリット、それからデメリットはどういうところをどういうふうに思われているのか。それから清掃の職員の方たちの負担はどういう形になって、改善、工夫はいろいろされているのかどうかというところをお聞きしたいと思います。","respondent":"中山資源循環推進課長","answer":"ごみの各戸収集ですけれども、昨年７月から全域で実施をしておる建物ごとの収集です。基本的なねらいは、ごみ出しを自分の建物の前に出すということで、意識を高めていただく。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"各戸収集では従来、１億何千万ですか、増えているということではありますが、メリットのほうもかなりあるということですが、おそらく個人宅のところであれば、ごみの出し方によってカラスの被害があったり、それから自分の家の前に置きますので、それなりに分別も頑張ろうとかいう形になるかと思うんですが、単身住宅の場合、集合住宅の場合には、指導はどうされているのか。","respondent":"島袋品川区清掃事務所長","answer":"実際に収集しているのは清掃事務所なので、こちらのほうでお答えいたします。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"もちろん個人個人の検査をお願いしたいところではありますが、やはりその集合住宅の責任者というのはあろうかと思いますので、そちらのほうの注意も促していただきたいと思います。あれをちょっと清掃車に張るというか、そういうことで区内のほうをずっと回っているわけですから、それで子どもたちの安全普及活動という形にはつながることができないのか、その辺の工夫はいかがでしょうか。","respondent":"島袋品川区清掃事務所長","answer":"実は清掃車のところには先ほどちょっとありましたけれども抜き取り防止パトロールとか、そこで見つけてきてやるとか、あとは犯罪者をなくすとかそういうのもあります。今、委員の提案のございましたところですけれども、その辺はちょっと今後の検討とします。","id":"exchange-099"},{"speaker":"西本委員","kind":"確認","question":"ぜひとも８３運動をやはり増やしていきたいという思いがありますので、ロゴをなるべく活用していただいて、すごくかわいいですから、もっと身近に収集車のほうも感じられるんではないかと思いますので、検討のほうでよろしくお願いします。その確認をまずさせてください。","respondent":"金子生活安全担当課長","answer":"まさにそのとおりです。居場所を確認していただいて、必要あれば警察等への関係機関への連絡を最優先していただきたいと、こういう内容です。","id":"exchange-100"},{"speaker":"西本委員","kind":"確認","question":"先ほどの答弁ですとすぐ警察に行くのが役目なのかと勘違いされそうでしたので、ちょっとお伺いさせていただきました。次に、ＰＨＳからＧＰＳのほうにかわりました。その中で、ハード的な問題というのはもう完全に解決をされていて正常に動いているのかどうか。それから精度という意味でＰＨＳよりも大分よくなっているという実績があるのかどうかの確認をさせてください。","respondent":"金子産業振興課長","answer":"今の委員のご質問ですけれども、今年の７月にＰＨＳからいわゆる携帯のＧＰＳ付きのものに変更して、それに伴ってシステムも改修しているです。","id":"exchange-101"},{"speaker":"西本委員","kind":"確認","question":"一つ、精度は上がったのか変わらないのかということと、それから続けて次の質問で、ＹＯＺＡＮに改修を頼んでいるんですけれども、その企業との関係は今後、どういうふうになっていくのかということを確認します。","respondent":"金子産業振興課長","answer":"システムを変更しまして、いわゆるＧＰＳの機能している部分については、かなり精度は上がっております。私どもの実験した中でもそれほど遠く、例えば１００ｍ、２００ｍというふうな範囲で……。","id":"exchange-102"},{"speaker":"本多委員","kind":"質問・要望","question":"１３０ページの清掃費、全般的にこの辺を中心に質問します。その辺をお聞かせください。それと粗大ごみですけれども、リサイクルショップの運営費で２カ所のリサイクルショップ「リボン」で運用状況、最近この１７年度のあたりでどういう状況になっているのか教えていただきたいのと、それと同じく粗大ごみの廃棄物対策で、粗大ごみ受付センターの業務内容がどのような傾向になっているのか。","respondent":"中山資源循環推進課長","answer":"それから廃プラスチックの分別変更、サーマルリサイクルに向けての説明ですけれども、基本的にはごみを減らすとともに、リサイクル、プラスチックについても徹底し、それでも出てくる廃プラスチックについて、２３区全体として埋め立てるのはやめようということでございまして。","id":"exchange-103"},{"speaker":"本多委員","kind":"質問・要望","question":"ご丁寧にありがとうあります。ごみ処理量は減るのに、その決算額は毎年上がっているんですよね。その辺は清掃一組のことですから今は取り上げられないですけれども、最終処分場を考えたときの最終処分量を低下させていくという、その発信はやはりどこかでやらなきゃいけないと思うんですけれども、そのことについてちょっと教えていただきたいと思います。","respondent":"中山資源循環推進課長","answer":"１８年度以降ですけれども、２３区で協議の上、ごみ量に合わせてベースにして変えるということで、これは予算ベースではありますけれども、品川区の分担金については数千万円の削減の傾向がありますけれども。","id":"exchange-104"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは１３５ページの産業経済費、キャリア支援塾にかかわって青年雇用対策について伺いたいと思います。そこでちょっとご説明いただきたいのが、最近発行された労働経済白書平成１８年度版、この中で若者の雇用環境をどのように説明しているのか教えていただきたいと思います。それと一方、企業の従業員の給与はどういう変化をしているのか、２つに分けてご説明いただきたい。","respondent":"金子産業振興課長","answer":"すべて答弁したつもりでありましたが、役員報酬あるいは企業の報酬についてはデータを持ち合わせておりませんのでご説明できません。","id":"exchange-105"},{"speaker":"中塚委員","kind":"質問・要望","question":"労働経済白書、９月末に発行されたものですけれども、ぜひ所管の課長ですから、その辺の情報はお読みいただきたいと思います。冒頭です。サラリーマンの報酬は、つまり従業員の報酬は８年連続右肩下がり、これは新聞報道でもされているとおりだと思います。ぜひそこを踏まえていただきたいと思います。品川の雇用実態をぜひつかんでいただきたいと思いますけれども、いかがでしょうか。","respondent":"金子産業振興課長","answer":"ですので、私の認識としてもこういったものをベースにご説明申し上げたわけで、勉強は足りないかもしれませんけれども、一定の勉強はしていると自負しています。","id":"exchange-106"},{"speaker":"中塚委員","kind":"質問・要望","question":"その日の新聞のニュースでも、民間給与８年連続ダウン、これは９月２９日の朝日新聞ですけれども、ぜひあとでごらんになっていただきたいと思います。私はこういったワーキングプアの広がりの中で、貧困から抜け出せるように品川区もこの点、どう考えているのか伺いたいんです。ワーキングプアの存在をどう考えているんでしょうか。改善すべきだと思っているんでしょうか、お答えください。","respondent":"日下部企画財政課長","answer":"一方におきまして、私ども品川区におきましては先ほど来、ご質問にもございましたキャリア支援塾と、身近な自治体ならではの取り組みということで、それぞれの役割と責任、その分担に基づきまして、今、大きな課題として出ております問題について対応してきていると。","id":"exchange-107"},{"speaker":"中塚委員","kind":"質問","question":"ワーキングプアの存在について、品川区はどう思っているかという答弁はありませんでした。仕事をしていても、生活保護基準以下の給与しかないワーキングプアのこの現状、私はやはり異常だと思うんです。品川区はこれをやはり異常だと思っているのか。改善すべきことだと思っているのか、そこを教えてください。","respondent":"日下部企画財政課長","answer":"その辺のそういう取り組みが一番肝要だと、このように考えております。","id":"exchange-108"},{"speaker":"中塚委員","kind":"質問","question":"１回、行財政特別委員会でも紹介しましたけれども、今年５月末の求人報告で品川区内の図書館のカウンタースタッフの募集、時給は８３０円、１カ月の収入は、ここに書いてある募集要項をフルに使っても９万１,３００円。時給がマックス９００円に上がっても、１カ月９万９,０００円。やはりこういうことが前提になって行われている職場というのは、私はやはり問題だと思うんですけれどもいかがでしょうか。","respondent":"日下部企画財政課長","answer":"ですから、私どもそういう意味では不断の努力ということで行財政の改革を進めることによりまして最小の経費で最大の効果を上げると、このような取り組みを進めているとこれがまず基本です。","id":"exchange-109"},{"speaker":"中塚委員","kind":"確認","question":"今、中高年とありましたけれども、この募集は２２歳からですね。品川区は結局、行財政改革という名でワーキングプアでも構わないと、そういう姿勢でよろしかったでしょうか、確認させてください。この問題は大きな問題ですから、国会でも話題になったんです。この答弁からしても、今の品川区の姿勢は問題ありではないかと思うんですけれども、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"つまり、今新しい政権のもとでというお話がありましたけれども、これはやはり社会全体として今抱えている問題について、先ほども申し上げましたようにそれぞれの役割なり何なりにおいてどう対応するかという問題と、区政運営ということに例えば絞りまして。","id":"exchange-110"},{"speaker":"中塚委員","kind":"質問・要望","question":"これだけワーキングプアの問題が社会問題化していてそれを否定しない、むしろワーキングプアの働き方を是認するこの姿勢は私は異常だと思います。ぜひ若者の実態を踏まえ、雇用改善に向けて心を寄せて事業を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"堺委員","kind":"質問・要望","question":"最初にがん対策についてですが、成果報告書の１２４ページ、あるいは１２５ページにそれぞれ今回、区が取り組んだがん対策について数を挙げて費用についても計上されておりますが、まず確認をしたいのは、区としてのがん対策についての取り組みの基本的なものの考え方といいましょうか、その辺についてひとつ教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"区の独自の考え方といたしまして、今年度からは前立腺がんを新たに取り入れ、また乳がん検診につきましても４０歳以上を年齢を引き下げまして３４歳から偶数年で実施できるように拡大をしているという状況です。","id":"exchange-112"},{"speaker":"堺委員","kind":"意見","question":"先ほども乳がん検診についての質疑がなされ、また今も課長のほうから乳がんについて４０歳が３４歳に年齢を引き下げたですが、あわせましてこのがんについては先ほども課長がおっしゃっておられました早期発見・早期治療ということが非常に大事であると、全くそのとおりかと思います。","respondent":"太田大井保健相談所長","answer":"建物のライトアップ等を都庁とか東京タワー等を１０月ごろにピンク色にライトアップする。それから啓発講演事業をやるということで、女性に特有の乳がんの早期発見・早期治療ということを目指している運動です。","id":"exchange-113"},{"speaker":"堺委員","kind":"質問・要望","question":"これはやはりこういう常識は変えていかなければならないということをおっしゃりながら、公明党は３年前から最前線で治療に当たっている医師や研究者、患者団体から意見を伺い、またがんの先進的治療の現場を多数視察し、意見交換を重ねてきました。ただ、区についてどうこうとは書いていないんです。ですから、この基本法の策定に伴って、いずれ東京都のほうでもこの基本計画を策定するだろうと。","respondent":"谷田部健康課長","answer":"さきの国会で衆議院・参議院ともに全会一致で可決成立したがん対策基本法ということで私どもも認識はしております。","id":"exchange-114"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひその辺のところは、まだこれから国が、東京都がという段階ですから、そういう答弁にならざるを得ないと十分わかっております。ですから、いずれ区のほうでもということで申し上げたわけですので、ぜひひとつその辺、整合性を持った形で区としても区民の生命を守る意義から検討をしていただきたい、こう思います。このツインキッズの事業の説明と現況について教えていただけますか。","respondent":"川口品川区保健センター保健サービス課長","answer":"で、その実績ですけれども、１７年度、これは年１２回行ってございまして、延べ数で１１６人が参加です。","id":"exchange-115"},{"speaker":"堺委員","kind":"質問","question":"この事業が関係者によりますと大変ありがたいといいますか、感謝されている大変重要な事業で、大変よかったというふうに皆さん参加されている方は喜んでいるわけですが、ある段階から形が変わってきたといいますか、取り組みの内容が変わってきたと申しますか、そういう特に関係者の方々からぜひもとに戻してほしいという意味の改善についてのお願いということでお話が来ていたかと思うんですが。","respondent":"倉橋品川区保健所保健サービス課長","answer":"事業を実施しておりますのが保健所のほうですので、私のほうからお答えします。今、答弁にもありましたとおり多胎児特有の低体重、それから発達・発育等の医学的な問題があるために、育児支援策ではありますが、保健所・保健センター、相談所等で実施しているものです。","id":"exchange-116"},{"speaker":"堺委員","kind":"質問・要望","question":"やはりＯＢとかＯＧと言われる経験者といえども、なかなかそういう場でリーダーシップをとってこういう方々にいわゆるこころを和ませるというのですか、心のケアといいましょうか、そういうことはなかなかできないということで、ぜひこの件についてはもとに戻して改善をしていただきたいですので、そういう方向でぜひお取り組みをしていただきたいと思いますので、もう１回この件について確認をしておきたい。","respondent":"倉橋品川区保健所保健サービス課長","answer":"職員の指導も含めましてボランティア主体の運営を考えておりますけれども、必要に応じまして職員が指導に入り、旧来どおり円滑な実施ができるようにしていきたいと考えております。","id":"exchange-117"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"私のほうからは１３４ページの商店街関係の事業につきましてお伺いをします。そしてまた、ここのところ経済状況も好転をし始めて、ほんとうに商店街のところまでそれが波及しているかどうかということはありますけれども、現状の中で今日の商店街の状況がどういうふうに把握されているかをちょっとお伺いをさせていただきたいと思います。","respondent":"金子産業振興課長","answer":"ご案内のとおり日本国内全体では景気は回復している、あるいは緩やかに回復しているという状況認識をここ７カ月ほど内閣府、あるいは日銀では持っているということから、国全体としてはそうだろうというふうに考えておりますが、私どもでも３カ月に１度。","id":"exchange-118"},{"speaker":"原（雅）委員","kind":"質問","question":"うちの周りの商店街と言ったらいいのでしょうか。そういうふうになってしまいました。それで、果たして区としてそういった元気のない商店街をどういうふうな形で見ていらっしゃるのか。そこのところではその管理、維持が十分に行えないと、そういったところもあるわけで、その辺のところの区としての見解はどういうふうに思っていらっしゃるか。","respondent":"金子産業振興課長","answer":"装飾灯ですか、商店街の装飾灯ですけれども、これについての維持管理、まだ具体的にご相談を承っていないんですけれども、これについて具体的に相談がございましたら、私どもとしても対応の方法を検討していきたいとは思っております。","id":"exchange-119"},{"speaker":"原（雅）委員","kind":"質問","question":"課題として今後に受けとめていくですけれども、じゃあ、元気のない商店街がどのぐらいあるのか調査されたんですか、１００幾つある商店街の中で。その辺のところも含めて、やはり衰退と言ってはよくないでしょうけれども、元気のない商店街を何とか元気が出るようにするような施策を打っているはずですが、全然それが浸透してこないところなんで、ぜひその辺のところのご見解をもう少し聞かせてください。","respondent":"金子産業振興課長","answer":"ただ、商品券につきましては、今、商品券拡大のお店が商店街だけでなくてさまざまなところに拡大しているというふうに聞いておりまして、商店街に加入していなくても、ちょっと手続の面はわかりませんが、商品券は使えるようになっているというふうに聞いておりますので。","id":"exchange-120"},{"speaker":"原（雅）委員","kind":"質問","question":"元気が出ない商店街の話ですが、もう一方で元気をなくしてしまった商店街があるわけです。ぜひその辺のところを今後の中でも、これは回復できるかどうかと非常に地元の方々は心配していました。特に光学通りのところはもうほとんど商店街活動をしておりませんからどうしようもならないという話で、ここのところにはぜひ多彩な支援策というところで十分な援助をしてほしいと思うんですが、いかがでしょうか。","respondent":"金子産業振興課長","answer":"このお尋ねの商店街のところにつきましては、今後地域の皆さんとのご要望についてお伺いする機会を設けていくというふうにまちづくり事業部のほうからも聞いておりますので、その際にご意見をお伺いしながら。","id":"exchange-121"},{"speaker":"原（雅）委員","kind":"質問・要望","question":"ぜひ検討して、多彩な支援策を打っていっていただきたいと要望をしておきます。区長は。それは見たことがないという方が多かったものですから、ぜひそのお答えをもらってきてくれと言われていますので、そのお答えと、それともう一つ商店街振興についてのお考えがありましたらぜひ披露していただきたいと思います。","respondent":"濱野区長","answer":"で、一本橋のことにつきましては、今産業振興課長からお答えしたとおり、今後地元の方との話し合いの中でどういう振興策が有効なのかというようなことは詰めていきたいと考えていますが、私も１０月の初めに各区内をいろいろ回りましたけれども。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"私は成果報告書１２９ページ、資源回収についてと、１２３ページ、休日診療費についてお伺いいたします。品川区資源化センターに５月ごろだと思うんですけれども、視察に行きました。缶の仕分け、自動的にやっていたり、古紙等の仕分け、ペットボトルなんかは手作業で仕分けしておりました。","respondent":"中山資源循環推進課長","answer":"いわゆるリターナブルびん、生きびんでまた売れるものについては、このラインに乗せる前に手作業で分けて、あとは基本的に色別のカレットにするものを今のようなコンテナからおろしておりますので、いわゆる生きびん作業については先に手作業でやっていると、こういうことです。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"ああ、そういうことですか。次に、品川区医師会の協力も得ています小児平日夜間診療事業ですか、これはちょっと平日のことですけれども、平日は月曜日から金曜日、夜間７時半からおおむね１１時ごろまで実施しておりますが、平日の夜間診療は主にどこの先生が担当しているのか、ちょっとそれをお聞かせください。休日診療については専門医は何科になるのか、ちょっとお聞かせください。","respondent":"谷田部健康課長","answer":"それから休日のほうですけれども、休日のほうは品川区医師会、荏原医師会両方にお願いしてございまして、内科と小児科を主に診療科目として実施しているです。ですから、内科、小児科を標榜する先生が詰めてやっているです。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"休日診療、診療日が７２日間で、受診者数が延べ９,３３９名ということでありますが、１日当たり平均で約１３０人ぐらい診察しております。ですが、聞くところによりますと、特に荏原医師会側の休日診療の９割は小児の内科的疾患であり、小児の病気であると聞いていますが、これは間違いないでしょうか。わかりますか。","respondent":"谷田部健康課長","answer":"この７,９４９人のうち小児科にかかわる部分というのは大体６割というふうに私ども伺ってあります。４割は内科系の疾病です。","id":"exchange-125"},{"speaker":"須貝委員","kind":"意見","question":"今、約６割が小児科の担当、小児が来ているという話ですが、今お話を聞いたところによると、内科医も入っていると。実際これだけの子どもたちを扱うということならば、何とかして専門医の小児科の先生を常に配置していくという形が必要だと思うんですが、その辺についてちょっとご見解をお聞かせください。","respondent":"谷田部健康課長","answer":"休日診療、内科、小児科の患者を診ますですから、そこに詰めている先生は内科、小児科を診ることができる先生。診るということを標榜している先生ですので、小児科の先生も当然、詰めていらっしゃるです。","id":"exchange-126"},{"speaker":"須貝委員","kind":"意見","question":"今、詰めていらっしゃるということですが、医者で大人の内科を診る先生と専門医で小児科を診ている先生ですと、やはり子どもの診方というのは全然違うと思うんです。そして、やはり経験則で言えば小児科専門の先生のほうが私は間違いないと思うんですが、その辺ちょっとご見解をお聞かせください。","respondent":"青山品川区保健所長","answer":"実際に休日あるいは平日夜間等に見える方たちの９０％以上、９５％ぐらいはほんとうにちょっと熱が出たとか、そういった昔でしたらおばあちゃんに聞けばわかるような方々がほとんどを占めているということで、その先生方がごらんになって。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと私の聞いたところによりますと、今、先生のおっしゃっていることは先生がおっしゃっているんですからかなり確信が高いと思いますが、ちょっと私も別の方で聞いたら、やはり小児科は小児科の先生をつけたほうがよりいいという話ですけれども、そのときに品川区では荏原医師会では特に５軒ぐらいしか開業医の方が夜間診療を受けてもらっていない。ふだんの日は足りている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"土井委員","kind":"質問・要望","question":"ほとんどだと思いますが、ちょっとそこらは契約的に何台ぐらい、要するに例えば品川区内だときょうは収集ですと何曜日になったら、その日に何台プレス車が動いているのかということがわからないと、ここの区で持っているのとの関係がよく見えないものですから、総額幾らというのは確かに必要でしょうけれども、そこにプレス車何台分ぐらいだろうかということをちょっと聞かせていだたいて。","respondent":"田中環境課長、中山資源循環推進課長","answer":"地元でいろいろな立会川の浄化ですとか、それから生き物の蝶等の自然の回復再生運動をやったりとかいう新しい人たちが環境活動に参加してくるような状況が生まれておりまして、まだ１年ぐらいしかたっていませんが。そのほかに軽自動車が６台、約２０台が直営ですから、１２０分の２０、１００台分が雇上げとかあと直接委託という部分はありますけれども、民間の車両、直営が２０台、このような状況です。","id":"exchange-129"},{"speaker":"土井委員","kind":"意見","question":"プレス車両等についてはわかりましたが、そこで車両等維持管理費のところで災害時対応ということですけれども、他の地区で災害が起こったりしたときいわゆる天然ガス車等では対応できないという問題等があって、ディーゼルもしくはガソリン車等を何台か入れておいていただかないと、他区へ、他のところに災害救助等に行けないということの申し出があったやに思うんですが。","respondent":"中山資源循環推進課長","answer":"それで、新潟まで行く際に航続距離と申しますか走行距離の関係で計算し、プロパンガスにつきましては途中、関越道等沿道にもいわゆる給ガスでしょうか、燃料補給が可能であるということで、現地も十分にこれで対応したということがございました。","id":"exchange-130"},{"speaker":"土井委員","kind":"質問・要望","question":"それからものづくり創造センター等、またベンチャー創業支援等、西大井の場合と天王洲の場合と若干、運営の仕方、運用の仕方が違って進められているわけですけれども、それぞれの中からやはりほんとうにものづくりをこれから進めていくという形の中に生かしていけるような新しいもの、発想、そういうものがどのように出てきているのかということを、どんどん宣伝をしていっていただきたいと思うものですから。","respondent":"金子産業振興課長","answer":"４点ほどのお尋ねだと思いますが、まず２点目の新製品・新技術の開発ですけれども、こっちまでいくとなかなか難しいんですけれども、例えば炭出しロボットの開発ですとか、ちょっと難しいんですけれども、射出成形技術による立体格子状等々との開発等々。","id":"exchange-131"},{"speaker":"土井委員","kind":"質問・要望","question":"だから、その元気とアイデアを出せるようにぜひやっていただきたいという思いを込めてお話をしていますので、よろしくお願いをしたい。そしてそのためにはやはりうまく技術レベルとか、いわゆるコンサルというスタイルでの経営的な面と同時に、技術レベルのバックアップを学校等も含めたところと連携をしていくということもうまく結びつけていただけるようにお願いをしておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"林（宏）委員","kind":"質問","question":"１３１ページの清掃とかリサイクルとかいうところで、時間がないんで端的に聞きますから端的に答えてください。民間でもやっている粗大ごみの収集を、そしていろいろ時間とか日にちとか折り合いがつかなくて、じゃあ、民間に頼めばいいじゃないですかという言葉がある。そこから発想が出たんですけど、もうこの事業は民間移譲されたらどうですか。民間ができる仕事ですから。それについての見解をひとつ。","respondent":"中山資源循環推進課長","answer":"は今の収集の中でいろいろとご意見をいただいているものを、端的に対応できるものからやっていくというのを基本に考えてあります。","id":"exchange-133"},{"speaker":"林（宏）委員","kind":"質問","question":"粗大ごみのほうは公の機関がやらなくてもできる事業という判断はそろそろすべきだろうと僕は思う。それで、職員の方もそういうふうに民間にお頼みしたらいかがですかという言葉が出るぐらいの意欲だから、もう民間に仕事を回すと。その辺は、もちろん今日明日、１年、２年という話ではないけれども、そういう方向を持っておいてほしいと思いますので、新しい区長の決意を伺っておきたいと思います。","respondent":"濱野区長、中山資源循環推進課長","answer":"この清掃一組の今抱えている課題は、例えば負担の公平の問題だとか、それから清掃工場を建設するに際しての住民との協定を今後どうしていくかというようなことだとか非常に重たい課題がありますので。学校の処理機、大規模なものが老朽化して撤去した部分、これは回収してどうしているかといいますと、まとめた形で大型の生ごみ処理機の中で堆肥化なりをするという形になっておりますので、規模の集約性の違いはありますけれども。","id":"exchange-134"},{"speaker":"林（宏）委員","kind":"意見","question":"普及ＰＲ、あれを学校に設置していったときに、いわゆる子どもたちにこういうことで生ごみを処理していくと資源循環型だよというのを見てもらう。実際に体験してもらう。それが一因である、それだけじゃないけれども。関連だから一つだけここで。ぜひ普通のフェイス・トゥ・フェイスの見本市を忘れないでほしい。忘れないでほしい。覚えておいてくださいという聞き方をしますから、覚えておいてくれますか。","respondent":"金子産業振興課長","answer":"前回、あるいは前々回のこの特別委員会でもそういうご意見ないし要望があったということはしっかり記憶しています。","id":"exchange-135"},{"speaker":"三上委員","kind":"質問","question":"１２８ページのノーレジ袋運動、それから１２９ページの屋上緑化、それからその下の低公害車導入、簡単にお伺いしていきたいと思います。その時代から少しずつでも何らかの形でこの低公害車的な部分の取り組み方というのを品川区はしようとしてきているけれども、現実に低公害車と言われる部分について今、現実はどうなっているのか、ここらあたりちょっと簡単でいいですからお伺いしたい。","respondent":"田中環境課長、藤田道路公園課長","answer":"レジ袋を今後どう考えていくのかというお尋ねですが、容器包装リサイクル法が改正されまして、政省令の改正が１２月に交付予定になっております。今後、２０１０年を目標に１４％まで拡大をしていきたいというふうに考えているところです。庁有車ですが、今委員ご指摘のようにディーゼルですとかそういうものについては当然、対応してきておりまして、低公害車、東京都の指定する低公害車の導入。","id":"exchange-136"},{"speaker":"三上委員","kind":"質問・要望","question":"ここらあたりは時間がありませんからお伺いしませんけれども、ぜひそういう進め方をお願いしたいとこう思います。だから、そういう古い車についての切りかえ的な部分についてのそういった考え方で、やはり先をいって取りかえていくということをちょっと考えていっていただきたいと思いますが、そこのところだけちょっといかがでしょうか。","respondent":"中島経理課長","answer":"庁有車の低公害車の導入ですけれども、この間、順次切りかえてございまして、現在１６５台中４９台が低公害車です。これから車検の切替時にはハイブリッド車を含めまして、積極的に導入してまいりたいというふうに考えてあります。","id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は成果報告書１３４ページの商店街振興事業について伺いたいと思います。初めに、先ほど原委員の質問で装飾灯の件で質問がありました。具体的に個別に相談に乗りたいというような答弁だったかと思いますけれども、ちょっとそこら辺のところの内容を確認させていただきたいんですが、よろしくお願いします。","respondent":"金子産業振興課長","answer":"先ほどの答弁についてのお尋ねですが、あそこの一本橋商店街のところのお尋ねにお答えしたもので、近々、先ほどもお答えしたとおり会合を持たれるというふうに聞いておりまして、それに私どものほうも出席して、具体的なご意見・ご要望等を伺って。","id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問","question":"今、電気代のほうの補助は平成１１年からだったと思うんですけれども、補助額が改定になりまして、今は１本５,６００円、年間の補助というふうになっていたと思うんですが、区のほうの考え方のところでは、防犯の役割を果たしている。しかし、そうですけれども、装飾灯の補助というのは私はそろそろ増額を検討する時期に来ているんじゃないかと思うんですが、そこら辺のところの区のお考えはどうでしょうか。","respondent":"金子産業振興課長","answer":"２点目のほうからお答え申し上げますが、２点目の装飾代の補助の増額ということですが、今現在どうしても装飾灯の個々の電気代、例えば新しいものについてはあまり電気がかからないとか、一つでかなり電気を食うもの、タイプの違いがありますので。","id":"exchange-139"},{"speaker":"宮崎委員","kind":"質問","question":"そういう意味では、先ほどもご説明があった平均で３０％前後というところよりはいいんだろうとは思うんですけれども、でもやはりいろいろ先ほども言いましたけれども、商店会のスタイルといいますか、例えば駅に近いところ、遠いところ、いろいろスタイルがあってまた考え方も違うんですけれども。","respondent":"金子産業振興課長","answer":"ただ私どもとしましては、この装飾灯維持管理補助事業というものについてもやはり一定の公平性は持っていかなければならないということで、その意味で１本の単価、委員ご指摘のとおり５,６００円、アーチについてはその倍というような設定をしておりますので。","id":"exchange-140"},{"speaker":"宮崎委員","kind":"質問","question":"そういう中でもせめて電気代は払ってくれということでやって非常に努力はしているんですけれども、商店街自身が後継者もいない非常に厳しい中で頑張っても、なかなかいわゆるイベント、元気を出す商店街でいわゆるイベントに補助をするというだけじゃなくて、商店街振興そのものを底上げしていくという考え方を持っていく必要があると思いますけれども、そこのところはどうでしょうか。","respondent":"金子産業振興課長","answer":"委員ご指摘のところと少しずれるかもしれませんが、小規模商店街についてもそれなりのメニューも持っていますので、その意味では現在のところ商店街の振興という意味では大きく不足しているといいますか、一定程度メニューとしては充足しているというふうに考えてあります。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この点は改めて見直しを強く求めておきたいと思います。ちょっと質問を変えますけれども、区内の小売店、今は大型店もどんどん出てきておりまして、百反通りのところにライフだとか、宮前商店会のところにオオゼキとか、ここのところ相次いでオープンしていますけれども、今、区内の小売店の面積の中で大型店の占める割合、店舗、この数というのを改めて聞いておきたいと思うですがどうでしょうか。","respondent":"金子産業振興課長","answer":"区内の大型店の面積の割合ということですけれども、今、それは持ち合わせておりませんが、１,０００m2以上の大型店につきましては、委員ご指摘のとおり先ごろライフの大崎店ができましたので、２４店から２５店に増えているという状況はあります。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ面積のがあとでわかりましたらお願いしたいと思うんですが、このところもうずっと増えてきているというのは、この間、説明でもありました。ぜひ現状をお知らせいただきたいと思います。事業概要のところでは大型店の出店に関する連絡調整ということをやる事業説明なんかあるんですけれども、そういう意味ではどんなことをやっているのか、具体的な実績等あったら説明いただきたいと思います。","respondent":"金子産業振興課長","answer":"具体的に先ほど出ましたライフに関しましては１,０００m2を超えていますので東京都の調整でありますが、私どもも同席しまして、まず具体的な出店の概要を出店者の側からお聞きして、なおかつその後、地元説明会を開かせておりますので、その地元説明会の中の概要をお聞きして。","id":"exchange-143"},{"speaker":"宮崎委員","kind":"質問","question":"時間も少なくなってきたんですが、今、非常に商店会も厳しくなってきて、先日ある新聞ですけれども、武蔵小山のことですが、２５０店あるうち１００店がもうチェーン店になっているとそういう報道もありました。今、商店街をめぐる状況というのはやはり非常に厳しくなってきている。この点については重ねて検討いただくということをお願いいたしまして、質問を終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"須藤委員","kind":"質問","question":"片一方は１３１所帯、費用的にも地区栄養調査のほうが１世帯３万４,０００というような費用になっているんですが、そのあたりの状況、それからもう少し下の方の２１世紀成年者縦断調査というのと、中高年者縦断調査というのが出てきているですけれども、これもどんな調査で、全国的にどういう目的で、何を得ようとしていのか、そのあたりを教えてください。","respondent":"谷田部健康課長","answer":"それから中高年縦断調査ですけれども、これは１７年度から毎年実施するために行われているものですけれども、これもちょっと似たような話ですが、調査対象になった男女の健康、就業、社会活動につきまして、意識面、事実面の変化の過程を継続的に調査し、高齢者対策等。","id":"exchange-145"},{"speaker":"須藤委員","kind":"質問","question":"国のほうで基礎的なデータを集めてくるということで理解をしました。これらを何年になって、また発表になってというのが区のほうである程度、その辺がつかめてくるのかどうか、その年度年度でやったものの結果が報告があるのかどうか教えてください。","respondent":"谷田部健康課長","answer":"結果につきましては分厚い資料で健康課のほうに参りまして、私ども参考になるところは参考にしまして、この調査結果につきましては区の施策のほうにも参考資料として活用はしているです。","id":"exchange-146"},{"speaker":"須藤委員","kind":"質問・要望","question":"これだけじゃないんですけれども、いろんな区で区民に調査が依頼があったりなんかしているんですけれども、その結果が今度はどうなったかというのがなかなか我々議会でも出てこない状況なんで、できましたらせっかくこういった調査をされて、いいデータなり何なりが国の上がってきたものが整理できましたら、議会のほうにも報告していただきたいと思いますが、これは要望しておきます。","respondent":"川口品川区保健センター保健サービス課長","answer":"ただいまの新聞で健康日本２１の項目別ということでのお話だと承ってありますけれども、今委員おっしゃいましたけれども、実は項目の数ということではちょっと把握してございません。","id":"exchange-147"},{"speaker":"須藤委員","kind":"質問","question":"報告になるとなかなか２０００年にスタートした方向性が、歯のほうは８０２０、８０歳２０本というのは目標を達成した。あるいは虫歯についても達成したというようなことがあるけれども、ほかの項目についてはなかなかいい結果にならない。逆に悪くなっていますというような数値があるんだけれども、きのうの発表では。品川区の状況はいかがでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"ただいま委員のお話で承りましたけれども、改善したということは歯科の２項目、それと悪化したということが肥満、それから食事についての事項だと認識しています。","id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"区内で数値を立てていないから、健康状態が一生懸命朝から健康についてということでここでいろいろ質疑しているんですけれども、努力をしていても違う方向にいってきているという状況であれば、抜本的に何か考え方を変えなきゃいけないんじゃないかという数値目標とか健康のあり方というものの考え方を変えなきゃいけないんじゃないかと思うんですけれども、そのあたりいかがでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"ただいまもご答弁させていただきましたけれども、数値目標は立ててございません。ただ、本区では先ほどからご議論がございました区民健康診査等々を実施していますので、その数値で１７年度、それからその前年度を比較しています。","id":"exchange-149"},{"speaker":"須藤委員","kind":"意見","question":"環境対策費のところでもう時間がないんで、これが品川区の大気汚染だとか環境情報活動センター等々で得られた情報が保健所等と連携がきちんと取れているのかどうか、それともう一つは総務のほうで町会の美化推進とか環境整備とかというのが総務のほうで各町会に出されているですが、そのあたりの連携が環境課のほうとどういうふうに、あるいは保健所とどう連携されているのかお知らせください。","respondent":"田中環境課長","answer":"美化の運動等につきまして今月の２１日号の広報に環境大賞を公募するという記事が出ますが、地域活動課、それから道路公園課等の各所管と連携しまして、緑のボランティアの人たち、それから町会で長い間、美化活動をやっている方たちを含めて。","id":"exchange-150"},{"speaker":"須藤委員","kind":"質問・要望","question":"環境情報活動センターが開きまして、そこに市民の方々がいろんな情報を持ってくる。そういうものがきちんと保健所に情報が行ったりするということが必要だろうと思うんで、そのあたりも連携をせっかくできましたんで、上手にとっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/249249?Template=document&Id=1266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":116097,"voices":347}}]);
